// Fortuitous encounters, second volume: the genre's lucky breaks and what they cost. Hidden caves, dying
// masters, spirit beasts, thousand-year herbs, cliffs, ruins, tombs, maps, teahouse sages, cursed things,
// omens, fated meetings, and the regressor's unfair advantage of simply remembering where things are.
// Flags use the "fo." prefix; codex entries defined here use "secret.fo_…".
// Price mechanics used here: 'longevity±=n' (lifespan years), 'fo.luck' (accumulated good fortune; at 3+
// the world collects), 'fo.whispers' (word of a treasure spreads; hunters follow), gaze and burden.
import { E, O, C, R, P, M, Q, L, LATER } from './kit.js';
import { template } from '../../engine/registry.js';

const HAND = [
  // ── The weeping saber (a cursed blade, three beats) ─────────────
  E('fo_weeping_saber', 'fortune', { if: { locType: 'city', age: [16, 70], stat: { wealth: '>=5' }, chance: 0.4 }, art: 'market', title: 'The pawnshop saber', text: 'At the back of a pawnshop hangs a saber wrapped in yellow talismans. The owner offers it for eight taels, and then, when you hesitate, for five. "It was my brother’s," he says. "Then my cousin’s. Then a customer’s. They all came back to sell it."', choices: [
    Q('Buy it (5 taels)', { stat: { wealth: '>=5' } }, O('You bought it. The talismans crackled when you touched them. The pawnbroker bowed you out of the shop and locked the door behind you, at noon.', { wealth: -5, item: { heavy_saber: 1 }, flag: 'fo.weeping' })),
    C('Ask what happened to them', O('"Nothing," he said. "They just stopped sleeping." You did not buy it. You dreamed about it anyway.', { sanity: -1, insight: 1 })),
    C('Leave', O('You left. Some bargains are a shop’s way of asking for help.')),
  ] }),
  E('fo_weeping_night', 'fortune', { if: { flag: 'fo.weeping', not: ['fo.weeping_done', 'fo.weeping_n>=2'], age: [16, 80] }, once: false, cd: 2, art: 'night', text: 'Past midnight, the saber under your bed is weeping: a thin, wet sound, like someone trying not to be heard. The talismans are curling at the edges.', choices: [
    R('Listen to it', 'sanity', 55, O('You listened until dawn. It was a woman’s voice, telling you how to hold it. In the morning your hands knew three new cuts.', { insight: 3, qi: 10, sanity: -4, flag: 'fo.weeping_n+=1' }), O('You listened until you were weeping too, and could not remember why.', { sanity: -10, flag: 'fo.weeping_n+=1' })),
    C('Wrap it in fresh talismans', O('You bought fresh talismans from a Daoist who would not meet your eyes. The saber went quiet. For now.', { wealth: -3 })),
    C('Throw it in the river', O('You threw it in the river. The next morning it was leaning against your door, dripping.', { sanity: -5, flag: 'fo.weeping_n+=1' })),
  ] }),
  E('fo_weeping_end', 'fortune', { if: { flag: ['fo.weeping', 'fo.weeping_n>=2'], not: 'fo.weeping_done', age: [16, 80] }, art: 'night', title: 'Her name', text: 'The weeping stops. In the silence a woman’s voice says, quite clearly: "Seo Wol-ha. That was my name. My husband forged me into this blade so that I could never leave him. Will you let me go, or keep me, as he did?"', choices: [
    C('Keep the blade', O('"So you are like him," she said, and then nothing more, ever. The saber is lighter now, and hungrier, and it cuts like grief.', { qiFill: 25, mastery: { uno_blood_saber: 15, paeng_tiger_saber: 15, court_guard_saber: 15 }, sanity: -10, infamy: 2, flag: 'fo.weeping_done' })),
    C('Carry it to Mount Song to be released', O('The monks chanted over it for nine days. On the ninth, the talismans burned away by themselves and the steel was only steel. An old monk told you she had said thank you. You chose to believe him.', { travel: 'songshan', take: { heavy_saber: 1 }, sanity: 10, rep: { orthodox: 4 }, flag: 'fo.weeping_done' })),
    R('Break it over your knee', 'body', 40, O('It broke with a sound like a sigh. Something warm brushed your cheek and was gone.', { take: { heavy_saber: 1 }, sanity: 12, insight: 2, flag: 'fo.weeping_done' }), O('It did not break. Your knee very nearly did.', { injury: { name: 'cracked kneecap', seasons: 4, sev: 8 } })),
  ] }),

  // ── The fox on the grave (a favour, and the bill) ───────────────
  E('fo_fox_grave', 'fortune', { if: { region: ['guanzhong', 'shu', 'jingchu'], age: [14, 60], chance: 0.35 }, art: 'moon', title: '“Do I look like a person?”', text: 'On a grave mound under the moon sits a white fox with its paws folded like a lady’s hands. It speaks in a young woman’s voice. "Traveller. Tell me truly. Do I look like a person?"', choices: [
    C('"Yes. You look like a person."', O('The fox laughed with delight and turned three somersaults on the grave. "Then I owe you," she said. "I always collect what I owe, and what I am owed." She was gone before you could ask what that meant.', { flag: 'fo.fox_favor', charm: 2, next: { id: 'fo_fox_due', in: 16 } })),
    C('"No. You look like a fox."', O('"Rude," said the fox, and bit your ankle, and vanished. The bite healed badly. You still limp in the rain, and you are not sorry.', { injury: { name: 'fox bite', seasons: 8, sev: 6 }, insight: 2 })),
    C('Walk past without answering', O('You walked past. Behind you, the fox asked the next traveller, and the next.')),
  ] }),
  L('fo_fox_gift', 'fortune', { flag: 'fo.fox_favor', not: 'fo.fox_paid', age: [14, 80] }, 'You woke to find a little pile of things on your doorstep: a pill wrapped in a leaf, a silver hairpin, and one small paw print in the dust.', { item: { qi_pill: 1 }, wealth: 6 }, { once: false, cd: 2 }),
  E('fo_fox_due', 'fortune', { on: 'scheduled', if: { flag: 'fo.fox_favor' }, art: 'moon', title: 'The fox collects', text: 'The white fox sits at the foot of your bed, looking very much like a person now. "Four years of luck," she says pleasantly. "Now I would like four years of your life. Only the ones at the end. You will hardly miss them."', choices: [
    C('Pay her', O('She leaned close and breathed in, and something left you that you could not name. "Generous," she said. "Most people argue." You feel exactly the same. You are fairly sure you are not.', { flag: ['longevity-=4', 'fo.fox_paid'], unflag: 'fo.fox_favor', sanity: -3 })),
    R('Argue the terms', 'charm', 35, O('You argued until dawn. She was delighted. In the end she took a single year and a jar of wine, and called you her best customer in a century.', { flag: ['longevity-=1', 'fo.fox_paid'], unflag: 'fo.fox_favor', charm: 2 }), O('She listened patiently, then took five years instead of four. "Interest," she said.', { flag: ['longevity-=5', 'fo.fox_paid'], unflag: 'fo.fox_favor' })),
    C('Refuse', O('"Then I will take it back the other way," she said. Your luck curdled. For a year, everything you touched broke, and everyone you trusted lied.', { unflag: 'fo.fox_favor', flag: ['fo.fox_paid', 'fo.luck+=3'], wealth: -20, sanity: -8 })),
  ] }),

  // ── The price of good fortune ───────────────────────────────────
  E('fo_luck_turns', 'fortune', { if: { flag: 'fo.luck>=3', age: [14, 200] }, once: false, cd: 6, title: 'Heaven keeps accounts', text: 'Ever since your good fortune began, the world has been keeping accounts. A roof tile misses you by a hand’s breadth. A horse bolts. A fortune-teller takes one look at your face and refuses your money.', choices: [
    Q('Give a third of your silver to a temple', { stat: { wealth: '>=30' } }, O('You gave it to the Daoists on the hill, who did not ask why. The tiles stayed on the roofs after that.', { wealth: -30, flag: 'fo.luck=0', sanity: 4 })),
    P('Ride it out', 0.5, O('Nothing worse happened. The world, apparently, had made its point.', { flag: 'fo.luck=1' }), O('The horse that bolted was yours, and you were on it.', { injury: { name: 'broken arm', seasons: 6, sev: 12 }, flag: 'fo.luck=0' })),
    C('Throw a feast for the neighbours', O('You fed the whole street. Good fortune shared, the old women said, is good fortune halved, and safe.', { wealth: -15, fame: 2, flag: 'fo.luck-=2' })),
  ] }),
  E('fo_whispers', 'fortune', { if: { flag: 'fo.whispers', age: [16, 80], chance: 0.6 }, once: false, cd: 3, danger: true, art: 'inn', title: 'Word gets around', text: 'Three strangers in travel-stained clothes take the table next to yours and talk loudly about nothing. One keeps looking at your pack. Word of your luck has travelled faster than you did.', choices: [
    C('Confront them outside', O('They were waiting for that.', { combat: { foe: { name: 'a treasure hunter', kind: 'bandit', rel: 0 }, context: 'ambush', lethal: 0.25, win: { text: 'They will tell everyone your luck comes with teeth. That is a kind of protection too.', fame: 2, unflag: 'fo.whispers' }, lose: { text: 'They took your purse and most of your dignity, and left you in the mud.', wealth: -30, unflag: 'fo.whispers' } } })),
    R('Slip out the back before dawn', 'body', 25, O('You were three valleys away before they finished breakfast.', { unflag: 'fo.whispers', body: 1 }), O('They were waiting at the back, too. You paid them to go away.', { wealth: -20, unflag: 'fo.whispers' })),
    R('Buy them a round and tell them a better rumour', 'charm', 30, O('You told them about a jar of gold under a pagoda in Kaifeng. They left at a run. Somewhere in Kaifeng, a pagoda is about to have a bad week.', { wealth: -2, unflag: 'fo.whispers', charm: 1 }), O('They laughed at your story, drank your wine, and kept watching.', { wealth: -2 })),
  ] }),

  // ── A dying demon ───────────────────────────────────────────────
  E('fo_demon_qi', 'fortune', { if: { region: ['guanzhong', 'west'], age: [14, 60], notSect: 'cult', chance: 0.3 }, art: 'snow', title: 'Red eyes in the snow', text: 'A man in a torn red robe sits against a boulder in the snow, holding his stomach together. His eyes are the colour of old blood. "Orthodox?" he rasps. "Doesn’t matter. Thirty years of qi, and nobody to give it to. Give me your hand."', choices: [
    C('Give him your hand', O('He poured it into you like a river through a broken dam. When it was over he was dead and smiling, and your veins were black for three days.', { qiFill: 45, sanity: -8, flag: 'fo.demon_qi' })),
    C('Give him water instead', O('He laughed and drank. "Soft," he said. "That is how the Orthodox will lose." He died before the cup was empty.', { sanity: 2 })),
    C('Finish him', O('One stroke. He did not resist. Somewhere, you suspect, someone will have opinions about that.', { fame: 2, rep: { orthodox: 2, cult: -5 }, sanity: -3 })),
  ] }),
  E('fo_demon_qi_found', 'fortune', { if: { flag: 'fo.demon_qi', not: 'fo.demon_qi_done', age: [14, 80], or: [{ faction: 'orthodox' }, { locType: 'sect' }] }, art: 'temple', text: 'An old monk passing on the road stops dead and looks at you. "There is something red asleep in your dantian," he says. "It is not yours. It will wake."', choices: [
    C('Let him purge it', O('He pressed his palm to your back for an hour. You vomited something black. You are weaker for it, and lighter, and you sleep through the night again.', { health: -10, sanity: 10, unflag: 'fo.demon_qi', flag: 'fo.demon_qi_done' })),
    R('Tame it yourself', 'sanity', 60, O('You sat with the red thing for a season and taught it your name. It answers to you now. Mostly.', { qiFill: 25, insight: 3, flag: 'fo.demon_qi_done' }), O('It woke first. For a month you were not entirely yourself, and the people around you noticed.', { sanity: -15, infamy: 4, rep: { orthodox: -5 }, flag: 'fo.demon_qi_done' })),
    C('Walk on', O('"It will wake," he called after you. You walked faster.', { sanity: -2 })),
  ] }),

  // ── Thresholds crossed by someone else’s gift (very rare) ───────
  E('fo_hermit_transfer', 'fortune', { if: { age: [20, 120], realm: [2, 6], bottleneck: true, locType: ['wild', 'sect', 'frontier'], stat: { health: '>=55' }, chance: 0.15 }, danger: true, art: 'mountain', title: 'The last of a lineage', text: 'In a hut above the cloud line an old woman lies on a straw mat, so thin the light comes through her hands. "I have been waiting for someone standing at a threshold," she says. "My qi is too much to take into the ground. Carry it across for me. It will hurt you. It hurt me."', choices: [
    R('Take her qi', 'health', 55, O('It was like swallowing a sunrise. Your dantian cracked, and held, and opened onto a realm you had never reached. She died while you were still screaming. You buried her above the clouds.', { realmUp: true, sanity: -10, burden: 1, flag: 'fo.luck+=2' }), O('It was too much. You held what you could and let the rest burn out through your meridians. She died disappointed. You will live, eventually.', { health: -30, qiFill: 30, injury: { name: 'scorched meridians', seasons: 8, sev: 10 } })),
    C('Refuse; it should go into the ground with her', O('"Proud," she said, and then, "Good." She told you stories about her own master until she fell asleep and did not wake.', { insight: 4, sanity: 3 })),
  ] }),
  E('fo_blood_bodhi', 'fortune', { if: { age: [16, 150], realm: [1, 5], bottleneck: true, region: ['shu', 'jingchu', 'west'], locType: ['wild', 'sect', 'frontier'], stat: { health: '>=45' }, chance: 0.12 }, danger: true, art: 'forest', title: 'The Blood Bodhi', text: 'A tree with white bark and leaves like small hands grows alone in a burnt clearing. A single red fruit hangs from it, pulsing faintly, like a heart. Every animal skeleton in the clearing faces it.', choices: [
    R('Eat it', 'body', 35, O('It was sweet, and then it was fire. You broke through the threshold before you knew you had sat down. The tree withered as you watched.', { realmUp: true, gaze: 1, sanity: -6, flag: 'fo.luck+=2' }), O('It was sweet, and then it was fire, and the fire did not stop. You woke a week later with your hair white at the temples.', { health: -30, qiFill: 40, sanity: -5 })),
    C('Pick it to sell', O('It rotted in your pack within a day, leaving a stain shaped like a hand. The buyer in the next town laughed at you.', { insight: 1 })),
    C('Leave it for whatever the skeletons were waiting for', O('You left. Something large moved in the trees behind you, toward the clearing.', { sanity: 1 })),
  ] }),

  // ── Herbs, and the people who also want them ───────────────────
  E('fo_herb_wait', 'fortune', { if: { locType: ['wild', 'sect'], age: [14, 70], not: 'fo.herb_watch', chance: 0.4 }, art: 'forest', title: 'Not yet ripe', text: 'On a dead pine you find a Nine-Leaf Purple Ganoderma a hand’s width from ripeness. Picked now, it is merely valuable. Ripe, in a year, it is priceless. Other people know how to count, too.', choices: [
    C('Camp beside it and wait', O('You built a lean-to, hid the ganoderma under bark, and settled in to guard it.', { flag: 'fo.herb_watch', next: { id: 'fo_herb_ripe', in: 4 } })),
    C('Pick it now', O('You picked it and sold it in the next town for a respectable sum.', { wealth: 50 })),
    C('Leave it for someone who needs it more', O('You left it. Somewhere, perhaps, an old woman with a cough found it next spring.', { sanity: 3 })),
  ] }),
  E('fo_herb_ripe', 'fortune', { on: 'scheduled', if: { flag: 'fo.herb_watch' }, danger: true, art: 'forest', title: 'Ripe', text: 'The ganoderma has turned the colour of a bruise and smells of rain. You are reaching for it when a voice behind you says, "Thank you for minding it. We will take it from here." Two men in grey, with swords.', choices: [
    C('Fight for it', O('You had waited a year. You were not leaving.', { combat: { foe: { name: 'a herb thief', kind: 'bandit', rel: 0 }, context: 'duel', lethal: 0.15, win: { text: 'They fled. You ate the ganoderma on the spot, still breathing hard, and felt a decade of qi settle into your dantian.', qiFill: 50, flag: 'longevity+=3', unflag: 'fo.herb_watch' }, lose: { text: 'They took it, and thanked you again, politely. That was the worst part.', unflag: 'fo.herb_watch', sanity: -5 } } })),
    R('Snatch it and run', 'body', 35, O('You ate it while running. It was the best thing you have ever tasted, in the worst circumstances.', { qiFill: 40, flag: 'longevity+=2', unflag: 'fo.herb_watch' }), O('You tripped over your own lean-to. They stepped over you on their way out.', { health: -8, unflag: 'fo.herb_watch' })),
    R('Offer to split it', 'charm', 30, O('They looked at each other and shrugged. Half a miracle is still a miracle.', { qiFill: 20, flag: 'longevity+=1', unflag: 'fo.herb_watch' }), O('"Why would we split it?" one of them asked, reasonably, and took it.', { unflag: 'fo.herb_watch', sanity: -3 })),
  ] }),
  E('fo_twin_mushrooms', 'fortune', { if: { locType: ['wild', 'sect'], age: [12, 70], stat: { health: '>=40' }, chance: 0.35 }, danger: true, art: 'forest', title: 'One for a hundred years', text: 'Two red mushrooms grow from a single root, identical down to the white freckles. A hunters’ rhyme goes: one for a hundred years, one for a hundred breaths.', choices: [
    R('Study them, then choose', 'insight', 35, O('The left one smelled faintly of almonds. You ate the right one. Warmth spread through your meridians like spring water.', { qi: 20, health: 10, flag: 'longevity+=1' }), O('You chose wrong. The hundred breaths were the longest of your life, and a passing herb-woman saved you with a spoonful of something foul.', { health: -25, sanity: -4 })),
    P('Eat one at random', 0.5, O('Warmth, then a deep, bone-level ease. You chose right, for no reason at all.', { qi: 20, health: 10, flag: 'longevity+=1' }), O('Wrong one. You spent a week on your back, sweating colours.', { health: -30 })),
    C('Eat neither', O('You ate neither. You are not that kind of gambler.')),
  ] }),
  E('fo_fake_ginseng', 'fortune', { if: { locType: 'city', age: [16, 80], stat: { wealth: '>=50' }, chance: 0.4 }, art: 'market', text: 'A herbalist unwraps red silk to show you a thousand-year ginseng shaped like a little man, root-hairs like a beard. Only fifty taels, he says, because his son is getting married and he needs the money quickly.', choices: [
    R('Examine it closely before paying', 'insight', 35, O('It was a carved radish, very well carved, with goat hair glued on for a beard. You did not buy it. You did buy him a drink, because it was really very good work.', { insight: 2, wealth: -1 }), O('You examined it closely and bought it. It was a carved radish. The beard came off in the soup.', { wealth: -50, insight: 1 })),
    C('Decline', O('You declined. He sold it to the next man for forty.')),
  ] }),

  // ── The Ghost Market bundle (first life, then the shortcut) ─────
  E('fo_ghost_stall', 'fortune', { if: { loc: 'kaifeng', age: [12, 50], year: [10, 30] }, art: 'market', title: 'The Ghost Market', text: 'In the Ghost Market, which opens only after midnight, a half-blind old woman sells bundles of junk scrolls by weight: almanacs, ledgers and bad poetry, tied up with string.', choices: [
    Q('Buy a bundle (3 taels)', { stat: { wealth: '>=3' } }, O('Almanacs, the ledger of a long-closed brothel, and some truly appalling poetry. You laughed for an evening, which is worth three taels.', { wealth: -3, sanity: 2 })),
    C('Move on', O('You moved on. Behind you, a scruffy young man bought the bundle tied with red string and walked off whistling.')),
    M('Buy the bundle tied with red string', 'secret.fo_ghost_scroll', O('Between two almanacs, a stained manual: the Reversed Meridian Step. The scruffy young man who should have bought it arrived as you were leaving, and looked at you as if you had stolen his life. In a way, you had.', { wealth: -3, manual: 'lost_reversed_step', gaze: 1 }), { show: { noManual: 'lost_reversed_step' } }),
  ] }),
  E('fo_ghost_legend', 'fortune', { if: { locType: 'city', age: [20, 90], year: [30, 90], noMem: 'secret.fo_ghost_scroll', chance: 0.4 }, art: 'inn', text: 'A teahouse storyteller tells the tale of Cha Mu-gyeong, the Reversed Meridian, a nobody until he bought a bundle of junk scrolls in the Kaifeng Ghost Market for three taels and found a lost art inside.', choices: [
    C('Buy the storyteller a drink for the details', O('"Year twenty, give or take," he said. "A blind old woman’s stall. He always said it was the red string that caught his eye." You found yourself remembering it very carefully.', { wealth: -1, codex: { id: 'secret.fo_ghost_scroll', cat: 'secrets', title: 'The bundle with red string', text: 'Between years 10 and 30, a half-blind old woman in the Kaifeng Ghost Market sells junk scrolls by weight. The bundle tied with red string holds the Reversed Meridian Step.' } })),
    C('Leave before the moral', O('You left before the moral. There is always a moral.')),
  ] }),

  // ── Black Pine Ridge (first life, then the shortcut) ────────────
  E('fo_black_pine_rumor', 'fortune', { if: { region: 'hebei', age: [16, 90], year: [23, 70], noMem: 'secret.fo_black_pine', chance: 0.5 }, art: 'inn', text: 'A bandit drinking his share boasts that the Green Forest dug up a thousand-year ginseng on Black Pine Ridge, the spring before last, and sold it to an Eastern Depot eunuch for a thousand taels. "Shaped like a little old man," he says. "It screamed when we pulled it."', choices: [
    R('Ask exactly where', 'charm', 25, O('He drew it for you in spilt wine: the north face, under the split pine, where the snow melts first.', { codex: { id: 'secret.fo_black_pine', cat: 'secrets', title: 'Black Pine Ridge', text: 'A Thousand-Year Spirit Ginseng grows on Black Pine Ridge in the Taihang, under the split pine on the north face. The Green Forest digs it up in the spring of year 22.' } }), O('He told you to mind your own business, with a knife for emphasis.', { health: -3 })),
    C('Drink and say nothing', O('You drank and said nothing. The ginseng, after all, is gone.')),
  ] }),
  E('fo_black_pine_dig', 'fortune', { if: { ...LATER, mem: 'secret.fo_black_pine', year: [8, 22], age: [10, 60], region: ['hebei', 'central'] }, art: 'mountain', title: 'Black Pine Ridge', text: 'You remember a bandit’s boast about Black Pine Ridge, and a ginseng that screamed. In this life, it is still in the ground.', choices: [
    R('Dig it up before the Green Forest does', 'insight', 25, O('Under the split pine, where the snow melts first. It did scream, a little. You wrapped it in red cloth and were off the mountain before anyone heard.', { item: { spirit_ginseng: 1 }, travel: 'taihang', gaze: 1, flag: 'fo.luck+=1' }), O('You found it, and so did a Green Forest patrol. You got away with the ginseng and an arrow in your shoulder.', { item: { spirit_ginseng: 1 }, travel: 'taihang', injury: { name: 'arrow wound', seasons: 4, sev: 12 }, rep: { unorthodox: -5 }, gaze: 1 })),
    C('Sell the location to the Green Forest', O('The Mountain Tiger’s men paid well and asked no questions. They will dig it up a few years early. History is very slightly different, and you are richer.', { wealth: 120, rep: { unorthodox: 6 } })),
    C('Let it grow', O('Let it grow. A thousand years is a long time; a few more will not hurt it.')),
  ] }),

  // ── What the flood uncovered ────────────────────────────────────
  E('fo_flood_tomb', 'fortune', { if: { happened: 'yellow_flood', region: 'central', year: [8, 14], age: [10, 70] }, art: 'flood', title: 'What the river uncovered', text: 'Where the flood tore away the riverbank east of Kaifeng, a wall of grey bricks stands exposed in the mud. Children dare each other to touch it. One brick has already fallen out, and the hole breathes cold air.', choices: [
    R('Crawl in', 'body', 25, O('A general of some forgotten dynasty lay in lacquered armour, hands folded over a bronze box. Around him, gold. You took what you could carry and told no one, which did not stop everyone finding out.', { wealth: 90, qi: 10, flag: ['fo.whispers', 'fo.luck+=1'], codex: { id: 'secret.fo_flood_tomb', cat: 'secrets', title: 'The general in the riverbank', text: 'East of Kaifeng, the riverbank hides a forgotten general’s tomb full of gold. The flood of year 8 exposes it; without the flood, dig at the third willow below the ferry.' } }), O('The bricks shifted and the river came in after you. You got out. The tomb did not.', { health: -15 })),
    C('Report it to the magistrate', O('The magistrate sealed it, emptied it, and reported to the capital that it had been empty. He gave you one tael for your honesty.', { wealth: 1, rep: { court: 2 } })),
  ] }),
  E('fo_flood_tomb_mem', 'fortune', { if: { ...LATER, mem: 'secret.fo_flood_tomb', region: 'central', age: [12, 70] }, art: 'river', text: 'You remember a general’s tomb in the riverbank east of Kaifeng, from a life in which the river opened it for you. In this one, you will need a shovel.', choices: [
    C('Dig at the third willow, and take only the gold', O('Two nights of digging. The general was where you left him, so to speak. You took the gold and left him his box, out of a strange sense of courtesy.', { wealth: 90, gaze: 1 })),
    C('Take the box too', O('The box held a treatise on breathing for men who must fight all day, and a letter to the general’s wife that he never sent. You read both. You wish you had read only one.', { wealth: 90, qi: 15, sanity: -3, gaze: 1 })),
    C('Leave him to sleep', O('You left him. Gold that waits a thousand years can wait a little longer.', { sanity: 2 })),
  ] }),

  // ── The Qingcheng founder’s cell ────────────────────────────────
  E('fo_qing_founder', 'fortune', { if: { happened: 'shu_quake', loc: 'qingcheng', year: [80, 120], age: [14, 150] }, art: 'mountain', title: 'The broken peak', text: 'The earthquake split Mount Qingcheng’s western peak like a melon. In the raw rock, halfway up, there is a square doorway that nobody carved in living memory.', choices: [
    R('Climb to it', 'body', 40, O('Inside: a cell, a stone bed, and a thousand needles of green jade set into the wall in the shape of falling rain. The Qingcheng founder’s practice room. You studied the pattern until it studied you back.', { manual: 'qing_rain_needles', insight: 3, codex: { id: 'secret.fo_qing_founder', cat: 'secrets', title: 'The founder’s cell', text: 'Inside Mount Qingcheng’s western peak is the founder’s sealed practice cell, with the Green Rain Needles laid out in jade. The quake of year 80 opens it; before that, the way in is a crack behind the third shrine.' } }), O('Loose rock. You fell twenty feet and decided the doorway could wait.', { health: -15 })),
    C('Tell the Qingcheng Sect', O('The elders thanked you coldly and sealed the doorway with their own bodies standing in front of it. Qingcheng remembers favours. Just not warmly.', { rep: { orthodox: 5 }, merit: 5 })),
  ] }),
  E('fo_qing_founder_mem', 'fortune', { if: { ...LATER, mem: 'secret.fo_qing_founder', loc: 'qingcheng', year: [10, 79], age: [14, 80], noManual: 'qing_rain_needles' }, art: 'cave', text: 'You remember the founder’s cell inside Mount Qingcheng’s western peak, from a life in which an earthquake opened it. In this life the mountain is whole, and the only way in is a crack behind the third shrine.', choices: [
    R('Squeeze through the crack', 'body', 30, O('It took a day of crawling on your stomach. The jade needles were there, in the shape of rain, undisturbed for three hundred years.', { manual: 'qing_rain_needles', insight: 2, gaze: 1 }), O('You got stuck for a night and a day, and came out the way you went in, minus some skin.', { health: -8 })),
    C('Leave it for the earthquake', O('You left it. Somebody in sixty years will have a very good day.')),
  ] }),

  // ── A face-reader who sees too much ─────────────────────────────
  E('fo_physiognomist', 'fortune', { if: { ...LATER, locType: 'city', age: [14, 80], chance: 0.4 }, art: 'market', title: 'The face-reader', text: 'A blind face-reader at a street corner runs his fingers over your face, and stops. "Strange," he says. "The face of a child and the eyes of a grandfather. How many times have they buried you?"', choices: [
    C('Tell him the truth', O('He listened, nodding. "Heaven notices those who change too much," he said. "Walk softly for a while. Let it look elsewhere." You did. It seemed to help.', { gaze: -1, wealth: -2, sanity: 2 })),
    R('Ask what else he sees', 'insight', 40, O('"A bead," he said. "Two halves. Someone else holding the other." He would not say more, or take your money.', { insight: 3, sanity: -3 }), O('"Bad teeth," he said. "Good bones." It was hardly worth the coin.', { wealth: -2 })),
    C('Laugh it off', O('"Of course," he said, and charged you double.', { wealth: -4 })),
  ] }),

  // ── The sword in the village shrine ─────────────────────────────
  E('fo_sword_stone', 'fortune', { if: { locType: 'village', age: [12, 40], chance: 0.4 }, art: 'shrine', title: 'The sword in the shrine', text: 'In the village shrine a rusted sword is sunk to the hilt in a boulder. The old men say whoever draws it must guard the village for the rest of their life. Every boy in the village has tried. So have most of the girls.', choices: [
    R('Draw it', 'body', 45, O('It came out with a sound like a held breath let go. Under the rust the steel was bright. The whole village came running, the headman wept, and then he handed you a list of their problems.', { item: { fine_sword: 1 }, fame: 3, flag: 'fo.village_oath' }), O('It did not move. The old men nodded, satisfied. They like it there.', { body: 1 })),
    C('Leave it be', O('You left it where it was. Some promises are heavier than swords.')),
  ] }),
  E('fo_oath_called', 'fortune', { if: { flag: 'fo.village_oath', not: 'fo.oath_done', age: [14, 80], chance: 0.5 }, danger: true, art: 'road', title: 'You promised', text: 'A boy you half remember from the village with the shrine finds you, barefoot and out of breath. "Bandits," he gasps. "You drew the sword. You promised."', choices: [
    C('Go back and fight', O('You went back.', { combat: { foe: { name: 'the bandit chief', kind: 'bandit', rel: -0.5 }, context: 'ambush', lethal: 0.2, win: { text: 'The bandits never came back. The village carved your name on the shrine, spelled slightly wrong.', fame: 5, sanity: 5, flag: 'fo.oath_done' }, lose: { text: 'You lost, and lived, and the bandits took the harvest. The village did not blame you. That was harder.', sanity: -6, flag: 'fo.oath_done' } } })),
    Q('Pay the bandits to go elsewhere (40 taels)', { stat: { wealth: '>=40' } }, O('You paid. It was not glorious. Nobody died.', { wealth: -40, flag: 'fo.oath_done' })),
    C('Send the boy away', O('You sent him away. The sword stayed in your belt. It feels heavier now.', { sanity: -12, infamy: 3, flag: 'fo.oath_done' })),
  ] }),

  // ── Odd finds ───────────────────────────────────────────────────
  E('fo_frozen_master', 'fortune', { if: { loc: 'kunlun', age: [16, 90], chance: 0.4 }, art: 'snow', title: 'The man in the ice', text: 'In a crevasse below the Kunlun glacier a man sits cross-legged inside clear ice, eyes closed. His hair stirs a little in the ice, as if in a breeze. You are almost sure he just blinked.', choices: [
    R('Thaw him with your qi', 'power', 50, O('It took three days. He woke, asked what year it was, and wept when you told him. Then he taught you for a season, because he had nothing else left, and walked into the snow in spring.', { insight: 5, qi: 20, mastery: { kun_cloud_sword: 20, kun_snow_palm: 20, sword_basic: 20 }, codex: { id: 'secret.fo_frozen_master', cat: 'secrets', title: 'The man in the ice', text: 'A Kunlun patriarch sits sealed in clear ice in a crevasse below the glacier. Three days of patient qi, never forced, will wake him, and he will teach whoever does it.' } }), O('Your qi ran out before the ice did. You climbed out of the crevasse with frost in your lungs.', { health: -15 })),
    C('Tell the Kunlun Sect', O('Kunlun’s elders went pale and roped off the crevasse. "Our sixth patriarch," one whispered, "who went into seclusion and never came out." They would not let you near him again, but they remember you.', { rep: { orthodox: 6 }, merit: 8 })),
    M('Thaw him slowly, the way that worked before', 'secret.fo_frozen_master', O('Three days, never forcing it. He woke, and wept, and taught you, and this time you knew which questions to ask.', { insight: 6, qi: 25, mastery: { kun_cloud_sword: 25, kun_snow_palm: 25, sword_basic: 25 }, gaze: 1 })),
  ] }),
  E('fo_turtle_chart', 'fortune', { if: { region: ['central', 'jingchu'], age: [12, 80], chance: 0.3 }, art: 'river', title: 'The River Chart', text: 'An enormous turtle crawls out of the river onto the bank beside you. The plates of its shell are carved with dots and lines in a pattern older than writing.', choices: [
    R('Copy the pattern', 'insight', 40, O('You copied it before it slid back into the water. Weeks later, in the middle of a meditation, the pattern suddenly meant something: the order in which qi wants to move.', { insight: 4, qi: 15, codex: { id: 'secret.fo_river_chart', cat: 'theory', title: 'The River Chart', text: 'A turtle carrying the River Chart on its shell comes ashore on the great rivers. The dots are a map of the meridians, in the order qi prefers to travel them.' } }), O('You copied it wrong, and spent a month meditating on your own mistake.', { sanity: -2 })),
    C('Help it back into the water', O('It looked at you with ancient, unimpressed eyes and swam away. You felt oddly forgiven for something.', { sanity: 4 })),
    C('Sell it to a temple', O('A temple paid twenty taels and put it in a pond. The monks say it is unhappy. So, a little, are you.', { wealth: 20, sanity: -3 })),
  ] }),
  E('fo_furnace', 'fortune', { if: { locType: ['wild', 'sect'], age: [14, 80], chance: 0.3 }, art: 'forge', title: 'A cracked furnace', text: 'Half buried in a landslide you find a bronze pill furnace the size of a child, with three legs and a crack down one side. The inside still smells of cinnabar and honey.', choices: [
    R('Clean it and read the inscriptions', 'insight', 40, O('Around the rim an alchemist had engraved his two proudest recipes, in case he forgot them. You do not intend to forget them either.', { recipe: ['marrow_pill', 'foundation_pill'], insight: 2 }), O('The inscriptions were in a script you could not read. You sold the furnace for its bronze.', { wealth: 25 })),
    C('Haul it home', O('It took three days and your back has not forgiven you. It makes very good soup, and, once you worked out the vents, passable pills.', { health: -5, recipe: 'qi_pill' })),
    P('Scrape out the residue and eat it', 0.4, O('Three hundred years old and still potent. Your qi surged for a week.', { qiFill: 25 }), O('Cinnabar is mercury. Mercury is poison. You learned this the hard way.', { health: -20, injury: { name: 'mercury poisoning', seasons: 6, sev: 8 } })),
  ] }),
  E('fo_false_master', 'fortune', { if: { age: [12, 40], realm: '<=2', locType: ['city', 'village'], chance: 0.4 }, art: 'inn', title: 'A hidden master', text: 'A ragged old man with a long white beard watches you train, sighs deeply, and says what you have waited your whole life to hear: "You have talent. I can teach you a secret art. Only twenty taels."', choices: [
    Q('Pay him (20 taels)', { stat: { wealth: '>=20' } }, O('He taught you a breathing method that made you dizzy, took your money, and was gone by morning. The method was backwards. It took a season to undo the damage.', { wealth: -20, health: -10, sanity: -4, insight: 2 })),
    R('Ask for a demonstration first', 'insight', 25, O('He showed you a very confident stance and fell over. You both laughed. He bought you a drink with someone else’s money.', { insight: 2, charm: 1 }), O('His demonstration was so impressive you paid anyway. So was his exit.', { wealth: -20, health: -8 })),
    C('Walk away', O('You walked away. Real hidden masters, you have heard, do not charge by the lesson.')),
  ] }),
  E('fo_sarira', 'fortune', { if: { age: [14, 90], locType: ['sect', 'wild'], chance: 0.3 }, art: 'temple', title: 'Three bright beads', text: 'At a burnt-out hermitage you find the ashes of a monk who let himself burn in meditation. Among the ashes lie three small beads, hard and bright as pearls: sarira, the relics of a lifetime of stillness.', choices: [
    C('Keep one and meditate with it', O('Holding it, your heart went quiet in a way it had not since you were very small. The quiet stayed.', { sanity: 15, insight: 2 })),
    C('Carry them to Shaolin', O('The monks of Mount Song received them with tears and a ceremony that lasted three days. Shaolin does not forget a kindness.', { rep: { orthodox: 8 }, fame: 2, sanity: 5 })),
    C('Sell them', O('A jade dealer paid sixty taels without asking where they came from. You did not sleep well for a while.', { wealth: 60, sanity: -8 })),
  ] }),
  E('fo_wrong_half', 'fortune', { if: { age: [14, 70], realm: [1, 5], locType: ['city', 'village', 'estate'], chance: 0.3 }, art: 'scroll', title: 'A copied manual', text: 'A poor scholar sells you, for the price of his mother’s medicine, a hand-copied manual of breathing. It is beautifully written. Halfway through, the copyist seems to have got bored and started guessing.', choices: [
    R('Find the guesses before you practise', 'insight', 40, O('You found nine errors and corrected six. What was left was a decent method, and a lesson about copyists.', { wealth: -3, qi: 15, insight: 3 }), O('You practised the guesses too. Your qi went the wrong way round a meridian, which is exactly as unpleasant as it sounds.', { wealth: -3, health: -15, sanity: -5, injury: { name: 'twisted meridian', seasons: 4, sev: 6 } })),
    C('Pay him and use it to light the stove', O('It burned beautifully. You were cold, and now you are not, and his mother has her medicine.', { wealth: -3, health: 2, sanity: 2 })),
  ] }),
  E('fo_cave_lovers', 'fortune', { if: { locType: ['wild', 'sect'], age: [14, 70], chance: 0.3 }, art: 'cave', title: 'MINE', text: 'Two skeletons lie in a dry cave, each with a hand on the other’s throat. Between them is a manual torn neatly in half. Scratched into the wall, in two different hands: "MINE." and "MINE."', choices: [
    R('Read both halves together', 'insight', 35, O('Neither half made sense alone. Together, they described a way of breathing for two people at once. You will need a partner. You also understood why they never managed it.', { insight: 4, qi: 10, codex: { id: 'secret.fo_paired_art', cat: 'theory', title: 'The paired breath', text: 'A manual torn in half in a cave of two skeletons describes a cultivation for two people breathing as one. Neither half works alone, which is the point.' } }), O('You could not fit the halves together. Perhaps they could not, either.', { insight: 1 })),
    C('Bury them in separate graves', O('You buried them apart, as they seemed to want. It felt petty, and right.', { sanity: 2 })),
    C('Bury them together', O('You buried them together, half a manual in each grave. Let them argue it out.', { sanity: 4, charm: 1 })),
  ] }),
  E('fo_echo_cave', 'fortune', { if: { locType: ['wild', 'sect'], age: [12, 70], chance: 0.3 }, art: 'cave', text: 'You call into a cave, and the echo comes back a half-beat late, in a voice that is not yours. "Again," it says.', choices: [
    R('Call again', 'sanity', 50, O('You called, and it answered, and you called, until you understood that the cave was teaching you to breathe with the echo. When you came out three days had passed, and your shout could crack stone.', { qi: 25, insight: 2 }), O('You called again. The echo laughed, and kept laughing after you had left.', { sanity: -8 })),
    C('Walk away briskly', O('You walked away briskly. "Coward," said the echo, in your mother’s voice.', { sanity: -2 })),
  ] }),

  // ── A push from behind ──────────────────────────────────────────
  E('fo_pushed', 'fortune', { if: { age: [14, 50], has: 'hostile', locType: ['sect', 'wild'], stat: { health: '>=45' }, chance: 0.3 }, bind: { x: 'hostile' }, danger: true, art: 'mountain', title: 'A hand on your back', text: 'You are standing at the edge of a cliff, admiring the view, when you feel a hand between your shoulder blades. You have just enough time to recognise {x}’s laugh.', choices: [
    R('Twist and grab', 'body', 35, O('You caught {x.his} sleeve and nearly took {x.him} with you. {x.He} tore free and ran. Neither of you will ever mention it. Both of you will remember.', { rel: { x: { aff: -20 } }, body: 1 }), O('You fell.', { health: -25, next: 'fo_pushed_valley' })),
    P('Drop flat', 0.6, O('{x.His} push met only air, and {x.he} nearly went over the edge instead. You let {x.him} scramble back. You did not help.', { rel: { x: { aff: -15, res: 10 } } }), O('Too slow. You fell.', { health: -25, next: 'fo_pushed_valley' })),
  ] }),
  E('fo_pushed_valley', 'fortune', { on: 'scheduled', art: 'forest', title: 'The bottom of the cliff', text: 'You wake in a valley so green it hurts. A skeleton sits under a persimmon tree with a manual on its knees, and carved into the trunk above it: "Pushed, also. Read this, climb out, and make them sorry."', choices: [
    C('Read it, climb out, and make {x.him} sorry', O('It was a lightness art, written in a furious hand. By the time you had learned it you could climb out of the valley. {x} turned the colour of chalk when {x.he} saw you walk in.', { manual: 'uno_ghost_step', mastery: { uno_ghost_step: 15 }, rel: { x: { res: 20 } }, fame: 2 })),
    C('Read it, climb out, and forgive', O('You learned the art and climbed out. When you met {x} again you only nodded. {x.He} has never been more frightened of anyone.', { manual: 'uno_ghost_step', sanity: 6, rel: { x: { res: 30, aff: 10 } } })),
  ] }),

  // ── Inherited obligations ───────────────────────────────────────
  E('fo_contract_due', 'fortune', { if: { flag: 'fo.contract', not: 'fo.contract_done', age: [16, 80] }, art: 'night', title: 'An inherited contract', text: 'A paper crane lands on your windowsill. Unfolded, it is a Blood Shadow contract, half paid, in the dead assassin’s name, and now in yours. The target is a salt merchant in Hangzhou. The other half of the money is generous.', choices: [
    C('Fulfil it', O('You did it. The money was generous. The merchant’s daughter watched from the stairs.', { wealth: 80, infamy: 8, sanity: -12, rep: { unorthodox: 5 }, flag: 'fo.contract_done' })),
    C('Warn the merchant instead', O('The merchant fled to the capital with his family. The Pavilion sent you a second crane, blank. That is how they say they are watching.', { fame: 2, rep: { unorthodox: -8 }, sanity: 3, flag: 'fo.contract_done' })),
    C('Burn it', O('You burned it. Nothing happened for a long time. Then one night a knife was stuck in your doorframe, not in you. A warning, or a courtesy.', { sanity: -4, flag: 'fo.contract_done' })),
  ] }),
  E('fo_qing_traitor', 'fortune', { if: { flag: 'fo.qing_revenge', not: 'fo.qing_done', age: [16, 80], region: 'shu' }, danger: true, art: 'duel', title: 'The poisoner', text: 'You find him at last: the Qingcheng disciple who poisoned his own master, now an elder with a soft voice and a hard face. He recognises the Pine Wind Sword in your stance before you say a word.', choices: [
    C('Challenge him openly', O('He accepted. He had no choice; half the sect was watching.', { combat: { foe: { name: 'the poisoner elder', kind: 'disciple', rel: 0.5 }, context: 'duel', lethal: 0.2, win: { text: 'He knelt and confessed, and Qingcheng did the rest. The dead elder’s name went back on the ancestral tablet.', fame: 6, rep: { orthodox: 6 }, sanity: 5, flag: 'fo.qing_done' }, lose: { text: 'He beat you, smiled, and said nobody would believe you anyway.', sanity: -6, flag: 'fo.qing_done' } } })),
    R('Gather proof first', 'insight', 40, O('A bowl, a receipt from an apothecary, a servant who remembered. You laid it all before the Qingcheng elders, and watched them decide to believe you.', { fame: 4, rep: { orthodox: 8 }, flag: 'fo.qing_done' }), O('Your proof vanished the night before you could present it. So did your witness.', { sanity: -5, flag: 'fo.qing_done' })),
    C('Let it go', O('You let it go. The dead do not collect debts. Only the living do, and you are tired.', { sanity: -5, flag: 'fo.qing_done' })),
  ] }),
  E('fo_ruin_heir', 'fortune', { if: { flag: 'fo.ruin_heir', age: [25, 120], chance: 0.5 }, title: 'The last of the line', text: 'A young woman in mended clothes bows at your gate. "My great-grandfather’s sect is ash, and you carry its art," she says, without heat. "I would like it back. I would like, if possible, to learn it from you."', choices: [
    C('Teach her', O('You taught her for two years. She was better than you by the end, which is how it should be. When she left to rebuild, she bowed lower than she had arrived.', { fame: 4, sanity: 8, insight: 2, unflag: 'fo.ruin_heir' })),
    C('Give her a copy and nothing else', O('You gave her a copy. She thanked you correctly and left. Some debts are paid in exact change.', { sanity: 2, unflag: 'fo.ruin_heir' })),
    C('Refuse', O('"Then it is yours," she said, "and so is what comes with it." She did not curse you. She did not need to.', { infamy: 3, sanity: -5, unflag: 'fo.ruin_heir' })),
  ] }),

  // ── Fated by lightning ──────────────────────────────────────────
  E('fo_fated_lightning', 'fortune', { if: { age: [14, 50], chance: 0.3 }, bind: { x: { ageRel: [-3, 3], minAge: 14, role: 'acquaintance', aff: 40 } }, art: 'storm', title: 'The same tree', text: 'Rain. You and a stranger reach the same pavilion at the same moment, the same lightning strikes the same tree, and the same falling branch knocks you both flat.', choices: [
    C('Help {x.him} up', O('You helped each other up, laughing, and talked until the rain stopped. {x} turned out to be a wanderer too, and a good one. You have been friends ever since, as if you always had been.', { meet: 'x', role: { x: 'friend' }, rel: { x: { aff: 20 } }, sanity: 4 })),
    C('Check the split tree first', O('The lightning had opened a hollow in the trunk. Inside, someone long ago had hidden a jar of silver. You split it with {x}. Fate, it seems, has a sense of humour.', { meet: 'x', wealth: 30, rel: { x: { aff: 10 } }, flag: 'fo.luck+=1' })),
  ] }),

  // ── The Peach Blossom Spring ────────────────────────────────────
  E('fo_peach_spring', 'fortune', { if: { locType: ['wild', 'sect', 'village'], season: 0, age: [14, 80], chance: 0.25 }, art: 'blossom', title: 'Peach petals on the stream', text: 'Peach petals float down a mountain stream where no peach trees grow. You follow them upstream to a cave just tall enough to walk through stooping. Beyond it: fields, farmhouses, and people in clothes three dynasties out of fashion.', choices: [
    C('Stay a season', O('They fed you, asked about the world, and sighed at the answers. You left rested in a way you have not been since childhood. They asked you not to come back. You did not promise.', { sanity: 15, health: 15, codex: { id: 'secret.fo_peach_spring', cat: 'secrets', title: 'The Peach Blossom Spring', text: 'In spring, peach petals on a mountain stream lead to a hidden village outside time. Those who mark the path never find it again. Those who do not, may.' } })),
    C('Mark the path so you can return', O('You notched every tree on the way out. When you came back with friends, the notches led to a cliff. The petals were gone.', { insight: 1, sanity: -3, codex: { id: 'secret.fo_peach_spring', cat: 'secrets', title: 'The Peach Blossom Spring', text: 'In spring, peach petals on a mountain stream lead to a hidden village outside time. Those who mark the path never find it again. Those who do not, may.' } })),
    M('Follow without marking the way, as they asked last time', 'secret.fo_peach_spring', O('They knew you. Not this you; the one who left without notching trees. An old man showed you their way of breathing, slow as the seasons, and said, "You are the only one who ever came back."', { sanity: 12, insight: 4, flag: 'longevity+=3' })),
  ] }),

  // ── The old warhorse ────────────────────────────────────────────
  E('fo_old_warhorse', 'fortune', { if: { region: ['west', 'hebei'], locType: ['frontier', 'wild', 'estate'], age: [14, 70], chance: 0.35 }, art: 'battlefield', title: 'The horse that remembered', text: 'A grey warhorse with a cavalry brand, too old for anything but grazing, follows you for a day. When you stop, it nudges you off the road and waits for you to follow.', choices: [
    C('Follow it', O('It led you to a cairn on an old battlefield, and lay down beside it. Under the stones, a general’s armour and his saber, wrapped in oilcloth by someone who loved him. The horse did not get up again.', { item: { heavy_saber: 1 }, fame: 2, sanity: -3, insight: 2 })),
    C('Take it to a stable', O('You paid a stable to let it graze out its days. It never stopped looking west.', { wealth: -5, sanity: 4 })),
    C('Shoo it away', O('It went, slowly, looking back.')),
  ] }),

  // ── A eunuch’s confession ───────────────────────────────────────
  E('fo_eunuch_hoard', 'fortune', { if: { loc: 'capital', age: [16, 80], chance: 0.35 }, art: 'palace', title: 'A deathbed confession', text: 'In a charity hospital an old palace eunuch, dying of something long and slow, grabs your sleeve. "Forty years of skimming," he whispers. "Under the third stone of the Moon Gate well. I cannot take it with me and I will not leave it to them."', choices: [
    C('Dig it up and keep it', O('Under the third stone: silver, and a list of names in the eunuch’s neat hand. You kept the silver and burned the list. Someone noticed one or the other.', { wealth: 180, rep: { court: -8 }, flag: ['fo.whispers', 'fo.luck+=1'] })),
    C('Dig it up and give it to the hospital', O('The hospital had a new roof by winter. The eunuch, told, laughed until he died. "Good," he said. "Good. Let them choke on it."', { wealth: 20, fame: 4, sanity: 6 })),
    C('Tell the Eastern Depot', O('The Depot thanked you, dug it up, and gave you a small reward and a long look.', { wealth: 15, rep: { court: 6 } })),
  ] }),

  // ── The magpies and the bell (a folktale come true) ─────────────
  E('fo_magpie_snake', 'fortune', { if: { locType: ['wild', 'sect', 'village'], age: [12, 60], season: [0, 1], chance: 0.3 }, art: 'forest', title: 'The magpies’ nest', text: 'A great black snake has wound itself around a pine and is climbing toward a magpies’ nest. The parent birds dive at it, screaming. It does not even look at them.', choices: [
    C('Kill the snake', O('One clean cut. The magpies settled on the branches around you, chattering, as if taking your name. That night, in the village, you heard a woman weeping somewhere.', { sanity: 2, flag: 'fo.magpie', next: { id: 'fo_magpie_bell', in: 3 } })),
    C('Drive it off without killing it', O('You struck the trunk until the snake slid away into the grass, sullen and unhurt. The magpies called after you for a mile.', { sanity: 3, insight: 1 })),
    C('Leave nature to itself', O('You left. The screaming stopped after a while.', { sanity: -2 })),
  ] }),
  E('fo_magpie_bell', 'fortune', { on: 'scheduled', if: { flag: 'fo.magpie', stat: { health: '>=35' } }, danger: true, art: 'temple', title: 'Three strokes of the bell', text: 'Lost on a mountain at night, you are taken in at a lonely house by a beautiful woman. You wake at midnight with a black snake coiled on your chest. "You killed my husband," it says. "If the bell of the ruined temple on the peak rings three times before dawn, I must let you go. It has not rung in a hundred years."', choices: [
    R('Hold still and pray', 'sanity', 45, O('Before dawn the bell rang: once, twice, three times. The snake hissed and was gone. At first light you climbed to the temple. Under the bell lay three magpies, their heads broken from striking it.', { sanity: -4, insight: 3, fame: 2, unflag: 'fo.magpie' }), O('Before dawn the bell rang: once, twice, three times. It came too late for you to hold still; the snake had bitten you as you flinched. You lived. Under the bell lay three dead magpies.', { health: -25, unflag: 'fo.magpie' })),
    R('Seize it by the neck', 'body', 45, O('You were faster. You threw it into the night and ran, and at dawn you heard a bell ringing on the peak behind you, three times, for no one.', { body: 1, unflag: 'fo.magpie' }), O('It was faster. You woke at dawn in an empty, ruined house, sick and swollen, alive.', { health: -22, unflag: 'fo.magpie' })),
  ] }),

  // ── A lake that shows the heart ─────────────────────────────────
  E('fo_mirror_lake', 'fortune', { if: { age: [16, 120], realm: '>=1', locType: ['wild', 'sect'], chance: 0.3 }, art: 'lake', title: 'Your reflection', text: 'You kneel to drink from a still mountain lake. Your reflection does not kneel with you. It stands, and smiles your smile, and says, "Let’s see which of us is real."', choices: [
    R('Face it', 'sanity', 55, O('You argued with yourself until sunset, and lost, and then won. When you stood up, your reflection stood up with you, at last, and some old ache in your heart had gone with the light.', { sanity: 15, insight: 4, cure: 'injuries' }), O('It won. You walked away from the lake feeling as if you had left something important behind, and that what had come away with you was not quite you.', { sanity: -15, qi: 15 })),
    C('Throw a stone into the water', O('The reflection broke into rings. When the water stilled, it was only you, looking worried.', { sanity: -2 })),
  ] }),

  // ── The old soul in the ring ────────────────────────────────────
  E('fo_ring_found', 'fortune', { if: { age: [10, 40], realm: '<=3', not: 'fo.ring', chance: 0.25 }, art: 'night', title: 'A black ring', text: 'Digging in the garden, you turn up a black iron ring. When you slip it on, an old man’s voice says, quite crossly, inside your head: "Finally. Do you know how long I have been in the dirt? Never mind. Your breathing is atrocious. Sit down."', choices: [
    C('Sit down', O('He called himself Elder Mok, refused to say of what, and corrected your breathing until dawn. He is rude, tireless, and right about almost everything.', { flag: 'fo.ring', qi: 15, insight: 2 })),
    C('Take it off and throw it in the well', O('You threw it in the well. For a week, you heard faint, furious shouting whenever you drew water.', { sanity: -2 })),
  ] }),
  E('fo_ring_lesson', 'fortune', { if: { flag: 'fo.ring', not: ['fo.ring_done', 'fo.ring_n>=4'], age: [10, 80] }, once: false, cd: 3, art: 'meditation', title: 'Elder Mok', text: '[Elder Mok wakes you before dawn. "Again," he says. "You were lazy yesterday, in your sleep."|"There is a man at the next table who will try to cheat you," says the voice in the ring. "Watch his left hand."|Elder Mok is in a good mood, which is to say he only insults you twice before the lesson starts.]', choices: [
    C('Do as he says', O('He drove you hard. You are stronger for it, and more tired than you have ever been.', { qi: 15, insight: 2, flag: 'fo.ring_n+=1' })),
    C('Ask him who he was', O('"Someone who trusted the wrong disciple," he said, and would not talk for a month. When he started again, his lessons were gentler.', { insight: 3, flag: 'fo.ring_n+=1' })),
  ] }),
  E('fo_ring_body', 'fortune', { if: { flag: ['fo.ring', 'fo.ring_n>=3'], not: 'fo.ring_done', age: [14, 90] }, danger: true, art: 'night', title: 'What Elder Mok wants', text: 'You wake unable to move your arms. In your head, Elder Mok says, almost apologetically: "You have done well. Your meridians are finally fit for a master. I need a body, and I have given you everything. Surely you can lend me yours."', choices: [
    R('Fight him for your own body', 'sanity', 55, O('You fought him all night in the dark of your own head, and in the morning he was gone from the ring, and what he taught you stayed. The ring is only iron now.', { sanity: -5, insight: 5, qiFill: 30, flag: 'fo.ring_done' }), O('You won, barely. For a month, your left hand sometimes moved on its own, correcting your grip.', { sanity: -20, health: -10, insight: 3, flag: 'fo.ring_done' })),
    R('Bargain with him', 'charm', 45, O('"A disciple who argues," he said, and you heard him smile for the first time. "That is what I wanted from the last one." He let go, and gave you the last of his art, and asked to be buried under a plum tree.', { manual: 'lost_reversed_step', sanity: 4, flag: 'fo.ring_done' }), O('He did not want to bargain. You threw the ring into a furnace with an arm that was not entirely yours. His scream lasted longer than the iron did.', { sanity: -12, burden: 1, flag: 'fo.ring_done' })),
  ] }),
];

// A codex entry from a [title, text] pair.
const cx = (id, cat, [title, text]) => ({ id, cat, title, text });
// Dangerous rows do not ambush someone already at death's door.
const SAFE = (r) => (r.danger ? { stat: { health: '>=40' } } : {});

// ── Template: hidden caves, one per mountain ─────────────────────
// Go in (a roll, which also teaches you where it is), leave it another way, or, in a later life, go
// straight to what you found last time.
const CAVES = [
  { key: 'mounthua', loc: 'mounthua', if: { noManual: 'hua_fragrance_step', season: [3, 0] }, title: 'Warm air in the granite', text: 'Behind a curtain of plum branches on the Lotus Peak, a crack in the granite breathes warm air into the snow. It is just wide enough for someone who has not eaten lately.',
    go: 'Squeeze in', stat: 'body', dc: 30,
    ok: O('A meditation cell, three hundred years old. On the wall, footprints carved in a pattern like falling petals: the Dark Fragrance Steps, as some long-dead elder first dreamed them.', { manual: 'hua_fragrance_step', rep: { orthodox: -2 }, flag: 'fo.luck+=1' }),
    no: O('Halfway in, the granite decided you had eaten lately. You were stuck until dark and got out with a torn sleeve and bruised pride.', { health: -8 }),
    leave: ['Tell the Mount Hua elders', O('The elders sent a disciple in, who came back out with a box and a face that told you nothing. They thanked you with a meal and a warning to keep it to yourself.', { rep: { orthodox: 4 }, merit: 4 })],
    codex: ['The warm crack on the Lotus Peak', 'Behind the plum branches on Mount Hua’s Lotus Peak, a warm crack in the granite leads to an elder’s cell with the Dark Fragrance Steps carved on the wall. Go in thin, in winter, when the warm air shows the way.'],
    mem: ['Go in thin, the way you remember', O('You fasted for three days and slid in like a letter under a door. The footprints were waiting.', { manual: 'hua_fragrance_step', mastery: { hua_fragrance_step: 15 }, gaze: 1 })] },
  { key: 'zhongnan', loc: 'zhongnan', title: 'The jade bed', text: 'Above the hermitages of Mount Zhongnan, a cave holds nothing but a bed of pale green jade, warm to the touch, worn smooth by some long-gone body.',
    go: 'Meditate on the jade bed', stat: 'sanity', dc: 55,
    ok: O('The warmth rose through your spine and settled in your dantian like a cat by a stove. You came down the mountain a season later, a season stronger.', { qi: 30, health: 10 }),
    no: O('You dreamed the hermit’s death, slowly, from the inside. You came down the mountain early.', { sanity: -8, qi: 10 }),
    leave: ['Try to pry up the jade', O('It would not budge. The Daoists below caught you with a crowbar and were very disappointed in you.', { rep: { orthodox: -2 }, body: 1 })],
    codex: ['The jade bed on Zhongnan', 'A cave above the Zhongnan hermitages holds a warm jade bed. Meditating on it gathers qi as fast as a season of seclusion, if your heart is calm enough not to dream.'],
    mem: ['Empty your heart first, then lie down', O('You knew to empty your heart first. The jade was warm, and the dreams did not come.', { qi: 35, health: 10, sanity: 5 })] },
  { key: 'kongtong', loc: 'kongtong', if: { noManual: 'ext_tiger_bone' }, danger: true, title: 'The screaming cave', text: 'Wind pours through a cave mouth on Mount Kongtong with a sound like a man screaming. Locals say a fist master is still in there, practising. The walls of the entrance are pocked with knuckle marks.',
    go: 'Walk into the wind', stat: 'body', dc: 35,
    ok: O('At the back, out of the wind, a skeleton sat in a horse stance, perfectly still. Carved beside him: the Tiger Bone Tempering, and a note saying the wind was the point.', { manual: 'ext_tiger_bone', body: 2 }),
    no: O('The wind threw you out like a drunk from a tavern, and took some skin with it.', { health: -12 }),
    leave: ['Train in the cave mouth instead', O('You stood in the screaming wind for a month. You found nothing, but you stopped flinching at loud noises.', { body: 2, sanity: 2 })],
    codex: ['The screaming cave', 'On Mount Kongtong, a cave that screams in the wind holds a fist master’s skeleton and the Tiger Bone Tempering. Crawl in low along the left wall, below the wind.'],
    mem: ['Crawl in low along the left wall', O('Below the wind it was almost quiet. The skeleton was still holding his stance. You bowed to him before you took the manual.', { manual: 'ext_tiger_bone', body: 3, gaze: 1 })] },
  { key: 'songshan', loc: 'songshan', age: [14, 90], title: 'The shadow on the wall', text: 'In a cave above Shaolin, a monk once faced the wall for nine years. His shadow is still on the stone, darker than the rock around it, sitting perfectly straight.',
    go: 'Face the wall beside it', stat: 'insight', dc: 40,
    ok: O('After a month you understood that the shadow was not facing the wall. It was facing you. Something in your chest came untied that you had not known was knotted.', { insight: 5, sanity: 8, qi: 15 }),
    no: O('You stared at a wall for a month. You came away with a stiff neck and a strange sense of peace, which is not nothing.', { sanity: 3 }),
    leave: ['Bow and leave', O('You bowed and left. The monks below saw you come down and nodded, as if you had passed something.', { rep: { orthodox: 2 } })],
    codex: ['The wall-gazing cave', 'Above Shaolin is the cave where a monk faced the wall for nine years. Sit beside his shadow, not before it, and let it look at you.'],
    mem: ['Sit beside the shadow, not in front of it', O('You sat beside him like a friend. By the end of the season you were breathing in time.', { insight: 6, sanity: 10, qi: 20 })] },
  { key: 'wudang', loc: 'wudang', if: { noManual: 'wu_taiji_fist' }, title: 'The snake and the crane', text: 'A shallow cave on the Wudang slopes is carved with a snake and a crane locked in a fight that has no beginning and no end. The carving runs all the way around the walls.',
    go: 'Walk the carving around the cave', stat: 'insight', dc: 35,
    ok: O('You walked it a hundred times. On the hundred and first your hands began to move like the snake and the crane at once. Some Wudang ancestor had carved the Taiji Fist into the stone before it had a name.', { manual: 'wu_taiji_fist', insight: 2 }),
    no: O('You walked in circles until you were dizzy, and then walked into a wall.', { health: -5, insight: 1 }),
    leave: ['Copy it for the Wudang Daoists', O('The Daoists were delighted and gave you tea and a lecture on softness. You kept the tea.', { rep: { orthodox: 3 }, health: 3 })],
    codex: ['The snake and the crane', 'A cave on the Wudang slopes is carved with a snake and a crane fighting around its walls: the Taiji Fist before it had a name. Walk it backwards; the carver did.'],
    mem: ['Walk it backwards, as the carver did', O('Backwards, it made sense at once. You laughed out loud, alone in the cave.', { manual: 'wu_taiji_fist', mastery: { wu_taiji_fist: 20 } })] },
  { key: 'emei', loc: 'emei', age: [10, 70], title: 'The monkeys’ cave', text: 'On Mount Emei a troop of monkeys snatches your pack and races up the cliff, straight into a cave mouth. One of them stops at the entrance and waves at you, which seems excessive.',
    go: 'Chase them in', stat: 'body', dc: 25,
    ok: O('Their cave was a magpie’s dream: pilgrims’ purses, a jade pendant, a pill box, and your pack, which they had already been through. You took back a good deal more than you lost.', { wealth: 30, item: { jade_pendant: 1, qi_pill: 1 } }),
    no: O('They pelted you with fruit from the ledges until you gave up. You never saw your pack again.', { wealth: -5, health: -3 }),
    leave: ['Bribe them with fruit', O('You offered a peach. After a long negotiation the pack came back, minus your rice cakes and plus a flea.', { sanity: 2 })],
    codex: ['The monkeys’ hoard', 'The thieving monkeys of Mount Emei keep their hoard in a cave on the cliff above the pilgrim stair. They let in anyone who brings plums, and only plums.'],
    mem: ['Bring plums, and only plums', O('They let you in like an old friend and let you take your pick of the hoard.', { wealth: 40, item: { jade_pendant: 1, qi_pill: 2 } })] },
  { key: 'qingcheng', loc: 'qingcheng', danger: true, title: 'Green mist', text: 'On Mount Qingcheng a cave exhales a faint green mist that has killed the moss around its mouth. Inside, very faintly, you can make out the shapes of shelves.',
    go: 'Hold your breath and go in', stat: 'health', dc: 50,
    ok: O('A hermit’s poison garden: dried flowers, labelled jars, and a book of recipes. You got out with the book before your lungs gave out.', { recipe: ['heart_calming', 'healing_salve'], insight: 3 }),
    no: O('The mist got into your lungs. You coughed green for a month.', { health: -18, injury: { name: 'mist-burned lungs', seasons: 4, sev: 6 } }),
    leave: ['Leave it alone', O('You left it alone. Some caves are warnings.')],
    codex: ['The green-mist garden', 'A cave on Mount Qingcheng breathes poison mist. A cloth soaked in vinegar over the mouth is enough to reach the dead hermit’s recipe book on the back shelf.'],
    mem: ['Go in with a vinegar cloth over your mouth', O('The vinegar stung and the mist did not. You took the recipe book and a jar labelled, in a neat hand, DO NOT.', { recipe: ['heart_calming', 'healing_salve'], insight: 3, item: { heart_calming: 1 } })] },
  { key: 'diancang', loc: 'diancang', if: { noManual: 'dian_swift_sword' }, title: 'Scratches above the clouds', text: 'Above the sea of cloud on Mount Diancang, the walls of a shallow cave are covered in thin, straight scratches, thousands of them, as if someone practised a single stroke for a lifetime.',
    go: 'Practise the stroke until you understand it', stat: 'body', dc: 40,
    ok: O('You copied the stroke until your arm stopped being an arm. Then the scratches arranged themselves into a sequence: the Diancang Swift Sword, as its founder first found it.', { manual: 'dian_swift_sword', body: 1 }),
    no: O('You practised the stroke for a month and learned only how many ways there are to pull a shoulder.', { injury: { name: 'torn shoulder', seasons: 4, sev: 6 } }),
    leave: ['Add a scratch of your own', O('You added one scratch, a little crooked. Somebody, someday, will wonder about it.', { sanity: 2 })],
    codex: ['The founder’s scratches', 'A cave above the clouds on Mount Diancang is covered in the founder’s practice strokes. Read them from the floor up, and they become the Diancang Swift Sword.'],
    mem: ['Read them from the floor up', O('From the floor up, the strokes were a sentence. You read it in an afternoon.', { manual: 'dian_swift_sword', mastery: { dian_swift_sword: 20 }, gaze: 1 })] },
  { key: 'taihang', loc: 'taihang', danger: true, title: 'A bandit’s bolt-hole', text: 'In the Taihang, a cave half hidden by brambles has a fresh path beaten to its mouth, and a crossbow string lying in the grass. Somebody keeps something here.',
    go: 'Look for traps and go in', stat: 'insight', dc: 30,
    ok: O('Two tripwires, one pit. Behind them, a bandit captain’s private stash: silver and a good saber. The Green Forest will be furious, once they find out who.', { wealth: 60, item: { heavy_saber: 1 }, rep: { unorthodox: -5 }, flag: ['fo.whispers', 'fo.luck+=1'] }),
    no: O('You found the third tripwire with your leg. The crossbow found the rest of you.', { injury: { name: 'crossbow bolt', seasons: 4, sev: 15 } }),
    leave: ['Leave it to its owner', O('You left. Bandits who set traps for their own brothers are not people you want to rob.')],
    codex: ['The captain’s stash', 'A Taihang cave behind brambles holds a Green Forest captain’s private stash. Two tripwires at the knee, a pit, and a third wire at the ankle just past it.'],
    mem: ['Step over the ankle wire you remember', O('Two wires, a pit, and the ankle wire. You took the silver and left the captain a polite note. He will not find it polite.', { wealth: 70, item: { heavy_saber: 1 }, rep: { unorthodox: -5 }, flag: 'fo.whispers' })] },
  { key: 'kunlun', loc: 'kunlun', if: { realm: '>=3', noManual: 'kun_snow_palm' }, danger: true, title: 'Where qi freezes', text: 'A blue ice cave on the Kunlun glacier is so cold your breath falls to the ground as frost. On the far wall a palm print is sunk a full inch into the ice, rimmed with frost that never melts.',
    go: 'Press your palm into the print', stat: 'health', dc: 55,
    ok: O('The cold went up your arm and into your heart and stopped there, waiting. Then it moved again, the way the print wanted: the Kunlun Snow-Burial Palm, left in ice by a master who did not trust paper.', { manual: 'kun_snow_palm', health: -10 }),
    no: O('The cold went into your arm and stayed. Your fingers were black for a season.', { injury: { name: 'frostbitten hand', seasons: 6, sev: 12 } }),
    leave: ['Leave before you freeze', O('You left while you could still feel your feet. Prudence is also an art.')],
    codex: ['The palm in the ice', 'A blue ice cave on the Kunlun glacier holds the Snow-Burial Palm, pressed into the ice. Warm your meridians until you steam before you press, and the cold will not take your fingers.'],
    mem: ['Warm your meridians first, then press', O('You warmed your meridians until you steamed, and pressed. The cold came in politely, taught you, and left.', { manual: 'kun_snow_palm', gaze: 1 })] },
  { key: 'dongting', loc: 'dongting', if: { noManual: 'uno_water_palm' }, title: 'The breathing cave', text: 'Diving in the reeds of Lake Dongting, you find an underwater cave. Bubbles rise from it in a steady line, as if something inside is breathing.',
    go: 'Swim in', stat: 'body', dc: 35,
    ok: O('Beyond the entrance, an air pocket, a ledge, and a drowned man’s handprints all over the rock in a pattern that moves like water: the Water Ghost Palm.', { manual: 'uno_water_palm', health: -5 }),
    no: O('You swam in and could not find the way out for a very long time.', { health: -15 }),
    leave: ['Come up and breathe', O('You came up and breathed. The bubbles kept rising.')],
    codex: ['The breathing cave', 'In the reeds of Lake Dongting a line of bubbles marks an underwater cave with an air pocket. The Water Ghost Palm is drawn in handprints on the ledge. The way out is toward the light, not the bubbles.'],
    mem: ['Swim in, and out toward the light', O('Toward the light, not the bubbles. You had learned that the hard way, once.', { manual: 'uno_water_palm', mastery: { uno_water_palm: 15 } })] },
];
const tplCave = template('fo_cave', CAVES, (r) => E('fo_cave', 'fortune', {
  if: { loc: r.loc, age: r.age || [12, 70], chance: 0.35, ...SAFE(r), ...r.if }, art: 'cave', title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [
    R(r.go, r.stat, r.dc, { ...r.ok, codex: cx(`secret.fo_cave_${r.key}`, 'secrets', r.codex) }, r.no),
    C(r.leave[0], r.leave[1]),
    M(r.mem[0], `secret.fo_cave_${r.key}`, r.mem[1]),
  ],
}));

// ── Template: a dying master, one per art ────────────────────────
// Stay and inherit the art (with its price), or do the decent or the greedy thing instead. In a later
// life you can arrive early and save the master, who then teaches you properly.
const DYING = [
  { key: 'escort', manual: 'escort_spear', if: { region: 'central' }, art: 'road', title: 'The last escort', text: 'Behind an overturned cart on the Luoyang road an old escort chief sits with three arrows in him and his spear across his knees. "The dowry," he says. "For a bride in Kaifeng. I have never lost a cargo. Don’t let me start now."',
    stay: ['Take the cargo and his spear', 'You delivered the dowry to Kaifeng, where the bride’s family wept and paid you his fee. In the long nights on the road you read the spear manual in his pack, and practised with his spear.', { wealth: 15, rep: { merchants: 5 }, fame: 2 }],
    other: ['Take the cargo for yourself', O('The dowry was worth forty taels. The bride’s family hired someone to find out who took it. You never learned whether they did.', { wealth: 40, infamy: 4, sanity: -6 })],
    codex: ['The last escort', 'An old escort chief dies on the Luoyang road, ambushed by archers in the willows. Warn him at the inn the night before and he lives, and teaches his Flowing Spear.'],
    mem: ['Warn him at the inn the night before', 'He laughed at you, and then took the other road anyway. The archers waited in the willows for nobody. He taught you his spear that winter, alive and gruff and grateful.', { rep: { merchants: 5 }, gaze: 1 }] },
  { key: 'thief', manual: 'uno_ghost_step', if: { loc: 'kaifeng' }, art: 'night', title: 'On the rooftops', text: 'A thief drops off a Kaifeng roof at your feet, bleeding from a Depot needle in his neck. "They will be here in a breath," he says. "My step. My whole art. Take it before they do. Take it and run."',
    stay: ['Take it and run', 'You ran, his manual in your shirt. The Depot men saw your back and, worse, your face.', { rep: { court: -8 } }],
    other: ['Stand over him and wait for the Depot', O('The Depot men took the body and wrote down your name, as a good citizen. You do not feel like one.', { rep: { court: 4 }, sanity: -4 })],
    codex: ['The thief of Kaifeng', 'A thief dies on the Kaifeng rooftops with a Depot needle in his neck, carrying the Ghost Shadow Step. The needle is tipped with grey moth; a heart-calming draught slows it long enough to save him.'],
    mem: ['Pour a heart-calming draught down his throat', 'The poison slowed. You hid him under your floor for a week while the Depot searched. He taught you his step to pay the debt, and left one morning with your best boots.', { sanity: 3, gaze: 1 }] },
  { key: 'bloodlord', manual: 'uno_blood_saber', if: { loc: 'taihang', realm: '>=1' }, art: 'fire', title: 'The red saber', text: 'A bandit lord lies in the ruins of his own stronghold, rivals’ bodies all around him, his saber still in his fist and his eyes bright with something that is not sanity. "It wants a new hand," he says. "It always wants a new hand."',
    stay: ['Take the saber art', 'You took the manual from his belt. Reading it was like putting your hand into hot blood. It is powerful. It is also always, faintly, angry.', { sanity: -8, infamy: 3 }],
    other: ['Bury him and the manual together', O('You buried the man and his art in the stronghold’s ashes. Some things should not have a next hand.', { sanity: 4, rep: { unorthodox: 2 } })],
    codex: ['The Blood Saber’s hunger', 'A Green Forest lord dies in his burned Taihang stronghold carrying the Blood Saber Art. Read it only after meditating a full day; the art feeds on an unsettled heart.'],
    mem: ['Meditate a full day before you read it', 'You read it with a still heart. The art strained against you and found nothing to grip.', { sanity: -2 }] },
  { key: 'porter', manual: 'ext_iron_shirt', if: { loc: 'wuchang' }, art: 'river', title: 'The porter’s chest', text: 'On the Wuchang docks an old porter has collapsed under a load three men should have carried. He has done it for forty years, for coppers. "Iron Shirt," he wheezes, tapping his chest. "Learned it to carry more. Nobody ever asked."',
    stay: ['Ask him, and pay for his funeral', 'He taught you on the docks in the last month of his life, between loads. You paid for his funeral with your own silver, and every porter on the river came.', { wealth: -8, body: 2, sanity: 3 }],
    other: ['Get him to a physician', O('The physician took your money and shook his head. The porter died thanking you for a kindness that did nothing.', { wealth: -5, sanity: -2 })],
    codex: ['The porter of Wuchang', 'An old porter on the Wuchang docks knows the Iron Shirt and has never been asked to teach it. Carry his loads for a season before he collapses, and he lives to teach you.'],
    mem: ['Carry his loads for a season before he collapses', 'You carried his loads beside him for a season. He did not collapse that year. He taught you slowly, between ships, and laughed at how your back complained.', { body: 3 }] },
  { key: 'venom', manual: 'med_five_venoms', if: { region: 'shu', notSect: 'dang' }, art: 'forest', title: 'The venom-hag', text: 'A hunched old woman lies by a stream on the edge of the Dang lands, her hands black to the wrist. "The Dang wanted my palm," she says. "I gave them a taste. Now they have given me one back."',
    stay: ['Learn the Five Venoms Palm from her', 'She taught you in a fevered whisper. When you practised, your own palms went grey, and stayed grey. The Dang family heard of it, the way the Dang hear everything.', { injury: { name: 'venom-greyed palms', seasons: 8, sev: 6 }, rep: { families: -4 } }],
    other: ['Carry her to the Dang for an antidote', O('The Dang took her in, thanked you, and closed the door. You never saw her again. Nobody did.', { rep: { families: 4 }, sanity: -5 })],
    codex: ['The venom-hag', 'A poison master dies by a stream on the edge of the Dang lands, poisoned by the Dang for her Five Venoms Palm. Golden Wound Salve bound on her wrists slows it enough to save her.'],
    mem: ['Bind her wrists with wound salve first', 'The salve slowed the poison. She lived, cackling, and taught you how to keep your palms from greying.', { rep: { families: -2 } }] },
  { key: 'exile', manual: 'kun_cloud_sword', if: { loc: 'jadegate', realm: '>=1' }, art: 'desert', title: 'An exile’s sword', text: 'In the caravan inn at Jade Gate a man in a ragged Kunlun white robe lies dying, of fever and of shame. "They cast me out for loving the wrong person," he says. "My sword is still Kunlun’s. Take it home for me. Or keep it. I no longer know which is the insult."',
    stay: ['Learn his sword, and keep it', 'He taught you the Cloud Dragon Sword with a fevered hand that never shook. Kunlun will not thank you for learning it outside their gate.', { rep: { orthodox: -4 }, insight: 1 }],
    other: ['Carry his ashes to Kunlun', O('You carried his ashes up into the snow. The Kunlun elders received them with closed faces, and then one of them, an old woman, wept.', { rep: { orthodox: 6 }, sanity: 4, travel: 'kunlun' })],
    codex: ['The Kunlun exile', 'A Kunlun exile dies of fever at the Jade Gate caravan inn, cast out for love. Bring willow bark and he lives through it, and teaches the Cloud Dragon Sword in gratitude.'],
    mem: ['Bring willow bark for the fever', 'The fever broke at dawn. He wept, embarrassed, and taught you everything, and went west with a caravan to a life where no one knew what Kunlun was.', { sanity: 4 }] },
  { key: 'poisoned', manual: 'qing_pine_sword', if: { loc: 'chengdu' }, art: 'inn', title: 'Poisoned tea', text: 'In a Chengdu teahouse an old man in Qingcheng green slides off his chair, foam at his lips. His eyes find yours. "My disciple," he manages. "His tea. My sword. Take it, and when you can, make him answer for it."',
    stay: ['Take his sword, and his grudge', 'He died with your promise in his ears. The Pine Wind Sword is yours now, and so is the name of the disciple who poisoned him.', { flag: 'fo.qing_revenge', sanity: -3 }],
    other: ['Call for a physician', O('The physician came too late. The Qingcheng disciples came very quickly, took the body, and looked at you as if you had done it.', { rep: { orthodox: -2 }, sanity: -3 })],
    codex: ['Poisoned tea in Chengdu', 'A Qingcheng elder is poisoned by his own disciple in a Chengdu teahouse. Knock the cup from his hand before he drinks and he lives, and teaches the Pine Wind Sword.'],
    mem: ['Knock the cup out of his hand', 'Tea everywhere, a startled old man, and across the room a young man in green turning white. The elder understood at once. He taught you his sword, and dealt with his disciple himself.', { rep: { orthodox: 4 } }] },
  { key: 'daoist', manual: 'zhong_heaven_gate', if: { loc: 'zhongnan', season: [3, 0] }, art: 'snow', title: 'A Daoist under the pines', text: 'Under the pines of Mount Zhongnan an old Daoist sits wrapped in snow, cross-legged, quite peacefully dying. "I am going," he says. "I have been going for days. It is slower than I hoped. Would you like a sword art while you wait?"',
    stay: ['Wait with him and learn', 'He taught you the Heavenly Gate Sword between long silences, in a voice that got quieter every day, and one morning he was simply still. You buried him under the pines, as he asked, with his feet toward the gate.', { insight: 2, sanity: 2 }],
    other: ['Fetch help from the hermitages', O('The hermits came and sat with him, and politely asked you to leave. Some deaths are a private matter among Daoists.', { rep: { orthodox: 2 } })],
    codex: ['The Daoist under the pines', 'An old Zhongnan Daoist dies slowly under the pines, in the snow, by choice. He teaches the Heavenly Gate Sword to whoever waits with him. He is very fond of jujube tea.'],
    mem: ['Bring him jujube tea', 'He sniffed the tea and smiled. "You have been here before," he said; it was not a question. He taught you twice as fast, as if he knew you had the time.', { sanity: 3 }] },
  { key: 'beggar', manual: 'beg_staff', if: { loc: 'luoyang', season: 3 }, art: 'snow', title: 'A Nine-Pouch elder', text: 'Under a Luoyang bridge an old beggar with nine pouches on his belt is dying of cold, curled around a green bamboo staff. "Nobody to pass it to," he says. "The young ones want money, not sticks."',
    stay: ['Take the staff, and beg beside him for a season', 'You begged beside him for a season, in rags, learning the Dog-Beating Staff in alleys. He died warm, at least, under your coat. The Beggars’ Sect noticed who had been with him.', { wealth: -10, charm: -1, rep: { orthodox: 5 }, sanity: 3 }],
    other: ['Give him your coat and your silver', O('He took the coat and gave the silver to a child under the next arch. "Sticks," he grumbled, "not money," and died in the night, warm.', { wealth: -10, sanity: 4 })],
    extra: [C('Take his staff and his place in the Beggars’ Sect', O('You took his staff and his place. The Beggars’ Sect took you in without questions, as it does.', { manual: 'beg_staff', join: 'beggars', rep: { orthodox: 3 } }), { show: { sect: 'none' } })],
    codex: ['The Nine-Pouch elder', 'An old Nine-Pouch elder of the Beggars’ Sect freezes under a Luoyang bridge in winter with no one to inherit the Dog-Beating Staff. A brazier and a jar of rice wine, and he lives till spring.'],
    mem: ['Bring a brazier and a jar of rice wine', 'He lived till spring, drunk and grateful and teaching. "Sticks," he said happily the whole time, "not money."', { rep: { orthodox: 3 } }] },
  { key: 'outcast', manual: 'paeng_tiger_saber', if: { region: 'hebei', notSect: 'paeng' }, art: 'estate', title: 'Outside the gate', text: 'Outside the gate of the Paeng fortress an old man in a torn tiger-stripe coat is dying in the mud, cast out decades ago. "Five Tigers," he says. "Better than they do it inside. Take it, and let them see."',
    stay: ['Learn it from him', 'He taught you in a ditch, laughing about every Paeng elder he had ever beaten. The Paeng will recognise the saber when they see it, and they will not be pleased.', { rep: { families: -6 }, body: 1 }],
    other: ['Knock on the gate and ask them to take him in', O('They took him in, reluctantly. He died in a warm bed, swearing at them. A Paeng nephew thanked you at the gate, red-faced.', { rep: { families: 5 } })],
    codex: ['The outcast tiger', 'An outcast Paeng master dies outside the Paeng fortress gate with his own, better Five Tigers Severing Saber. Bring young Paeng Gu out to see him, his grandson, and he finds a reason to live.'],
    mem: ['Bring young Paeng Gu out to see him', 'The old man and the boy looked at each other for a long time. Then the old man laughed until he coughed, and lived, and taught you both.', { rep: { families: 3 }, meet: '@paeng_gu', rel: { '@paeng_gu': { aff: 15 } } }] },
  { key: 'assassin', manual: 'uno_silent_needle', if: { loc: 'hangzhou', age: [16, 70] }, art: 'night', title: 'A needle in the dark', text: 'In a Hangzhou alley a woman in black lies with an arrow through her, still holding a needle case. "Blood Shadow," she says, without fear. "My contract is half done. Take my needles, finish it, and they will let you keep them."',
    stay: ['Take the needles and the contract', 'She died with the contract pressed into your hand. The Silent Death Needle is yours now. So, the Pavilion will assume, is her unfinished work.', { flag: 'fo.contract', infamy: 2 }],
    other: ['Take nothing and leave', O('You left her the dignity of her needles. The Pavilion collected her before dawn, and nobody followed you.', { sanity: 1 })],
    codex: ['The Blood Shadow in Hangzhou', 'A Blood Shadow assassin dies in a Hangzhou alley with a half-finished contract and the Silent Death Needle. Burn the contract in front of her before she dies, and the debt dies with her.'],
    mem: ['Take the needles and burn the contract before her eyes', 'She watched the paper burn and smiled. "Clever," she said. "Nobody thinks of that." The needles were yours, and the debt was ash.', { infamy: 1 }] },
];
const tplDying = template('fo_dying', DYING, (r) => E('fo_dying', 'fortune', {
  if: { age: [14, 70], noManual: r.manual, chance: 0.4, ...r.if }, art: r.art, title: r.title, text: r.text,
  choices: [
    C(r.stay[0], O(r.stay[1], { manual: r.manual, ...r.stay[2], codex: cx(`secret.fo_dm_${r.key}`, 'secrets', r.codex) })),
    C(r.other[0], r.other[1]),
    ...(r.extra || []),
    M(r.mem[0], `secret.fo_dm_${r.key}`, O(r.mem[1], { manual: r.manual, mastery: { [r.manual]: 20 }, ...r.mem[2] })),
  ],
}));

// ── Template: thousand-year herbs ────────────────────────────────
// Harvest it properly (a roll), or take the quick, costly shortcut.
const HERBS = [
  { key: 'tiger_ginseng', if: { region: 'liaodong' }, danger: true, art: 'snow', title: 'The tiger’s ginseng', text: 'In the birch forests of Liaodong, red berries in the snow mark a thousand-year ginseng. Curled around its stem, fast asleep, is a tiger.',
    pick: ['Dig around the sleeping tiger', 'body', 40, O('You dug for an hour, a finger’s width at a time, while the tiger snored. When you lifted the root out, the tiger opened one eye, looked at you, and went back to sleep. You do not want to know why.', { item: { spirit_ginseng: 1 }, flag: 'fo.luck+=1' }), O('The tiger woke. You escaped up a birch and spent the night there, while the tiger ate the berries out of spite.', { health: -15, injury: { name: 'claw marks', seasons: 4, sev: 6 } })],
    quick: ['Take only the berries', O('The berries alone warmed you through the winter. The tiger did not wake. The root is still there.', { qi: 15, health: 5 })] },
  { key: 'snow_lotus', if: { loc: 'kunlun', season: [1, 2] }, art: 'snow', title: 'A lotus in the ice', text: 'On a ledge of the Kunlun glacier, out of season and out of reason, a single Snow Lotus has bloomed, white as the ice and glowing faintly at the heart.',
    pick: ['Climb to the ledge', 'body', 45, O('You climbed with your fingers in the ice and your heart in your mouth, and wrapped the lotus in your shirt against your skin.', { item: { snow_lotus: 1 } }), O('The ledge broke. You fell into deep snow, and the lotus fell with you, and was crushed.', { health: -15, qi: 10 })],
    quick: ['Eat it where it grows', O('It tasted of cold water and starlight. Every wound you carry closed at once.', { heal: true, qi: 20 })] },
  { key: 'sun_grass', if: { constitution: 'nine_yin', region: 'west', locType: 'frontier' }, danger: true, art: 'desert', title: 'Sun-Scorched Grass', text: 'In a desert ravine beyond Jade Gate grows a grass so full of sun that it smoulders where the wind bends it. A caravan guide warns you that it has killed every man who ate it. Your frozen meridians ache for it.',
    pick: ['Eat it slowly, one blade at a time', 'health', 45, O('It burned like swallowing a lamp. For a week you lay in fever, sweating out a cold you had carried since birth. When it broke, you were warm all the way through for the first time in your life.', { cure: 'nine_yin', achieve: 'cured_cold', health: -25 }), O('It burned too hard and too fast. You lived, and the cold lived with you, a little quieter.', { health: -30, qi: 10 })],
    quick: ['Gather it to sell to the physicians', O('The physicians at Jade Gate paid well and asked who it was for. You said a friend.', { wealth: 60 })] },
  { key: 'lingzhi', if: { loc: 'wudang' }, art: 'mountain', title: 'Purple lingzhi', text: 'On a dead pine above a Wudang ravine grows a lingzhi as purple as a bruise and as wide as a gong. The Daoists say a lingzhi that old grants a decade of life.',
    pick: ['Cut it without bruising it', 'insight', 30, O('You cut it clean and carried it down like an egg. The Wudang Daoists bought it on the spot, for a sum that made you sit down.', { wealth: 120, rep: { orthodox: 3 } }), O('It bruised, and the bruise spread. What you sold was the size of a coin.', { wealth: 15 })],
    quick: ['Eat it in the ravine', O('Bitter enough to make you weep. The Daoists say you will live years longer. They say it with some resentment.', { flag: 'longevity+=5', insight: 2, rep: { orthodox: -2 } })] },
  { key: 'bodhi_seed', if: { loc: 'songshan' }, art: 'temple', title: 'A falling seed', text: 'Under the old bodhi tree of Shaolin, a seed drops from a branch toward your rice bowl. The monks say a seed that falls into your bowl is a sign, and must be given to the Abbot. Nobody is looking.',
    pick: ['Catch it with your chopsticks and swallow it', 'body', 30, O('You caught it and swallowed it before you could think. A great stillness came over you; the monks, seeing your face, bowed.', { sanity: 10, insight: 3, qi: 10 }), O('It bounced off your chopsticks into a monk’s tea. He drank it, and was very calm for a week.', { charm: 1 })],
    quick: ['Give it to the Abbot', O('The Abbot accepted it with a small smile and gave you a pill in exchange, and a look that said he knew you had thought about eating it.', { item: { qi_pill: 1 }, rep: { orthodox: 4 } })] },
  { key: 'dragon_whisker', if: { loc: 'dongting', season: [1, 2] }, art: 'lake', title: 'Dragon-Whisker Grass', text: 'In the deep reeds of Lake Dongting a grass grows that moves against the current, long and golden, like a dragon’s whiskers. It grows only where the water is deepest.',
    pick: ['Dive for it', 'body', 40, O('You dove until your ears rang and came up with a fistful. Steeped, it made your bones feel like green bamboo: light, and very hard to break.', { body: 4 }), O('A Water Fortress patrol found you diving in their lake and charged you a toll for the privilege of being fished out.', { wealth: -10, health: -5 })],
    quick: ['Buy some from the fishermen', O('The fishermen sold you a bundle at a fair price. It was not Dragon-Whisker Grass. It made very good soup.', { wealth: -5, health: 5 })] },
  { key: 'moon_orchid', if: { loc: 'emei', season: 2 }, art: 'moon', title: 'The Seven-Leaf Moon Orchid', text: 'On a cliff below Emei’s Golden Summit, a Seven-Leaf Moon Orchid opens only under the full moon, and only for one night. The nuns say it calms any heart. It hangs directly above a very long drop.',
    pick: ['Climb down to it at moonrise', 'body', 35, O('You picked it under the moon and brewed it as the nuns do. You learned the recipe from the steam, somehow, as if it wanted to be remembered.', { recipe: 'heart_calming', item: { heart_calming: 2 }, sanity: 5 }), O('You missed the bloom by an hour, and the cliff by less.', { health: -10 })],
    quick: ['Just watch it bloom', O('You watched it open, and close, and the moon go down. You came down the mountain feeling as if someone had sung to you.', { sanity: 8 })] },
  { key: 'grave_lily', if: { region: ['shu', 'jingchu'] }, art: 'grave', title: 'The flower on the grave', text: 'On a forgotten grave a black lily has grown, rooted, the gravedigger says, in the heart of whoever lies there. It smells of iron. Demonic cultivators would pay anything for it.',
    pick: ['Eat it and hold it down', 'sanity', 45, O('Cold power, borrowed from the dead. You held it down, and it became yours. Mostly.', { qiFill: 35, sanity: -8 }), O('Whatever was buried there did not want to share. You woke on the grave at dawn with soil under your nails.', { sanity: -15, qi: 10 })],
    quick: ['Pull it up and burn it', O('It screamed a little as it burned. The gravedigger nodded and said it was the right thing. He had been afraid to do it himself.', { sanity: 4, insight: 1 })],
    more: [C('Sell it to a man in a red sash', O('He paid sixty taels and did not ask your name. You hope you never learn what he used it for.', { wealth: 60, rep: { cult: 3 }, infamy: 2 }))] },
  { key: 'nine_bend_vine', if: { crippled: true, region: ['shu', 'jingchu', 'guanzhong'] }, art: 'forest', title: 'The Nine-Bend Vine', text: 'An old woodcutter shows you a vine with nine bends in every stem, climbing a dead cypress. "My grandfather broke his back," he says. "He chewed this for a year and walked again. It hurts, he said. Like being knitted."',
    pick: ['Chew it for a year', 'health', 40, O('It felt like being knitted from the inside by someone who hated knitting. At the end of the year your meridians carried qi again.', { cure: 'crippled', health: -15, sanity: -5 }), O('You gave up after a season. The pain was too much. Your meridians are no better, but your jaw is very strong.', { health: -10 })],
    quick: ['Thank him and leave it for now', O('You thanked him. Some cures cost more than you are ready to pay yet.')] },
  { key: 'ginseng_child', if: { region: 'hebei', locType: ['wild', 'estate'] }, art: 'forest', title: 'The ginseng child', text: 'In the Hebei hills a little boy in a red bib runs past you, giggling, and disappears behind a rock. There is no boy behind the rock, only a ginseng plant with red berries, trembling slightly.',
    pick: ['Tie a red thread to its stem', 'insight', 35, O('You tied the red thread, as your grandmother’s stories said, and it could not run. You dug it up. You felt terrible. It was a Thousand-Year Spirit Ginseng.', { item: { spirit_ginseng: 1 }, sanity: -4 }), O('The thread slipped. In the morning the plant was gone, and small footprints led away into the hills.', { insight: 1 })],
    quick: ['Play with the boy instead', O('You played hide and seek with a ginseng until sunset. It won every round. When you left, there were three red berries on your pack.', { sanity: 6, qi: 10, flag: 'longevity+=1' })] },
];
const tplHerb = template('fo_herb', HERBS, (r) => E('fo_herb', 'fortune', {
  if: { age: [12, 80], chance: 0.35, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [R(r.pick[0], r.pick[1], r.pick[2], r.pick[3], r.pick[4]), C(r.quick[0], r.quick[1]), ...(r.more || [])],
}));

// ── Template: ruins of fallen sects ──────────────────────────────
// Every great sect stands on a smaller one it buried. Search the ruin (and learn its secret), honour it
// another way, or go straight to what you found in another life. Some inheritances come with an heir.
const RUINS = [
  { key: 'sunset_manor', if: { loc: ['zhongnan', 'changan'], noManual: 'zhong_heaven_gate' }, art: 'fire', title: 'Sunset Sword Manor', text: 'South of Chang’an a burned manor stands in a field of wild chrysanthemums. Sixty years ago the Sunset Sword Manor was destroyed in a single night by a rival sect. Nobody will say which. Everyone looks toward Zhongnan when they don’t say it.',
    search: ['Search the training hall', 'insight', 30, O('Under the scorched floor of the training hall, in a lead box: the Sunset Manor’s sword manual. It is the Heavenly Gate Sword, nearly stroke for stroke, written forty years before Zhongnan claims to have invented it.', { manual: 'zhong_heaven_gate', flag: 'fo.ruin_heir' }), O('The floor gave way into the cellar. You found only ash, and the bones of a child who had hidden there.', { health: -8, sanity: -6 })],
    alt: ['Lay flowers at the gate', O('You laid chrysanthemums at the gate. An old woman watching from the field said, "Nobody does that," and walked away before you could ask her name.', { sanity: 3 })],
    codex: ['The Sunset Sword Manor', 'Zhongnan destroyed the Sunset Sword Manor south of Chang’an sixty years ago for its sword, the Heavenly Gate Sword, which Zhongnan now teaches as its own. The original lies under the third floorboard from the north wall of the training hall.'],
    mem: ['Lift the third floorboard from the north wall', O('Third from the north wall. The lead box was there. This time you also found the letter Zhongnan’s old patriarch sent the night before the attack.', { manual: 'zhong_heaven_gate', flag: 'fo.ruin_heir', rep: { orthodox: -2 }, insight: 2 })] },
  { key: 'iron_palm', if: { loc: 'luoyang' }, art: 'city', title: 'The Iron Palm Hall', text: 'In a Luoyang back street a gutted hall still has its sign over the door: IRON PALM GANG. The Murim Alliance destroyed them thirty years ago for "unorthodox practices." Their old neighbours say the gang were the only ones who ever paid fair wages.',
    search: ['Search behind the walls', 'insight', 35, O('Behind a false wall, the gang’s ledger: every bribe the Alliance elders took to look away, until the gang stopped paying and the elders stopped looking away. You copied it and sold the copy to a storyteller.', { fame: 4, rep: { orthodox: -6 }, insight: 2 }), O('You found a rat’s nest and an old woman who chased you out with a broom.', { charm: -1 })],
    alt: ['Sell the beams for timber', O('The beams were good ironwood. A carpenter paid well and asked no questions.', { wealth: 25 })],
    codex: ['The Iron Palm ledger', 'The Iron Palm Gang of Luoyang kept a ledger of every bribe the Alliance elders took from them. It is behind a false wall in their burned hall.'],
    mem: ['Go straight to the false wall and nail the ledger to the Alliance gate', O('You nailed copies of the ledger to the Alliance’s gate. Half of Luoyang laughed for a week. The other half started making lists of their own.', { fame: 6, rep: { orthodox: -8 }, gaze: 1 })] },
  { key: 'five_poisons', if: { region: 'shu', notSect: 'dang' }, danger: true, art: 'temple', title: 'The Five Poisons Altar', text: 'In the jungle south of Chengdu, vines have swallowed a stepped altar carved with toads, centipedes, scorpions, snakes and spiders. The Five Poisons Sect worshipped here, until the Dang family decided Shu had room for only one poison clan.',
    search: ['Search under the altar', 'insight', 40, O('Under the altar, in jars sealed with wax: the Five Poisons Sect’s antidotes, and the recipe for a pill the Dang never managed to steal.', { recipe: 'foundation_pill', item: { serpent_gall: 1 } }), O('The altar’s guardians were still alive: a centipede the length of your arm, and its several thousand children.', { health: -20, injury: { name: 'centipede venom', seasons: 4, sev: 8 } })],
    alt: ['Tell the Dang where it is', O('The Dang sent men with fire. They paid you in silver, and in a long, considering look.', { wealth: 30, rep: { families: 5 } })],
    codex: ['The Five Poisons Altar', 'South of Chengdu, under a jungle altar, the destroyed Five Poisons Sect left sealed jars and the Foundation-Settling Pill recipe. Its guardian centipedes flee from roosters.'],
    mem: ['Bring a rooster, and let it go in first', O('The old stories were right: centipedes hate roosters. The rooster walked in like a general. You followed it and took the jars.', { recipe: 'foundation_pill', item: { serpent_gall: 1 } })] },
  { key: 'white_crane', if: { region: 'jingchu', realm: '>=2', noManual: 'wu_ladder' }, art: 'temple', title: 'White Crane Monastery', text: 'On a cliff across the river from Wudang stand the ruins of the White Crane Monastery, emptied by plague a century ago. Cranes nest in the broken roofs. They watch you climb with polite interest.',
    search: ['Climb to the highest roof', 'body', 45, O('On the highest roof, in a crane’s nest woven from scripture, you found pages of a lightness art. The monks had learned to fly from the cranes; Wudang’s Ladder to the Clouds was once theirs.', { manual: 'wu_ladder' }), O('The cranes did not like you on the highest roof. Neither did the roof.', { health: -15 })],
    alt: ['Pray for the plague dead', O('You burned incense in the empty hall. The cranes, all at once, bowed their heads. You will never be sure you did not imagine it.', { sanity: 6 })],
    codex: ['White Crane Monastery', 'The ruins of the White Crane Monastery across the river from Wudang hold the original Ladder to the Clouds, woven into the highest crane’s nest. Climb at dusk, when the cranes are out feeding.'],
    mem: ['Climb at dusk, while the cranes are feeding', O('At dusk the nests were empty. You took the scripture pages and left the cranes a fish.', { manual: 'wu_ladder', mastery: { wu_ladder: 10 } })] },
  { key: 'northern_sea', if: { region: 'liaodong', realm: '>=4', noManual: 'moy_star_shift' }, art: 'snow', title: 'The Northern Sea Palace', text: 'On a frozen beach in Liaodong the pillars of the Northern Sea Palace stand in the ice like the ribs of a whale. The Moyong say the palace fell to a storm. The Moyong say a great many things, in that polite, final way of theirs.',
    search: ['Read the frozen hall', 'insight', 50, O('In a frozen hall the palace’s last master had cut a palm art into the ice of the floor, each move turning an enemy’s force back on itself: the Star-Shifting Palm, before the Moyong had it.', { manual: 'moy_star_shift', flag: 'fo.ruin_heir' }), O('You stood in the frozen hall until your thoughts froze too. Moyong guards found you and walked you, very politely, off their beach.', { health: -10, rep: { families: -5 } })],
    alt: ['Ask the Moyong about it', O('Moyong Baek’s steward listened, smiled, and served you tea so cold it hurt your teeth. You understood you would not be asking again.', { rep: { families: 1 } })],
    codex: ['The Northern Sea Palace', 'The Moyong did not lose the Northern Sea Palace to a storm; they took it. The original Star-Shifting Palm is cut into its frozen hall floor. Read it from the throne outward.'],
    mem: ['Read the floor from the throne outward', O('From the throne outward, the cuts were an argument against force itself. You understood it by nightfall, and left before the Moyong patrol.', { manual: 'moy_star_shift', gaze: 1, flag: 'fo.ruin_heir' })] },
  { key: 'black_tortoise', if: { region: 'hebei', noManual: 'kong_iron_wall' }, art: 'battlefield', title: 'The Black Tortoise Fort', text: 'In the hills of Hebei a fortress built like a turtle’s shell lies cracked open down its spine. The Black Tortoise family held it against three armies, and lost it to a single traitor at the gate.',
    search: ['Climb into the inner keep', 'body', 35, O('In the inner keep, the family’s art was carved on the walls of the last room they held: a way of standing like a wall that does not fall. Kongtong’s Iron Wall is a cousin of it, and a poor one.', { manual: 'kong_iron_wall', body: 1 }), O('The cracked shell shifted while you climbed. You got out from under the stones with a cracked rib of your own.', { injury: { name: 'cracked rib', seasons: 4, sev: 10 } })],
    alt: ['Salvage the iron gates', O('The gates were good iron. A smith in the nearest town paid you by weight.', { wealth: 35 })],
    codex: ['The Black Tortoise Fort', 'The Black Tortoise family’s cracked fortress in Hebei hides a wall-standing art in its last keep. The postern the traitor opened is still unbarred.'],
    mem: ['Walk in through the traitor’s postern', O('The traitor’s postern was still unbarred, after a century. You walked in the way the enemy had. It felt like a kind of justice, or its opposite.', { manual: 'kong_iron_wall', sanity: -2 })] },
  { key: 'golden_crow', if: { region: 'west', locType: 'frontier', noManual: 'cult_mind' }, art: 'desert', title: 'Temple of the Golden Crow', text: 'A sandstorm uncovers the roof of a temple to a three-legged crow, buried for centuries outside Jade Gate. The Cult claims its first Heavenly Demon studied here. The Cult claims a great deal.',
    search: ['Read the bronze plates in the sanctum', 'sanity', 50, O('In the sanctum, a heart method burned into a bronze plate: qi drawn from hunger and anger, burning hot and fast. The Cult’s Demon Mind Method, or its grandfather. You read it once and could not forget it.', { manual: 'cult_mind', sanity: -6 }), O('The sanctum was full of voices. You came out days later with sand in your mouth and someone else’s anger in your chest.', { sanity: -15, qi: 15 })],
    alt: ['Let the sand cover it again', O('You let the wind bury it. Some temples are buried for good reasons.', { sanity: 3 })],
    codex: ['The Golden Crow Temple', 'A buried sun temple outside Jade Gate holds the Cult’s first heart method on bronze plates. The outer plates teach breath and fire safely; the plates in the sanctum teach hunger.'],
    mem: ['Read only the outer plates', O('The outer plates were the safe half: breath and fire without the hunger. You left the sanctum unread.', { qi: 25, insight: 3 })] },
  { key: 'thousand_hand', if: { loc: ['chengdu', 'emei', 'qingcheng'], noManual: 'dang_needles' }, art: 'fire', title: 'The Thousand-Hand Hall', text: 'In the hills above Chengdu, the Thousand-Hand Hall was a hidden-weapons school famous for never missing. The Dang family burned it to the ground and, within a year, never missed either.',
    search: ['Study the practice yard', 'insight', 35, O('In the practice yard, a thousand needle holes in a wooden wall formed a pattern, and the pattern formed a method. The Dang’s Ten Thousand Flowers began here.', { manual: 'dang_needles', rep: { families: -4 }, flag: 'fo.ruin_heir' }), O('An old trap in the practice yard was still loaded. It did not miss either.', { injury: { name: 'needle in the thigh', seasons: 3, sev: 8 } })],
    alt: ['Dig the old needles out of the wall', O('Old needles, good steel. A Chengdu smith paid well for them, asked where they came from, and then decided he did not want to know.', { wealth: 20 })],
    codex: ['The Thousand-Hand Hall', 'The Dang took their hidden-weapon art from the Thousand-Hand Hall above Chengdu, which they burned. Its method is a pattern of needle holes in the practice yard wall, read from the shooter’s mark.'],
    mem: ['Read the wall from the shooter’s mark', O('From the shooter’s mark, the holes made sense at once. You took the method and left the needles.', { manual: 'dang_needles', mastery: { dang_needles: 15 }, flag: 'fo.ruin_heir' })] },
  { key: 'wine_immortal', if: { loc: ['luoyang', 'kaifeng'], age: [16, 80], noManual: 'beg_drunk_step' }, art: 'feast', title: 'The Wine Immortal Sect', text: 'The Wine Immortal Sect brewed, drank and fought, in roughly that order, until a feud with a temperance-minded Shaolin abbot ended badly for everyone. Their ruined brewery still has a cellar. The cellar still has wine.',
    search: ['Drink your way through the cellar', 'health', 50, O('You drank through the cellar, as the rule on the door required, and on the third night your feet began to move on their own, beautifully. The Beggars’ Drunken Immortal Steps were stolen from here, and badly.', { manual: 'beg_drunk_step', health: -10, flag: 'fo.ruin_heir' }), O('You drank through a third of the cellar and woke in a ditch outside the city with no shoes.', { health: -15, wealth: -5 })],
    alt: ['Sell the wine', O('Hundred-year wine. A tavern keeper wept as he paid you.', { wealth: 50 })],
    codex: ['The Wine Immortal cellar', 'The ruined Wine Immortal brewery has a cellar of hundred-year wine and a rule on the door: drink to learn. The jars marked with a crane hold the art; the rest only hold a headache.'],
    mem: ['Drink only the jars marked with a crane', O('Only the crane jars, as the founder intended. Two nights, not three, and your feet knew the steps by dawn.', { manual: 'beg_drunk_step', health: -5, flag: 'fo.ruin_heir' })] },
  { key: 'jade_maiden', if: { region: ['guanzhong', 'shu'], locType: 'sect', realm: '>=3', noManual: 'emei_buddha_light' }, danger: true, art: 'mountain', title: 'Jade Maiden Peak', text: 'A sect of women once lived on a peak above the cloud line, until their last leader went mad in seclusion and killed every one of her disciples in a single night. The halls are still clean. Somebody, or something, sweeps them.',
    search: ['Read the seclusion chamber walls', 'insight', 50, O('In the leader’s chamber, a heart method written on the walls in a calm hand that grew less calm with each line. The first half is a light as pure as Emei’s Golden Summit. You stopped reading before the second half.', { manual: 'emei_buddha_light', sanity: -10 }), O('You read too far. For a month after, you woke every night at the hour she killed them, certain you had heard a broom.', { sanity: -18 })],
    alt: ['Sweep the hall yourself, and leave', O('You swept the hall, carefully. When you looked back from the path, a lamp had been lit in the window.', { sanity: 4, insight: 1 })],
    codex: ['Jade Maiden Peak', 'On Jade Maiden Peak, the mad leader’s seclusion chamber holds a heart method like Emei’s Buddha’s Light. The first half is pure. Stop at the line about the moon, or her madness comes with it.'],
    mem: ['Stop at the line about the moon', O('You knew where to stop. You stopped there. The light was enough.', { manual: 'emei_buddha_light', sanity: -2 })] },
];
const tplRuin = template('fo_ruin', RUINS, (r) => E('fo_ruin', 'fortune', {
  if: { age: r.age || [14, 80], chance: 0.35, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [
    R(r.search[0], r.search[1], r.search[2], { ...r.search[3], codex: cx(`secret.fo_ruin_${r.key}`, 'secrets', r.codex) }, r.search[4]),
    C(r.alt[0], r.alt[1]),
    M(r.mem[0], `secret.fo_ruin_${r.key}`, r.mem[1]),
  ],
}));

// ── Template: heavenly omens ─────────────────────────────────────
// Read the omen, act on it (a roll), or shrug it off.
const OMENS = [
  { key: 'white_rainbow', if: { locType: 'city', age: [12, 200] }, art: 'city', title: 'A white rainbow pierces the sun', text: 'At noon a pale white rainbow cuts straight across the sun. The old men in the market go quiet. A white rainbow through the sun means an assassin is about to strike at someone great.',
    read: ['Burn incense for the great', O('You burned incense for whoever it was. Three days later came news of a magistrate stabbed in his sedan chair. Your incense did him no good, but you felt better.', { sanity: 2 })],
    act: ['Watch the magistrate’s road', 'insight', 40, O('You spotted the man with the long sleeves and the too-calm face, and shouted. The magistrate lived. He rewarded you, and his enemies noticed who had shouted.', { fame: 4, rep: { court: 6, unorthodox: -4 }, wealth: 20 }), O('You watched the wrong road. The assassin did not.', { sanity: -3 })],
    shrug: ['It is only weather', O('It was only weather, you told yourself. The magistrate, three days later, would have disagreed.')] },
  { key: 'blood_moon', if: { age: [14, 200], realm: '>=1' }, art: 'moon', title: 'Blood moon', text: 'The moon rises red as a wound. Dogs howl. On such nights, the old texts say, demonic qi rises out of the earth, and those who drink it grow fast and strange.',
    read: ['Shut the shutters and sleep', O('You slept badly and woke well. Your neighbour’s son, who did not shut his shutters, was never quite the same.', { sanity: 1 })],
    act: ['Cultivate under it', 'sanity', 55, O('You drank the red light and kept your own mind. In the morning your qi had grown like a weed, and by noon your eyes were their own colour again.', { qi: 30, sanity: -4 }), O('You drank the red light and something drank you back. You were cruel all month, and enjoyed it.', { qi: 25, sanity: -15, infamy: 2 })],
    shrug: ['Watch it with a jar of wine', O('Red moon, white wine. It was, honestly, very beautiful.', { sanity: 3 })] },
  { key: 'summer_snow', if: { season: 1, locType: ['city', 'village'], age: [12, 200] }, art: 'snow', title: 'Snow in midsummer', text: 'In the middle of summer, snow falls on the town square, thick and silent, and only there. Yesterday a young widow was executed in that square for poisoning her husband. She swore to the end that she had not.',
    read: ['Pray for her', O('You prayed for her. The snow melted by noon. The magistrate did not sleep that night, or the next.', { sanity: 2 })],
    act: ['Find out who really did it', 'insight', 45, O('The husband’s brother had bought the arsenic. It took you a month to prove it, and the magistrate an afternoon to hang him. The widow’s grave is never without flowers now.', { fame: 5, sanity: 6, rep: { court: -3 } }), O('Every door closed in your face. The magistrate sent a man to warn you off. The snow did not fall again.', { sanity: -6 })],
    shrug: ['Stay out of it', O('You stayed out of it. People in the town stopped meeting each other’s eyes for a while.', { sanity: -3 })] },
  { key: 'five_planets', if: { age: [14, 200], realm: '>=2', year: [40, 300] }, art: 'moon', title: 'Five stars in a line', text: 'Five planets hang in a line across the dawn sky like beads on a string. Astrologers say it happens once in a lifetime, and that what is begun under it does not end.',
    read: ['Begin something', O('You began a letter you had been afraid to write. It did not end. You are still writing it, in a way.', { sanity: 4, charm: 1 })],
    act: ['Meditate until they fade', 'insight', 40, O('As the five lights faded into the day, your qi aligned with them, one meridian at a time. You understood something about order that you cannot put into words.', { insight: 5, qi: 20 }), O('You meditated until they faded, and nothing aligned except your knees, which locked.', { insight: 1 })],
    shrug: ['Go back to bed', O('You went back to bed. Once a lifetime is once too often to get up that early.')] },
  { key: 'broom_star', if: { year: [26, 33], age: [14, 200] }, art: 'storm', title: 'A broom star', text: 'A comet with a long tail like a broom has hung in the western sky for a month, pointing east. The astrologers say a broom star sweeps away the old order. The grain merchants are already raising prices.',
    read: ['Read the old almanacs about broom stars', O('Every broom star in the almanacs came before a war from the west. You closed the book and sat for a while.', { insight: 2, codex: { id: 'secret.fo_broom_star', cat: 'timeline', title: 'The broom star', text: 'A broom star hangs in the west, pointing east, in the years before the Cult marches. The almanacs record one before every war from the west.' } })],
    act: ['Buy grain before the merchants do', 'insight', 35, O('You bought early, stored it dry, and sold it when the panic came. Some called it shrewd. Some called it something else.', { wealth: 60, sanity: -2 }), O('You bought late, at the top, and the panic passed. The rats ate well.', { wealth: -20 })],
    shrug: ['It is only a star', O('It is only a star, you told yourself, and it went on pointing east.')] },
  { key: 'thousand_cranes', if: { loc: ['wudang', 'zhongnan', 'emei'], age: [10, 200] }, art: 'mountain', title: 'A thousand cranes', text: 'A thousand cranes circle the peak in a slow white wheel, crying. The Daoists come out of their halls and kneel in silence. Somewhere on the mountain someone very old has just become immortal, or has just died; the Daoists say these are the same thing.',
    read: ['Kneel with the Daoists', O('You knelt with them until the cranes flew west. An old Daoist told you that anyone who sees the cranes will live long. He seemed sure.', { flag: 'longevity+=1', sanity: 5 })],
    act: ['Climb to where they circle', 'body', 40, O('At the centre of the wheel, on a bare peak, a pair of straw sandals sat neatly side by side, and nothing else. You sat beside them and breathed, and breathed.', { qi: 20, insight: 3, sanity: 3 }), O('You climbed until the cranes scattered at your clumsy approach. The Daoists were not happy with you.', { rep: { orthodox: -3 }, health: -5 })],
    shrug: ['Keep walking', O('You kept walking, and felt somehow that you had missed a funeral, or a wedding.')] },
  { key: 'dragon_drinks', if: { loc: ['dongting', 'wuchang', 'hangzhou'], season: [1, 2], age: [10, 200] }, danger: true, art: 'storm', title: 'A dragon drinks', text: 'A black cloud shaped exactly like a dragon comes down out of the sky and drinks from the water in a long, twisting column of grey. Boats scatter. The fishermen say a dragon drinking means a flood, or a king being born.',
    read: ['Help pull the boats ashore', O('You hauled boats until your hands bled. The waterspout passed. The fishermen gave you a basket of fish and, for a while, a name: the one who pulls.', { fame: 2, body: 1 })],
    act: ['Row out toward it', 'body', 50, O('You rowed to the edge of the column and let the wind roar through you. For one breath you felt the qi of the whole sky moving. Then you rowed back, very fast, laughing.', { qi: 30, insight: 2 }), O('The waterspout threw your boat thirty feet. You woke on the shore with weed in your hair and no boat.', { health: -20, wealth: -10 })],
    shrug: ['Watch from the shore', O('You watched from the shore until it dissolved into rain. Nobody was born king that you heard of.', { sanity: 2 })] },
  { key: 'three_suns', if: { loc: 'capital', age: [14, 200] }, art: 'palace', title: 'Three suns', text: 'Three suns rise over the Imperial Capital: the true one, and two false ones on either side, ringed in a halo. The court astrologers run through the streets in their slippers. Nobody yet knows whether it is a good omen. It depends who is paying.',
    read: ['Listen to what the astrologers decide', O('By noon they had decided it meant the Emperor was blessed. By evening, a minister who disagreed was in prison. You learned a great deal about omens that day.', { insight: 3 })],
    act: ['Sell your own reading to a minister', 'charm', 40, O('You told a nervous minister that the false suns were his rivals, flanking him. He paid you twenty taels and believed it. So, after a while, did his rivals.', { wealth: 20, rep: { court: 3 }, infamy: 1 }), O('Your reading reached the wrong minister. You spent a night in a Depot cell explaining yourself.', { rep: { court: -5 }, health: -5 })],
    shrug: ['Stay indoors', O('You stayed indoors. In the capital, on days like this, that is the wisest omen there is.')] },
  { key: 'sweet_wells', if: { region: 'shu', year: [77, 80], age: [10, 200] }, art: 'shrine', title: 'The sweet wells', text: 'All over Shu the wells have turned sweet and warm, and the frogs have gone quiet. The old people say it happened once in their grandparents’ time, the season before the earth split open.',
    read: ['Ask the old people what happened then', O('"The mountains walked," a grandmother said. "Half the roofs came down." You wrote down everything she said. You expect to need it.', { insight: 2, codex: { id: 'secret.fo_sweet_wells', cat: 'timeline', title: 'The sweet wells of Shu', text: 'Before the Great Earthquake of Shu in year 80, the wells of Shu turn sweet and warm and the frogs fall silent.' } })],
    act: ['Warn the city to sleep outdoors', 'fame', 30, O('Enough people listened. When the earth split in the autumn, the market squares were full of sleepers under blankets, alive, watching their roofs come down.', { fame: 8, sanity: 5, gaze: 1 }), O('Nobody listens to a stranger about frogs. You slept outdoors alone, and felt foolish, and waited.', { sanity: -2 })],
    shrug: ['Enjoy the sweet water', O('It was very good water. You did not think about it again until autumn.')] },
  { key: 'falling_stars', if: { ...LATER, item: 'wheel_bead', age: [12, 200] }, art: 'moon', title: 'Falling stars', text: 'Stars are falling all night, hundreds of them. At first it is beautiful. Then you notice that every one of them is falling toward you, and the bead under your shirt is hot enough to burn.',
    read: ['Hold the bead and watch', O('The stars fell all around you and none of them landed. By dawn you understood that Heaven had looked straight at you, and you had looked back.', { gaze: 1, insight: 3, sanity: -3 })],
    act: ['Shelter under a temple roof', 'sanity', 40, O('You sat under the temple eaves with the monks until the stars stopped falling. The bead cooled. The monks did not ask, which you appreciated.', { sanity: 3 }), O('Under the temple roof you could still feel them looking. You did not sleep for three days.', { sanity: -8 })],
    shrug: ['Go to sleep', O('You went to sleep. The bead burned a small round mark on your chest that is still there.', { health: -3 })] },
  { key: 'fireflies', if: { season: 1, locType: ['village', 'wild'], age: [8, 200] }, art: 'night', title: 'Fireflies that write', text: 'A field of fireflies rises at dusk and, for a moment, forms a single line of glowing characters across the dark, before it scatters.',
    read: ['Write down what you saw', O('You wrote it down. A scholar later told you it was a line of poetry, misquoted. Even fireflies, apparently, get it wrong.', { insight: 2, charm: 1 })],
    act: ['Read it before it scatters', 'insight', 35, O('It said: "Breathe as the grass does." You laughed, and then tried it, and your qi moved more easily for months.', { qi: 15, sanity: 4 }), O('You caught only the first word, which was "you." It kept you up for weeks.', { sanity: -2 })],
    shrug: ['Catch some in a jar', O('You caught a jarful and let them go at midnight, as children do.', { sanity: 3 })] },
];
const tplOmen = template('fo_omen', OMENS, (r) => E('fo_omen', 'fortune', {
  if: { chance: 0.3, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [C(r.read[0], r.read[1]), R(r.act[0], r.act[1], r.act[2], r.act[3], r.act[4]), C(r.shrug[0], r.shrug[1])],
}));

// ── Template: a strange old man in the teahouse ──────────────────
const TEAHOUSES = [
  { key: 'changan', loc: 'changan', title: 'Old coins', text: 'In a Chang’an teahouse an old man pays for his tea with a coin from a dynasty three hundred years gone. The owner bites it, shrugs, and gives him change. The old man winks at you.',
    sit: ['Pay for his next pot', O('He told you stories of the old capital as if he had walked its streets, which, he said, he had. As he left he tapped your sword arm in three places. It has never felt the same since, in a good way.', { wealth: -1, insight: 3 })],
    test: ['Ask to see the coin', 'insight', 35, O('The coin was real, and so was the faint qi still in it, like a signature. You recognised it from an old scroll: an imperial swordmaster who vanished with the last dynasty. He took the coin back and said, "Clever. Don’t be clever in public."', { insight: 4, codex: { id: 'secret.fo_old_coin', cat: 'people', title: 'The man with old coins', text: 'An old man in a Chang’an teahouse pays with coins three centuries old. He is an imperial swordmaster of a dead dynasty, who never died. He respects tact.' } }), O('It was just an old coin, you decided. The old man looked faintly disappointed in you.')],
    leave: ['Mind your own business', O('You minded your own business. The old man finished his tea and was not there when you looked again.')] },
  { key: 'luoyang', loc: 'luoyang', if: { notMet: 'beggar_chief' }, title: 'A cheat at xiangqi', text: 'In a Luoyang teahouse a filthy old beggar with nine fingers is cheating at xiangqi, badly, against a merchant who has not noticed. He catches you noticing, and raises an eyebrow.',
    sit: ['Say nothing and buy him a dumpling', O('He ate the dumpling, and yours. Then he said, "The Beggars’ Sect remembers who feeds it," and introduced himself as Hong Chil. You realised, belatedly, who that was.', { meet: '@beggar_chief', rel: { '@beggar_chief': { aff: 15 } }, wealth: -1 })],
    test: ['Beat him at his own game', 'insight', 45, O('You cheated better than he did. He laughed so hard he fell off his stool. "Nine fingers and I never saw it," he said. "Hong Chil. Come and find me when you want to learn something real."', { meet: '@beggar_chief', rel: { '@beggar_chief': { res: 20, aff: 10 } }, insight: 1 }), O('He beat you and took your money, cheating openly now, grinning. "Hong Chil," he said, pocketing it. "Thank you for the lesson fee."', { meet: '@beggar_chief', wealth: -5 })],
    leave: ['Warn the merchant', O('The merchant threw the beggar out. He went cheerfully, taking the merchant’s purse with him. You never saw how.', { charm: 1 })] },
  { key: 'kaifeng', loc: 'kaifeng', if: { ...LATER }, title: 'A fortune for free', text: 'In a Kaifeng teahouse an old fortune-teller refuses your coin. "I don’t read for people who have already read the ending," he says. "Sit anyway. Drink. Tell me how it ends."',
    sit: ['Tell him how it ends', O('You told him about the war, the Blood Night, the year of the flood. He listened as if to a story. At the end he said, "Then don’t do it the same way," and poured you more tea.', { sanity: 5, gaze: -1 })],
    test: ['Ask him how he knew', 'charm', 40, O('"Your eyes," he said. "And because I died nine times, once, before I stopped. It is a long story. You have time." He told it. You learned more than you wanted about the price of knowing.', { insight: 4, burden: -1 }), O('He only smiled and said that every teahouse has its secrets.')],
    leave: ['Leave quickly', O('You left quickly. You could feel him watching you all the way down the street, kindly.', { sanity: -1 })] },
  { key: 'wuchang', loc: 'wuchang', title: 'The old boatman', text: 'In a tea stall on the Wuchang docks an old boatman drinks his tea in one breath and then holds it so long you start to worry. "Sixty years on the river," he says, finally exhaling. "You learn to breathe like the fish, or you drown like the rest."',
    sit: ['Ask him to teach you', O('He took you out in his boat and pushed you overboard, repeatedly, for a month. By the end you could hold your breath for a count of four hundred.', { body: 2, qi: 15 })],
    test: ['Race him across the river', 'body', 45, O('You beat him across, barely, and he laughed and called you a fish. He taught you the rest for free.', { body: 3, qi: 15, health: -5 }), O('Halfway across, he was already sitting on the far bank, drinking tea. A ferryman fished you out.', { health: -8 })],
    leave: ['Drink up and go', O('You drank up and went. Somewhere behind you, someone was still holding his breath.')] },
  { key: 'chengdu', loc: 'chengdu', title: 'The pepper challenge', text: 'In a Chengdu teahouse an old man eats Sichuan peppers by the handful, without water and without expression. A sign beside him reads: “EAT MORE THAN ME AND I TEACH YOU SOMETHING.”',
    sit: ['Order him a cup of milk', O('He drank it in one swallow and laughed until he cried. "Sensible," he said, and told you which peppers in the market are not peppers.', { insight: 2, wealth: -1 })],
    test: ['Accept the challenge', 'health', 50, O('You ate until you could not see. He ate one more, then conceded with a bow. "Dang Ok-ran’s cousin," he said. "Retired." He taught you how poison moves through the body, by comparison with peppers.', { recipe: 'healing_salve', insight: 3, health: -5 }), O('You lost after the ninth handful and spent the night with your face in a water trough. He left you a note: "Nobody beats me."', { health: -10 })],
    leave: ['Back away', O('You backed away. Your eyes watered just from watching.')] },
  { key: 'hangzhou', loc: 'hangzhou', title: 'The tea master', text: 'In a Hangzhou teahouse by West Lake an old tea master pours you a cup without being asked, studies the leaves at the bottom after you drink, and frowns.',
    sit: ['Ask what he sees', O('"A long road," he said, "and someone at the end who will not be glad to see you." He gave you a brick of his own tea for the road, which was the best thing that happened all year.', { item: { tea_brick: 1 }, sanity: 2 })],
    test: ['Read his cup in return', 'insight', 40, O('You read his leaves back at him: a debt, an old love, a daughter he has not spoken to. He went very quiet, then smiled. "Nobody has read my cup in thirty years." He taught you how to sit still for a whole pot.', { insight: 3, sanity: 4, charm: 1 }), O('You read his leaves and said something about wealth. He laughed politely. Everyone says wealth.', { charm: -1 })],
    leave: ['Pay and leave', O('You paid. The tea was very good. You did not want to know about the leaves.')] },
  { key: 'capital', loc: 'capital', age: [16, 80], title: 'The needle case', text: 'In a quiet teahouse near the palace an old eunuch with powdered cheeks sits with a lacquered needle case beside his cup. A fly lands on the table and falls dead. You did not see his hand move.',
    sit: ['Bow and offer him the seat by the window', O('He accepted it as his due. As he left he said softly, "Polite children live longer in this city," and pressed a pill into your hand. It was not poison. You checked.', { item: { qi_pill: 1 }, rep: { court: 2 } })],
    test: ['Ask him to teach you that', 'charm', 50, O('He looked at you a long time. "Everything has a price," he said. He taught you a little, over a season, and the price was a few small favours inside the palace walls that you will not describe.', { insight: 3, mastery: { court_withered_flower: 15, uno_silent_needle: 15, emei_needles: 15, dang_needles: 15 }, rep: { court: 4 }, infamy: 3, sanity: -4 }), O('He smiled, and you woke the next morning on the teahouse floor with a small hole in your earlobe and no memory of how it got there.', { health: -5, sanity: -4 })],
    leave: ['Leave very calmly', O('You left very calmly. You are not ashamed to say you did not look back.')] },
  { key: 'jadegate', loc: 'jadegate', title: 'A traveller from the west', text: 'In the caravan inn at Jade Gate an old man from somewhere beyond the deserts plays a stringed instrument shaped like a pear. The music goes places the zither cannot. Everyone in the inn has stopped talking.',
    sit: ['Sit and listen until he stops', O('He played until dawn. When he stopped, you found that you had been crying, and that something sore in you had stopped being sore.', { sanity: 10 })],
    test: ['Ask about the lands he came from', 'charm', 30, O('He told you of cities of blue tile and rivers of sand, and of a fighting art there in which the hand stays open, like a beggar’s, until it is not. You practised it in your head for weeks.', { insight: 3, codex: { id: 'secret.fo_open_hand', cat: 'theory', title: 'The open hand', text: 'A traveller from beyond the western deserts described an art in which the hand stays open until the moment of striking. It saves qi, and it lies.' } }), O('His language and yours met only in hand-waving. You learned his word for wine.', { charm: 1 })],
    leave: ['Go to bed', O('You went to bed. The music came up through the floorboards all night, and you dreamed of blue cities.', { sanity: 3 })] },
  { key: 'willow', loc: 'willow', age: [6, 13], title: 'The tea-stall grandfather', text: 'The old man who runs the tea stall by the Willow Creek bridge watches you swing a stick at the reeds. "Wrong," he says. "Hold it like a writing brush. Now again."',
    sit: ['Do as he says', O('He corrected you every afternoon for a summer, for the price of fetching his water. In autumn he gave you a wooden sword he had carved himself, and would not say where he had learned.', { item: { wooden_sword: 1 }, body: 2, insight: 1 })],
    test: ['Ask him if he was a master', 'charm', 25, O('"Mount Hua," he said, after a long time. "Before you were born. Before I was a coward." He would not say more, but he taught you to stand.', { insight: 2, body: 1, codex: { id: 'secret.fo_teastall_elder', cat: 'people', title: 'The tea-stall grandfather', text: 'The old man at the Willow Creek tea stall was once a Mount Hua swordsman who fled a battle. He will teach a child who fetches his water, and never an adult.' } }), O('"Just an old man," he said, and served you tea with too much sugar.', { health: 1 })],
    leave: ['Run off to play', O('You ran off to play. He watched you go, and went back to his kettle.')] },
];
const tplTeahouse = template('fo_teahouse', TEAHOUSES, (r) => E('fo_teahouse', 'fortune', {
  if: { loc: r.loc, age: r.age || [14, 80], chance: 0.35, ...r.if }, art: 'inn', title: r.title, text: r.text,
  choices: [C(r.sit[0], r.sit[1]), R(r.test[0], r.test[1], r.test[2], r.test[3], r.test[4]), C(r.leave[0], r.leave[1])],
}));

// ── Template: sealed tombs ───────────────────────────────────────
// Open it (a roll), or leave it to its owners, the court or the dead.
const TOMBS = [
  { key: 'clay_army', if: { loc: ['changan', 'zhongnan', 'willow'] }, danger: true, art: 'grave', title: 'The bronze general', text: 'A farmer digging a well outside Chang’an breaks through into a tomb full of clay soldiers, row after row, facing east. At the end of the hall is a bronze door. The farmer is already filling his well back in.',
    open: ['Look for the traps, then the door', 'insight', 40, O('Crossbows in the walls, still strung after a thousand years; you found every trigger. Behind the bronze door lay a general’s sword, green with age and sharp as the day it was forged, and a chest of ancient coins.', { item: { fine_sword: 1 }, wealth: 50, sanity: -2, flag: 'fo.luck+=1' }), O('The crossbows were still strung after a thousand years. One of them was faster than you.', { injury: { name: 'bronze bolt', seasons: 4, sev: 14 } })],
    alt: ['Help the farmer fill it in', O('You helped him fill it in. The clay soldiers watched you do it. You dream of them sometimes, still facing east, still waiting.', { sanity: 2, body: 1 })] },
  { key: 'consort', if: { region: 'hebei', locType: ['city', 'wild', 'estate'] }, danger: true, art: 'palace', title: 'The consort’s tomb', text: 'Tomb robbers in Hebei have broken into the tomb of an imperial consort and run away screaming. The passage they dug is still open. The air coming out of it smells of mercury.',
    open: ['Go in with a wet cloth over your face', 'health', 50, O('Rivers of mercury on the floor, and a consort asleep in jade on an island in the middle. You took her pendants and her gold, and apologised. The court considers robbing imperial tombs a form of treason.', { item: { jade_pendant: 3 }, wealth: 100, rep: { court: -10 }, health: -10, flag: ['fo.whispers', 'fo.luck+=1'] }), O('The mercury got into your lungs before you got out.', { health: -25, injury: { name: 'mercury lungs', seasons: 6, sev: 8 } })],
    alt: ['Report it to the magistrate', O('The magistrate posted soldiers and sent the robbers’ names to the capital. They gave you five taels and a look.', { wealth: 5, rep: { court: 4 } })] },
  { key: 'poisoner', if: { region: 'shu', notSect: 'dang' }, danger: true, art: 'grave', title: 'The poisoner’s tomb', text: 'The tomb of a Dang ancestor, a poisoner so feared that the family buried him outside their walls, lies open after a landslide. The flowers around it are dead. The snakes are dead. The landslide, somehow, looks dead too.',
    open: ['Read the inscriptions before you touch anything', 'insight', 45, O('The inscriptions were his last joke: every warning was a recipe, and every recipe a warning. You copied the useful ones and touched nothing.', { recipe: ['foundation_pill', 'heart_calming'], mastery: { dang_poison_canon: 20, med_five_venoms: 20, dang_needles: 10 }, rep: { families: -3 } }), O('You touched something.', { health: -25, injury: { name: 'tomb poison', seasons: 6, sev: 10 } })],
    alt: ['Tell the Dang it is open', O('The Dang came in masks and sealed it again with lead. The matriarch herself sent you a box of sweets, which you did not eat.', { rep: { families: 6 } })] },
  { key: 'stupa', if: { loc: 'songshan' }, art: 'temple', title: 'The first abbot’s stupa', text: 'In Shaolin’s Forest of Stupas, the oldest has cracked in a frost. Through the crack you can see a small bronze box, and inside it something that glows faintly, like a pearl in a dark room.',
    open: ['Reach in and take the box', 'sanity', 55, O('Your hand went in and came out with the box, and your heart did not race once. Inside lay the first abbot’s relic. You held it until your heart opened like a gate, and then you gave it to the monks.', { sanity: 15, qi: 25, insight: 3, rep: { orthodox: 5 } }), O('Your hand shook so badly the box fell further in. A monk found you with your arm in a stupa and was not amused.', { rep: { orthodox: -8 }, sanity: -3 })],
    alt: ['Tell the monks about the crack', O('The monks repaired the stupa in a day, chanting. The Abbot thanked you personally, and you saw in his eyes that he knew you had thought about reaching in.', { rep: { orthodox: 4 }, merit: 5 })] },
  { key: 'demon_elder', if: { region: 'west', noManual: 'cult_demon_palm' }, danger: true, art: 'demonic', title: 'A demon elder’s tomb', text: 'Among the black rocks of the west, a tomb door is carved with a single red hand. The Cult buries its elders with their arts, so that only the strong deserve them. This door was opened from the inside, a long time ago.',
    open: ['Go in', 'power', 60, O('His bones were sitting up, with his manual in his lap. You took it, and the bones fell over, and you decided not to think about which of you had won.', { manual: 'cult_demon_palm', sanity: -6, rep: { cult: 3 } }), O('Whatever opened the door from the inside was still in there. You ran, and it did not follow, and you still do not know what it was.', { sanity: -12, health: -10 })],
    alt: ['Seal the door again', O('You rolled a stone across the door. It took all day. Something on the other side helped push, at the end.', { sanity: -3, body: 1 })] },
  { key: 'golden_pearl', if: { region: ['west', 'jingchu', 'guanzhong'], locType: ['sect', 'wild'], realm: [3, 6], bottleneck: true, stat: { health: '>=55' }, chance: 0.12 }, danger: true, art: 'cave', title: 'The pearl in the tomb', text: 'In a sealed tomb inside a mountain a master sits upright on a stone throne. In his open mouth is a pearl as large as a plum, glowing gold. The inscription reads: "I sealed my qi here for whoever comes to the threshold. Do not be greedy."',
    open: ['Take the pearl into your own mouth', 'health', 55, O('Gold light went down your throat like warm wine and broke your threshold open from the inside. You took nothing else. When you left, the master seemed to be smiling.', { realmUp: true, gaze: 2, flag: 'fo.luck+=2' }), O('The light was too much. It burned through your meridians and out of you, into the air of the tomb, and was gone. You lived. That was all.', { health: -30, injury: { name: 'burned meridians', seasons: 6, sev: 8 }, qi: 15 })],
    alt: ['Leave it for someone who needs it more', O('You bowed to the master and left the pearl. Whoever finds it next will be standing at a threshold too.', { sanity: 5, insight: 2 })],
    more: [C('Take the pearl and the grave goods', O('Greedy. The tomb began to collapse as you reached for the gold. You got out with a purse of grave coins and the pearl, which went dark in your hand.', { wealth: 50, health: -20, sanity: -5 }))] },
  { key: 'butterflies', if: { loc: 'hangzhou' }, art: 'lake', title: 'The butterfly tomb', text: 'On an island in West Lake a double tomb is overgrown with flowers, and a hundred white butterflies rest on it. Two lovers, the boatman says, forbidden to marry, who were buried together after all.',
    open: ['Read the poems carved on the stones', 'insight', 30, O('His poems on one stone, hers on the other, answering each other across a hundred years. You read them all twice and came away a little wiser about what people will die for.', { insight: 3, charm: 3, sanity: -2 }), O('The poems were in an old style you could not follow. The butterflies landed on you anyway.', { charm: 1 })],
    alt: ['Leave an offering of plum wine', O('You left a jar of plum wine. When you looked back from the boat, two butterflies were sitting on its rim.', { sanity: 5, wealth: -2 })] },
  { key: 'strategist', if: { region: 'hebei', noManual: 'jegal_formations' }, art: 'estate', title: 'The strategist’s tomb', text: 'Outside the Jegal Estate stands the tomb of the family’s founder, the greatest strategist of his age. It has no door. The stones around it are arranged in a pattern that makes your eyes slide off it.',
    open: ['Walk the formation', 'insight', 50, O('Eight gates, seven of them death. You took the eighth, and the stones led you inside, where the founder had carved his formations into the walls for anyone clever enough to reach them.', { manual: 'jegal_formations', insight: 2, rep: { families: -3 }, codex: { id: 'secret.fo_jegal_gate', cat: 'secrets', title: 'The eighth gate', text: 'The founder’s tomb outside the Jegal Estate is a formation of eight gates. The eighth, the one that looks most like death, is the way in.' } }), O('You walked the formation for a day and a night and came out where you went in, exhausted, a season older in your bones.', { health: -10, sanity: -5 })],
    alt: ['Ask the Jegal for permission', O('Jegal Mun’s steward laughed, kindly. "If you could get in," he said, "you would not need to ask." It sounded like an invitation. It was not.', { rep: { families: 1 } })],
    more: [M('Take the eighth gate first', 'secret.fo_jegal_gate', O('The eighth gate, the one that looks most like death. You were inside within the hour.', { manual: 'jegal_formations', gaze: 1 }))] },
  { key: 'robbers', if: { region: 'central' }, bind: { x: { ageRel: [-5, 10], minAge: 16, role: 'acquaintance', aff: 25, realm: [0, 2] } }, art: 'grave', title: 'Someone else’s tunnel', text: 'A tomb robbers’ tunnel opens in a field near Luoyang, freshly dug. From somewhere in the dark a voice calls weakly for help. "The roof came down. My partner ran. Please."',
    open: ['Dig them out', 'body', 35, O('You dug for half a day. The robber was {x}, a thin, embarrassed person with a crushed foot and a satchel of tomb jade. {x.He} gave you half the jade and a promise, which {x.he} has kept.', { rel: { x: { aff: 30 } }, wealth: 40, item: { jade_pendant: 1 } }), O('The tunnel collapsed further as you dug. You got {x} out, and nearly stayed down there yourself.', { rel: { x: { aff: 30 } }, health: -15 })],
    alt: ['Fetch the constables', O('The constables dug the robber out and hanged {x.him} in the square the following week. You did not go and watch.', { rep: { court: 3 }, sanity: -6 })],
    more: [C('Keep walking', O('You kept walking. The voice stopped calling sometime in the night.', { sanity: -8 }))] },
  { key: 'river_king', if: { loc: 'dongting', season: 3 }, danger: true, art: 'lake', title: 'The drowned king', text: 'In the dry winter the waters of Dongting drop to their lowest in fifty years, and an island appears with a door in it: the tomb of a river king from before the empire, who ruled the lake with a thousand boats.',
    open: ['Go in before the water rises', 'body', 40, O('A dead king on a throne of black coral, and a hoard of pearls the fish had been guarding. You took a handful and ran as the lake came back in behind you. The Water Fortress will want a share. They always do.', { wealth: 120, rep: { unorthodox: -4 }, flag: ['fo.whispers', 'fo.luck+=1'] }), O('The lake came back faster than you ran. You got out half drowned, with a single pearl in your fist.', { health: -18, wealth: 15 })],
    alt: ['Sell the location to the Water Fortress', O('Lord Gyeong Pa’s men paid you in silver and a kind of grudging respect. They looted the tomb in a night.', { wealth: 50, rep: { unorthodox: 6 } })] },
];
const tplTomb = template('fo_tomb', TOMBS, (r) => E('fo_tomb', 'fortune', {
  if: { age: [16, 80], chance: 0.3, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.bind ? { bind: r.bind } : {}), ...(r.danger ? { danger: true } : {}),
  choices: [R(r.open[0], r.open[1], r.open[2], r.open[3], r.open[4]), C(r.alt[0], r.alt[1]), ...(r.more || [])],
}));

// ── Template: treasure maps ──────────────────────────────────────
// Follow it (pure chance), sell it, or let it go.
const MAPS = [
  { key: 'pirate', if: { loc: ['dongting', 'wuchang'] }, danger: true, art: 'lake', title: 'A pirate’s chart', text: 'A drowned Water Fortress pirate washes up in the reeds with an oilskin pouch around his neck. Inside, a chart of the lake with a red circle on an island that is only an island in a dry year.',
    follow: ['Follow it in the next dry season', 0.6, O('The island was there, and so was the chest: pirate silver, some still in imperial wrappers. The Water Fortress keeps very good records of what it is owed.', { wealth: 120, rep: { unorthodox: -6 }, flag: 'fo.whispers' }), O('The island was there, and so was a Water Fortress boat, waiting for whoever came with the chart.', { health: -15, wealth: -10 })],
    sell: ['Sell it back to the Water Fortress', O('They paid a quarter of what it was worth and a full measure of goodwill.', { wealth: 30, rep: { unorthodox: 5 } })],
    drop: ['Bury the pirate with his chart', O('You buried him with his chart. Whatever he died for, he can keep.', { sanity: 3 })] },
  { key: 'great_bell', if: { loc: 'songshan' }, art: 'temple', title: 'The map in the sutra', text: 'Tucked into a sutra you borrowed from a Shaolin library is a map in faded monk’s ink of a valley behind Mount Song, marked: "Where the Great Bell was hidden from the bandits."',
    follow: ['Go and find the bell', 0.5, O('In a dry cave behind the valley hung the Great Bell of the old temple, green with age. You struck it once. The note went through your meridians like a cleansing fire. The monks, when you told them, wept.', { qi: 25, insight: 2, rep: { orthodox: 8 } }), O('The valley had moved, as valleys do on old maps. You found only a fine view.', { sanity: 2 })],
    sell: ['Give it to the librarian', O('The librarian took it with trembling hands and sent monks into the hills. You were not invited along, but you were thanked.', { rep: { orthodox: 4 }, merit: 4 })],
    drop: ['Put it back where you found it', O('You put it back. Some things are found when they are meant to be found.')] },
  { key: 'honest_seller', if: { loc: ['changan', 'kaifeng', 'luoyang'], stat: { wealth: '>=15' } }, art: 'market', title: 'An honest map-seller', text: 'A map-seller in the market has a sign: GENUINE TREASURE MAPS, FIFTEEN TAELS, NO REFUNDS. "Most of them are fake," he tells you cheerfully. "One of them isn’t. I forget which."',
    follow: ['Buy one and follow it', 0.15, O('It was the one. Under a broken stele outside the city, a jar of gold coins. You went back to tell the map-seller, and he had already packed up his stall and left town, laughing.', { wealth: 200, flag: 'fo.luck+=1' }), O('Your map led to a pig farm. The farmer had seen a great many people with maps.', { wealth: -15, insight: 1 })],
    sell: ['Buy one and resell it at double', O('You resold it to a young master for thirty taels, with a story about a dying monk. You are now, technically, in the map business.', { wealth: 15, charm: 1, infamy: 1 })],
    drop: ['Shake his hand and walk on', O('You shook his hand. He seemed genuinely pleased to meet someone sensible.', { sanity: 1 })] },
  { key: 'payroll', if: { region: 'west', locType: 'frontier' }, art: 'desert', title: 'The lost payroll', text: 'An old soldier at Jade Gate, dying of drink, gives you a map for a jar of wine: where his company buried the army’s payroll forty years ago, the night before they were massacred. "Nobody left to dig it up," he says. "Nobody but me, and look at me."',
    follow: ['Dig it up', 0.55, O('In the sand by a dead beacon tower: four iron chests of silver under the old emperor’s seal. You took what you could carry. Whoever sees that seal will ask questions.', { wealth: 150, rep: { court: -5 }, flag: 'fo.whispers' }), O('Someone had dug it up years ago. All that was left was a hole and a broken shovel.', { health: -5 })],
    sell: ['Give it to the garrison commander', O('The commander dug it up, paid his men their back wages for the first time in a year, and named you a friend of the garrison.', { rep: { court: 8 }, fame: 3 })],
    drop: ['Drink with him instead', O('You drank with him till dawn and let him tell you about the friends he buried. The map went into the fire somewhere in the middle.', { sanity: 4, wealth: -2 })] },
  { key: 'alchemist', if: { loc: ['wudang', 'zhongnan'] }, art: 'forge', title: 'The alchemist’s directions', text: 'In a used-book stall you find a Daoist alchemist’s diary. The last page gives directions, in a shaking hand, to "my furnace, which I have hidden from my disciples, who are thieves."',
    follow: ['Follow the directions', 0.5, O('Behind a waterfall stood the furnace, still warm somehow, with the last batch of pills inside, perfectly made.', { item: { marrow_pill: 1, qi_pill: 2 }, recipe: 'marrow_pill' }), O('The disciples had found it first. All that was left was a scorch mark and some very rude graffiti about their master.', { insight: 1 })],
    sell: ['Sell the diary to Wudang', O('The Wudang Daoists paid well for it. One of them recognised the handwriting and laughed for a very long time.', { wealth: 25, rep: { orthodox: 2 } })],
    drop: ['Keep the diary for its recipes', O('The diary was full of recipes and complaints about disciples. You kept the recipes.', { recipe: 'qi_pill', insight: 1 })] },
  { key: 'cult_cache', if: { or: [{ sect: 'cult' }, { loc: 'tenthousand' }] }, art: 'demonic', title: 'A supply cache', text: 'A Cult courier’s body in a ravine still has a map sewn into his sleeve: a supply cache for the western passes, with pills for a hundred warriors.',
    follow: ['Find the cache', 0.6, O('Under a cairn of black stones: crates of pills, and a list of the warriors they were meant for. You took the pills. You burned the list, out of a strange courtesy.', { item: { marrow_pill: 1, qi_pill: 3 }, rep: { cult: -4 } }), O('The cache had a guard. He was asleep. Then he was not.', { health: -15 })],
    sell: ['Deliver it as the courier should have', O('The Cult’s quartermaster received it without expression and gave you a token with a red hand on it. People in the west treat you differently now.', { rep: { cult: 8 }, item: { qi_pill: 1 } })],
    drop: ['Burn the map', O('You burned it. Somewhere in the passes, a hundred warriors will go hungrier. You do not yet know whether that is good.', { rep: { orthodox: 2 } })] },
  { key: 'dead_merchant', if: { locType: ['city', 'estate'], region: ['jiangnan', 'central'] }, art: 'city', title: 'A dead man’s key', text: 'A merchant dies in the room next to yours at an inn, with no family anyone knows of. Among his things are a key and a sketch: a vault under a teahouse in Hangzhou, and the words "for my daughter, if I ever find her."',
    follow: ['Open the vault', 0.7, O('Silver, deeds, and a letter to a daughter he never found. You kept the silver. You still have the letter. You have not looked for her either.', { wealth: 250, sanity: -6, flag: 'fo.luck+=1' }), O('The teahouse owner had found the vault first, and denied everything with the merchant’s silver rings on his fingers.', { sanity: -2 })],
    sell: ['Look for the daughter', O('It took a year. She was a seamstress in Suzhou who had been told her father was dead. You gave her the key and the sketch. She offered you half, which you refused, and then a tenth, which you did not.', { wealth: 25, fame: 4, sanity: 8 })],
    drop: ['Hand it to the magistrate', O('The magistrate thanked you and confiscated everything for the state. The daughter, wherever she is, will never know.', { rep: { court: 3 }, sanity: -3 })] },
  { key: 'dragon_treasure', if: { locType: 'village', age: [7, 13] }, art: 'garden', title: 'The dragon’s treasure', text: 'The village children have drawn a map on a scrap of paper: the dragon’s treasure, buried under the old well, guarded by Granny Song’s goose. They need someone brave enough to get past the goose.',
    follow: ['Get past the goose', 0.5, O('The goose bit you twice. Under the well, in a rotten box, a string of copper coins and a rusty knife. The children declared you king. It was a good summer.', { wealth: 3, charm: 2, sanity: 4 }), O('The goose won. The children declared the goose king.', { health: -3, sanity: 2 })],
    sell: ['Trade the map for sweets', O('An older boy gave you three honey sweets for it. The goose bit him the same afternoon. Worth it.', { health: 1, charm: 1 })],
    drop: ['Draw a better map', O('You drew a better map, with more dragons. The other children were impressed, and for a week you were in charge of everything.', { insight: 1, charm: 1 })] },
  { key: 'star_chart', if: { loc: ['kunlun', 'jadegate', 'mounthua'] }, art: 'moon', title: 'A map of the sky', text: 'In a dead astrologer’s pack you find a map that turns out to be of the sky, not the earth: stars joined by lines, and in the margin, "where the qi falls."',
    follow: ['Climb to where it points on the next clear night', 0.6, O('Where the lines crossed, starlight fell like snow on a high ledge, and you breathed it all night. Your meridians hummed for a month.', { qi: 25, insight: 3, codex: { id: 'secret.fo_star_chart', cat: 'theory', title: 'Where the qi falls', text: 'A dead astrologer’s star chart shows where starlight gathers on high ledges on clear nights. Breathing it for a night is worth a season of meditation.' } }), O('Cloud. Every night for a month. You came down with a cold and no starlight.', { health: -5 })],
    sell: ['Sell it to the court astrologers', O('The court astrologers bought it for ten taels and argued about it for a year.', { wealth: 10 })],
    drop: ['Keep it for its beauty', O('You kept it. You still take it out on clear nights and look at the stars it names.', { sanity: 4 })] },
  { key: 'tattoo', if: { loc: 'kaifeng' }, danger: true, art: 'night', title: 'A map on a man’s back', text: 'In a Kaifeng alley a dead man lies face down with his shirt torn open. Tattooed across his back is a map. Someone has already started cutting it off him, and been interrupted.',
    follow: ['Copy it and follow it', 0.5, O('It led to a cellar under a burned temple: a smuggler’s cache of pills and silver. You did not sleep well, but you slept rich.', { wealth: 60, item: { marrow_pill: 1 }, sanity: -5 }), O('It led to the same cellar, and to the people who had gone to fetch a lamp.', { health: -18, sanity: -5 })],
    sell: ['Sell the copy to Madam Yeon', O('Madam Yeon paid well for it, and better for a description of the people who had run off. You did not ask why.', { wealth: 30, rep: { merchants: 3 } })],
    drop: ['Cover him and call the constables', O('You covered him with your coat and called the constables, who did nothing, competently.', { sanity: 2, wealth: -2 })] },
];
const tplMap = template('fo_map', MAPS, (r) => E('fo_map', 'fortune', {
  if: { age: r.age || [14, 70], chance: 0.3, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [P(r.follow[0], r.follow[1], r.follow[2], r.follow[3]), C(r.sell[0], r.sell[1]), C(r.drop[0], r.drop[1])],
}));

// ── Template: spirit beasts ──────────────────────────────────────
// Be kind, be bold (a roll), or be greedy. Only two of these beasts can be fought.
const BEASTS = [
  { key: 'white_cub', if: { loc: 'taihang' }, danger: true, art: 'forest', title: 'A white cub', text: 'In a bandit’s snare in the Taihang a white tiger cub is crying, one paw caught. From somewhere above the ridge, something much larger answers it.',
    kind: ['Free it and back away', O('You freed it and backed away very slowly. On the ridge above, a white tigress watched you go and did not follow. For the rest of your time in the Taihang, no beast ever troubled you.', { sanity: 4, flag: 'fo.luck+=1' })],
    bold: ['Free it and wait to meet the mother', 'sanity', 60, O('The tigress came down the slope and stood nose to nose with you, breathing. Then she picked up her cub and left you a gift at your feet: a dead bandit’s purse.', { wealth: 20, sanity: 6, fame: 2 }), O('The tigress did not stop to consider it. You got away with her claws in your back.', { injury: { name: 'tiger claws', seasons: 6, sev: 14 } })],
    greed: ['Take the cub to sell', O('A rich man in the city paid eighty taels for it. The tigress followed you halfway there, at night, every night.', { wealth: 80, infamy: 3, sanity: -8 })] },
  { key: 'sun_crow', if: { region: 'west', locType: 'frontier' }, art: 'desert', title: 'A three-legged crow', text: 'At noon in the desert a crow with three legs lands on your water skin, its black feathers glowing red at the edges like coals. It looks at you as if you owe it something.',
    kind: ['Give it your water', O('It drank your water and flew straight up into the sun. You walked the rest of the day thirsty and did not feel the heat once.', { health: -5, qi: 15, sanity: 2 })],
    bold: ['Ask it for a feather', 'charm', 40, O('It plucked one from its own breast and dropped it in your palm. The feather stayed warm as a coal for a year, and you slept beside it on cold nights.', { qi: 20, health: 10 }), O('It pecked your hand, hard, and left a burn shaped like a beak.', { health: -5 })],
    greed: ['Throw a stone at it', O('It caught the stone in one foot and dropped it back on your head from a great height.', { health: -4, charm: -1 })] },
  { key: 'jade_toad', if: { loc: ['emei', 'qingcheng'] }, art: 'garden', title: 'The jade toad', text: 'In a temple pond a toad as green and clear as jade sits on a lily pad. The monks say it eats poison. They also say it has been there for three hundred years and is thoroughly bored.',
    kind: ['Bring it a poisonous beetle', O('It ate the beetle with great dignity and then, to your surprise, crawled onto your hand. Whatever was in your blood, it drew out through your skin. You felt clean for the first time in years.', { cure: 'poison', health: 15 })],
    bold: ['Ask it, properly, for its pearl', 'insight', 50, O('The monks say a jade toad will give its pearl to someone who asks properly. Learning how to ask properly took a month. The pearl dissolved on your tongue like snow.', { qi: 25, health: 10, sanity: 4 }), O('You asked improperly. The toad turned its back on you, and the monks asked you to leave.', { rep: { orthodox: -2 } })],
    greed: ['Catch it and sell it', O('A physician in Chengdu paid fifty taels for it. Three days later the toad was back on its lily pad, and your purse had a hole in it.', { wealth: 10, sanity: -2 })] },
  { key: 'old_turtle', if: { loc: 'dongting' }, art: 'lake', title: 'The old turtle', text: 'A turtle as big as a sampan surfaces beside your boat on Lake Dongting, moss on its shell and a fishing hook rusted into its lip from some century past. It looks at you with eyes like old ink.',
    kind: ['Work the old hook free', O('It took an hour, leaning over the side. The turtle held perfectly still. When the hook came out it bowed its head and sank, and you had the strongest feeling that you had been forgiven a debt you did not know about.', { sanity: 8, flag: 'fo.luck=0' })],
    bold: ['Climb onto its back', 'body', 40, O('It carried you across the whole lake, through reeds and mist, and set you down on a beach you have never found again. You learned more about water in that day than in a lifetime.', { insight: 4, qi: 15 }), O('It dived. You did not.', { health: -10 })],
    greed: ['Harpoon it', O('The fishermen said a thousand-year turtle’s meat would add years to your life. It did. It also cost you something every time you looked at the lake.', { health: 20, flag: ['longevity+=2', 'fo.luck+=2'], sanity: -10, gaze: 1 })] },
  { key: 'snow_fox', if: { loc: ['kunlun', 'moyong'], season: [2, 3] }, art: 'snow', title: 'A fox in the blizzard', text: 'Caught in a blizzard, you are certain you are going to die when a fox as white as the snow trots out of nowhere and sits down in front of you, waiting.',
    kind: ['Follow it', O('It led you to a hollow under a rock, out of the wind, and curled against your chest until morning. When the blizzard lifted it was gone, and there were no tracks.', { health: 10, sanity: 5 })],
    bold: ['Follow it, and then follow where it goes', 'insight', 40, O('At dawn you followed its tracks to a cave where a dozen white foxes slept on a bed of herbs that never freeze. You took one sprig. It was a Snow Lotus, out of season.', { item: { snow_lotus: 1 }, sanity: 3 }), O('Its tracks vanished after ten paces, as if it had stepped into the air.', { insight: 1 })],
    greed: ['Kill it for its pelt', O('You killed it, wrapped yourself in its pelt, and lived through the night. In the morning there were fox tracks all around you, a hundred of them, in a circle.', { health: 5, wealth: 30, sanity: -10 })] },
  { key: 'ink_monkey', if: { loc: ['zhongnan', 'wudang'] }, art: 'library', title: 'The ink monkey', text: 'In a ruined hermitage a monkey no bigger than your hand sits beside an inkstone, grinding ink as it must have done for its master. The master’s bones lie in the next room. The monkey has been copying his last scripture, very badly, for years.',
    kind: ['Read the master’s original', O('The original was a commentary on breathing, half finished. The monkey watched you read it, then went back to grinding, as if relieved.', { insight: 3, qi: 10 })],
    bold: ['Teach the monkey to copy properly', 'insight', 45, O('It took a season. At the end the monkey copied the whole scripture perfectly, closed the book, and went to sleep on top of it. In teaching it, you had learned the scripture by heart.', { insight: 5, qi: 15, sanity: 3 }), O('The monkey bit you and went on copying badly. It has its own ideas.', { health: -2 })],
    greed: ['Take the monkey with you', O('It came reluctantly and spent a year grinding your ink and stealing your plums. Then one morning it was gone, back to its master, you suppose.', { charm: 2, sanity: 3 })] },
  { key: 'iron_eagle', if: { loc: ['kongtong', 'mounthua'] }, art: 'mountain', title: 'The stone-dropping eagle', text: 'An eagle with feathers like dark iron drops stones on anyone who climbs its cliff, apparently for fun. Everyone takes the long path. A one-armed hermit at the bottom says he learned to dodge by climbing it every day for ten years.',
    kind: ['Take the long path', O('You took the long path. The eagle dropped one stone near you anyway, to make a point.')],
    bold: ['Climb the cliff under the eagle', 'body', 45, O('Stones from a hundred feet. You learned to hear them coming, then to feel them. When you reached the top the eagle landed beside you, looking offended.', { body: 3, mastery: { step_basic: 15, hua_fragrance_step: 10, uno_ghost_step: 10, kun_cloud_step: 10, dian_cloud_step: 10 } }), O('A stone found the top of your head. You woke at the bottom with the hermit laughing at you.', { health: -15 })],
    greed: ['Climb it every day for a season', O('Every day for a season. You were hit nine times. By the end the eagle was dropping stones and you were catching them.', { body: 4, health: -10 })] },
  { key: 'honey_bear', if: { region: ['liaodong', 'hebei'], locType: ['wild', 'estate'] }, danger: true, art: 'forest', title: 'The honey bear', text: 'A black bear as big as a cart is guarding a hollow tree that hums. The smell of honey is so strong it makes you dizzy. Thousand-flower honey, the hunters call it, worth a year of meditation, if you live.',
    kind: ['Leave the bear its honey', O('You left the bear its honey. It watched you go, licking its paws, and you are fairly sure it was smiling.')],
    bold: ['Smoke it out', 'insight', 40, O('You built a smoky fire upwind and the bear wandered off, coughing and offended. The honey tasted like summer and made your qi glow for a week.', { qi: 25, health: 10 }), O('The smoke blew the wrong way, and the bear came the right way.', { health: -18, injury: { name: 'bear mauling', seasons: 6, sev: 10 } })],
    greed: ['Fight it for the honey', O('The bear stood up. It kept standing up for a while.', { combat: { foe: { name: 'a black bear', kind: 'beast', rel: 0 }, context: 'beast', lethal: 0.25, win: { text: 'The bear fled into the forest, bleeding and furious. The honey was everything the hunters had promised.', qi: 30, health: 15, fame: 2 }, lose: { text: 'You escaped with your life and none of the honey. The bear ate it in front of you.' } } })] },
  { key: 'golden_carp', if: { loc: ['wuchang', 'dongting'], season: 1 }, art: 'river', title: 'The golden carp', text: 'A golden carp throws itself again and again at a waterfall, trying to leap to the top. The old tale says a carp that leaps the Dragon Gate becomes a dragon. This one keeps falling back, bleeding a little each time.',
    kind: ['Lift it to the top of the falls', O('You climbed the falls with the carp in your hands and let it go at the top. It swam off looking, you thought, a little cheated. That night you dreamed of flying.', { sanity: 5, insight: 2 })],
    bold: ['Watch until it makes the leap', 'sanity', 50, O('You watched for three days. On the third evening it leapt and cleared the falls, and for a heartbeat in the red light it was not a fish at all. You came away understanding something about effort.', { insight: 4, qi: 20 }), O('You watched for a day and lost patience. The carp did not.', { sanity: -2 })],
    greed: ['Catch it for dinner', O('It was delicious. You felt bad about it, which did not stop you having seconds.', { health: 8, sanity: -3 })] },
  { key: 'white_stag', if: { loc: ['qingcheng', 'emei'] }, danger: true, art: 'forest', title: 'The one-horned stag', text: 'A white stag with a single horn walks out of the bamboo and stops in your path. The horn glows faintly. Hunters say it is worth a hundred taels; old women say it is worth your soul.',
    kind: ['Bow to it', O('You bowed. It bowed back, unmistakably, and walked away through the bamboo. For days you felt as if something were walking beside you.', { sanity: 6, flag: 'fo.luck+=1' })],
    bold: ['Ask it for a blessing', 'charm', 50, O('It came close and touched its horn to your forehead. Warmth went all the way down to your dantian and settled there.', { qi: 20, health: 15 }), O('It snorted and left. Some blessings are for other people.')],
    greed: ['Hunt it', O('It lowered its horn.', { combat: { foe: { name: 'the white stag', kind: 'beast', rel: 0.5 }, context: 'beast', lethal: 0.15, win: { text: 'The stag fell. The horn sold for a hundred taels. You were not entirely yourself for a long while after.', wealth: 100, sanity: -12, infamy: 2, gaze: 1 }, lose: { text: 'It ran you through the shoulder and was gone. You think it chose not to kill you.', injury: { name: 'horn wound', seasons: 4, sev: 10 } } } })] },
];
const tplBeast = template('fo_beast', BEASTS, (r) => E('fo_beast', 'fortune', {
  if: { age: [12, 80], chance: 0.3, ...SAFE(r), ...r.if }, art: r.art, title: r.title, text: r.text, ...(r.danger ? { danger: true } : {}),
  choices: [C(r.kind[0], r.kind[1]), R(r.bold[0], r.bold[1], r.bold[2], r.bold[3], r.bold[4]), C(r.greed[0], r.greed[1])],
}));

// ── Template: cursed things ──────────────────────────────────────
// Use it and pay, understand it (a roll), or get rid of it.
const CURSES = [
  { key: 'blood_jade', if: { locType: 'city' }, art: 'market', title: 'The blood-jade ring', text: 'A jade dealer sells you nothing, but gives you a ring for free: red jade with a dark thread inside it that moves when you are not looking at it directly. "Take it," he says. "Please."',
    use: ['Wear it', O('It drank from you a little every night, and gave back more than it took, in qi. You feel strong and slightly thin, like paper held to a lamp.', { qiFill: 40, health: -12, sanity: -6, gaze: 1 })],
    test: ['Study the thread inside', 'insight', 45, O('The thread was a sealed spirit, an old master’s blood art folded into stone. You learned what you could and broke the ring before it learned you.', { insight: 4, qi: 10 }), O('The thread began to move when you looked at it directly. You threw the ring down a well and have avoided wells since.', { sanity: -8 })],
    rid: ['Give it back', O('He would not take it. You left it on his counter; when you got home it was in your pocket. You left it on a temple altar. That worked.', { sanity: -2 })] },
  { key: 'bone_flute', if: { region: 'west' }, art: 'desert', title: 'A bone flute', text: 'In the sand beside a dead caravan you find a flute carved from a thigh bone, its holes drilled in a pattern no musician would use. When the wind blows through it, the camels kneel.',
    use: ['Play it', O('You played one note. Everyone within earshot fell asleep where they stood, including you, eventually. When you woke, your purse was full of other people’s silver and you had no idea how.', { wealth: 30, sanity: -8, infamy: 2 })],
    test: ['Learn the fingering slowly', 'sanity', 55, O('You learned to play it softly, so that only one person sleeps. It is a terrible thing to know. You have used it twice, both times to stop a fight.', { insight: 3, charm: 2, sanity: -3 }), O('You played the wrong note. The camels did not kneel; they bolted, and so did your sense of direction.', { sanity: -10, health: -5 })],
    rid: ['Bury it with the caravan', O('You buried it with them. The wind stopped making that sound.', { sanity: 4 })] },
  { key: 'face_mirror', if: { ...LATER, locType: ['city', 'estate'] }, art: 'night', title: 'The mirror of faces', text: 'In an antique shop a bronze mirror shows you your face, then a different face, then another: a man, a girl, an old woman, a child. You know every one of them. They are all you.',
    use: ['Buy it and keep looking', O('You bought it and looked every night. You remembered things you had lost: a recipe, a road, a name. You also remembered how each of those faces died.', { wealth: -15, insight: 4, sanity: -12, burden: 1 })],
    test: ['Ask the shopkeeper where it came from', 'charm', 35, O('"An old woman sold it," he said. "She said it had shown her too many lives, and she only wanted one." You understood her completely.', { insight: 2, sanity: 2 }), O('"It shows whatever you want to see," he said, bored. It did not.', { sanity: -3 })],
    rid: ['Turn it face down', O('You turned it face down and walked out. The shopkeeper did not look surprised. Most people did the same.', { sanity: 1 })] },
  { key: 'hungry_sword', if: { region: ['guanzhong', 'central'], locType: ['village', 'wild', 'sect'] }, art: 'duel', title: 'A sword that will not be sheathed', text: 'In a ditch lies a fine sword with no scabbard, its edge bright and its hilt wrapped in a dead man’s ribbon. When you pick it up, your hand does not want to let go.',
    use: ['Keep it', O('It is the best sword you have ever held. It also hums, faintly, whenever you are angry, and you are angry more often now.', { item: { fine_sword: 1 }, sanity: -10, infamy: 1 })],
    test: ['Make it let go of you', 'sanity', 50, O('You sat with the sword across your knees until your hand opened by itself. After that it was just a sword: an excellent one, and yours.', { item: { fine_sword: 1 }, sanity: -2 }), O('Your hand would not open for a week. Your temper did not come back for longer.', { item: { fine_sword: 1 }, sanity: -15 })],
    rid: ['Drop it back in the ditch', O('It took your other hand to pry your fingers open. You walked away and did not look back.', { sanity: 2 })] },
  { key: 'jade_seal', if: { loc: ['capital', 'changan', 'kaifeng'] }, art: 'palace', title: 'A seal of office', text: 'A jade seal falls out of a fleeing official’s sleeve into the gutter at your feet. Stamped on paper, it would turn any order into the Emperor’s order. The official does not come back for it.',
    use: ['Keep it and use it carefully', O('You used it three times: a pass, a pardon, a purse of tax silver. Then the Depot started asking who had found it, and you dropped it in a canal.', { wealth: 100, rep: { court: -12 }, infamy: 4, flag: 'fo.whispers' })],
    test: ['Find the official and return it', 'insight', 40, O('He was hiding in a temple, waiting to be executed. When you handed it back he wept and gave you a ring and a promise. He kept the promise, in his way.', { rep: { court: 6 }, item: { jade_pendant: 1 }, fame: 2 }), O('The Depot found him before you did. They also found you, holding his seal, and asked questions all night.', { rep: { court: -6 }, health: -8 })],
    rid: ['Drop it in the canal', O('You dropped it in the canal. Somewhere a man will be executed for losing it. That is not your fault. You remind yourself of that.', { sanity: -4 })] },
  { key: 'water_bride', if: { loc: ['dongting', 'hangzhou', 'wuchang'] }, art: 'lake', title: 'A drowned woman’s pearl', text: 'A pearl the size of a quail’s egg washes up on the shore, wrapped in long black hair. The fishermen will not touch it. "Water bride," they say. "She will want it back."',
    use: ['Wear it', O('People find you lovely now, in a way that makes them uneasy. At night you dream of being underwater, and wake with wet hair.', { charm: 5, sanity: -8 })],
    test: ['Find out who she was', 'insight', 40, O('A girl who drowned herself rather than marry an old magistrate, twenty years ago. You gave the pearl to her mother, who still lives by the water. The dreams stopped.', { sanity: 6, fame: 2 }), O('No one would say. The dreams got worse.', { sanity: -6 })],
    rid: ['Throw it back', O('You threw it back. A pale hand, perhaps, caught it. Perhaps it was a fish.', { sanity: 2 })] },
  { key: 'straw_doll', if: { age: [12, 80], locType: ['village', 'city', 'estate'] }, art: 'night', title: 'A doll with your name', text: 'Under the floor of your room you find a straw doll with nine needles in it. Folded inside is a slip of paper with your name and the hour of your birth. Someone has gone to a great deal of trouble.',
    use: ['Pull the needles and burn it', O('You pulled the needles one by one and burned it. The headache you had been carrying for a month lifted at once.', { sanity: 6, health: 5 })],
    test: ['Find out who made it', 'insight', 40, O('The handwriting, the straw, a neighbour who had once been rude to you and then very polite. You returned the doll to them with a smile. They moved away within the month.', { insight: 2, sanity: 3, fame: 1 }), O('You never found out. That was the worst part.', { sanity: -8 })],
    rid: ['Leave it where it is', O('You left it. Your headaches got worse every month, until you burned it after all.', { health: -10, sanity: -5 })] },
  { key: 'ghost_lantern', if: { loc: ['luoyang', 'kaifeng', 'chengdu'] }, art: 'night', title: 'A paper lantern', text: 'A paper lantern hangs outside an abandoned house, lit every night though no one lives there. When you hold it, you can see the dead walking in the street, going about their old business. They see you, too.',
    use: ['Keep it and walk with the dead', O('You walked with them every night for a season. An old swordsman among them taught you a parry and asked you to tell his son he was sorry. You did. The son slammed the door.', { insight: 3, sanity: -8, mastery: { sword_basic: 10, hua_plum_sword: 10, wu_taiji_sword: 10, emei_sword: 10, qing_pine_sword: 10 } })],
    test: ['Ask the dead what they want', 'sanity', 50, O('They wanted to be told the year, and to know whether anyone remembered them. You told them, and lied about the second part. They went quietly, one by one, and the lantern went out.', { sanity: 4, insight: 2, fame: 1 }), O('They all wanted something, all at once. You dropped the lantern and ran.', { sanity: -12 })],
    rid: ['Blow it out', O('You blew it out. For a moment the street was full of people looking at you, disappointed. Then it was empty.', { sanity: -2, insight: 1 })] },
  { key: 'gambler_coin', if: { locType: 'city', stat: { wealth: '>=5' } }, art: 'market', title: 'A coin that lands heads', text: 'A gambler dying in a gutter presses a coin into your palm. "Always heads," he says. "Always. Don’t use it more than you must." Then, quite cheerfully, he dies.',
    use: ['Take it to the dice tables', O('Heads, every time. You won enough to buy a house before the luck curdled: your landlord died, your horse went lame, and the house burned.', { wealth: 80, flag: 'fo.luck+=3' })],
    test: ['Use it once, for something that matters', 'insight', 35, O('You used it once, to decide whether to trust someone. Heads. You trusted them. You were right. You buried the coin with the gambler.', { sanity: 5, charm: 1, flag: 'fo.luck+=1' }), O('You used it once. Then twice. It is very hard to use a lucky coin once.', { wealth: 30, flag: 'fo.luck+=2' })],
    rid: ['Bury it with him', O('You buried it with him. He would have laughed. You think he did, a little.', { sanity: 3 })] },
  { key: 'red_armband', if: { region: ['west', 'guanzhong'], notSect: 'cult' }, art: 'battlefield', title: 'A commander’s armband', text: 'On a dead Cult commander you find a red silk armband embroidered with a black hand. Cult soldiers salute whoever wears it, the stories say, and Orthodox soldiers kill them on sight.',
    use: ['Wear it in the west', O('Cult patrols saluted you and let you pass. You learned a great deal about the western passes. You also learned how easy it is to enjoy being saluted.', { rep: { cult: 8, orthodox: -8 }, insight: 2, codex: { id: 'secret.fo_red_armband', cat: 'secrets', title: 'The red armband', text: 'A Cult commander’s armband, embroidered with a black hand, makes Cult patrols salute and step aside. Orthodox patrols do the opposite.' } })],
    test: ['Learn his name before you burn it', 'insight', 35, O('His name was in the lining, with a letter to his wife in the Ten Thousand Mountains. You sent the letter west with a merchant. You will never know if it arrived.', { sanity: 4, rep: { cult: 2 } }), O('His name was smudged past reading. You burned it anyway.', { sanity: 1 })],
    rid: ['Bury him with it, as a soldier', O('You buried him with it. A Cult scout watched from a ridge and, when you had gone, came down and put a stone on the grave.', { sanity: 3, rep: { cult: 2 } })] },
];
const tplCurse = template('fo_curse', CURSES, (r) => E('fo_curse', 'fortune', {
  if: { age: [14, 80], chance: 0.3, ...r.if }, art: r.art, title: r.title, text: r.text,
  choices: [C(r.use[0], r.use[1]), R(r.test[0], r.test[1], r.test[2], r.test[3], r.test[4]), C(r.rid[0], r.rid[1])],
}));

// ── Template: fated meetings ─────────────────────────────────────
// A chance first meeting with someone who will matter, with a small fortune folded into it.
const FATED = [
  { key: 'sohee', npc: 'namgung_sohee', loc: 'namgung', age: [12, 30], art: 'garden', title: 'The girl in the bamboo grove', text: 'Behind the Namgung Estate, in a bamboo grove where nobody is supposed to go, a girl your age is practising a sword form the Namgung do not teach their daughters. She sees you, and her sword stops a finger from your throat. "Tell anyone," says {@namgung_sohee}, "and I will deny it beautifully."',
    a: ['Promise to tell no one', 'You promised. She practised in front of you after that, every evening, as if you were part of the grove. Watching her, you learned more about the sword than in a year of drills.', { rel: { '@namgung_sohee': { aff: 15 } }, insight: 2 }],
    b: ['Spar with her', 'body', 30, 'You held your own for twenty exchanges. She laughed for the first time, delighted. "Again," she said. "Tomorrow. Nobody else will fight me properly."', { rel: { '@namgung_sohee': { aff: 10, res: 20 } }, body: 1 }, 'She put you in the pond. Twice. Then she helped you out and apologised, and did not mean it.', { rel: { '@namgung_sohee': { aff: 8 } }, health: -3 }],
    c: ['Back away and say nothing', O('You backed away. She went on practising, alone.')] },
  { key: 'dangmin', npc: 'dang_min', region: 'shu', age: [12, 30], art: 'forest', title: 'An antidote, tested', text: 'A young man in Dang colours lies in the forest, lips blue, a bottle in his hand and a notebook open beside him. The last line reads: "Antidote seven: testing on self, as no one else will volunteer." He is {@dang_min}, and he is dying of his own good intentions.',
    a: ['Make him vomit and carry him to water', 'You did the undignified, sensible thing. He lived, mortified, and insisted on paying you with a recipe. "It works," he said. "I tested it."', { rel: { '@dang_min': { aff: 20 } }, recipe: 'healing_salve' }],
    b: ['Read his notes and finish the antidote', 'insight', 40, 'You found his mistake: one ingredient too many, out of caution. You fixed it and poured it down his throat. He woke, read your correction, said, "Oh. Oh, that is clever," and has written to you ever since.', { rel: { '@dang_min': { aff: 20, res: 20 } }, insight: 3, recipe: 'heart_calming' }, 'You made it worse. He survived in spite of you, and laughed about it later, weakly.', { rel: { '@dang_min': { aff: 10 } } }],
    c: ['Fetch the Dang', O('The Dang came and took him away without a word to you. A month later a box of candied plums arrived with no note.', { rep: { families: 2 } })] },
  { key: 'ilgak', npc: 'ilgak', loc: 'songshan', age: [10, 25], art: 'temple', title: 'The bun thief', text: 'Behind the Shaolin kitchens a round-faced young monk is eating steamed buns as fast as he can, hiding more in his sleeves between bites. He freezes when he sees you. "They were going to be thrown away," says {@ilgak}, through a bun. "Probably."',
    a: ['Help him eat the evidence', 'You ate four buns each, sitting on the woodpile. He decided on the spot that you were his best friend, and from then on slipped you pills from the infirmary that he was not supposed to have.', { rel: { '@ilgak': { aff: 20 } }, item: { qi_pill: 1 } }],
    b: ['Race him down the thousand steps', 'body', 30, 'You raced him down a thousand steps and won, and he was sick, and you laughed so hard you fell over. The cook found you both and made you carry water for a month, which built more strength than any lesson.', { rel: { '@ilgak': { aff: 15 } }, body: 2 }, 'He beat you by two hundred steps, still holding a bun.', { rel: { '@ilgak': { aff: 10 } } }],
    c: ['Tell the cook', O('The cook was furious. Il-gak swept the courtyard for a month, and forgave you after the first week, which made it worse.', { rep: { orthodox: 1 } })] },
  { key: 'hyeryeong', npc: 'hyeryeong', loc: 'emei', age: [12, 30], art: 'river', title: 'A sword in the river', text: 'A fierce young Emei swordswoman stands waist-deep in a freezing river, glaring at the water. "My sword," says {@hyeryeong}. "A monkey. Don’t laugh."',
    a: ['Don’t laugh, and help her look', 'You searched until your feet were numb. She found it, swore at the monkey for a full minute, and then cooked you the best meal you have ever eaten, to apologise for the swearing.', { rel: { '@hyeryeong': { aff: 20 } }, health: 5 }],
    b: ['Dive for it', 'body', 35, 'You came up with the sword on the third dive. She looked at it, then at you, and said, "I would have found it," and then, much more quietly, "Thank you."', { rel: { '@hyeryeong': { aff: 15, res: 15 } } }, 'You came up with a boot. She laughed until she had to sit down in the river.', { rel: { '@hyeryeong': { aff: 12 } }, health: -5 }],
    c: ['Laugh', O('You laughed. She came out of the river and hit you. You deserved it. Somehow, after that, you were friends.', { meet: '@hyeryeong', rel: { '@hyeryeong': { aff: 5, res: -5 } }, health: -3 })] },
  { key: 'dongsu', npc: 'dongsu', loc: 'luoyang', age: [8, 25], art: 'city', title: 'A pickpocket', text: 'A grubby boy bumps into you in the Luoyang market and is three stalls away before you notice your purse is gone. He is laughing. He is very fast.',
    a: ['Let him keep it, and follow him', 'You followed him under the bridges to where a dozen beggar children were sharing your silver for dinner. He saw you and grinned. "{@dongsu}," he said. "You can have some. It is your money."', { rel: { '@dongsu': { aff: 20 } }, wealth: -5, sanity: 3 }],
    b: ['Chase him down', 'body', 30, 'You caught him by the collar at the bridge. He handed back the purse without argument and then, as a professional courtesy, pointed out three other people in the market who had been watching you. Dong-su knows everything that happens in Luoyang.', { rel: { '@dongsu': { aff: 10, res: 15 } }, insight: 1 }, 'He lost you in the alleys in a breath. Later a different beggar returned your empty purse, with a note in a child’s writing: "Faster next time. D."', { rel: { '@dongsu': { aff: 8 } }, wealth: -5 }],
    c: ['Shout for the constables', O('The constables shrugged. Your purse was gone. Somewhere, a boy was laughing.', { wealth: -5 })] },
  { key: 'jegalha', npc: 'jegal_ha', loc: 'jegal', age: [12, 35], art: 'garden', title: 'Baduk against herself', text: 'In the Jegal Estate’s garden a young woman is playing baduk against herself, and losing, on purpose, beautifully. "Sit," says {@jegal_ha}, without looking up. "You can be white. White loses. It is tradition."',
    a: ['Lose gracefully', 'You lost, as tradition demanded. She talked the whole time about formations and families, and which of the Five Families would fall first. She was right about most of it, later.', { rel: { '@jegal_ha': { aff: 15 } }, insight: 2 }],
    b: ['Try to win', 'insight', 50, 'You won. She stared at the board for a long time, then swept the stones into their bowls and said, "Again," with a look you have not seen on anyone before or since.', { rel: { '@jegal_ha': { res: 25, aff: 10 } }, insight: 4 }, 'You lost, thoroughly, and not on purpose. "Better," she said, kindly.', { rel: { '@jegal_ha': { aff: 10 } }, insight: 2 }],
    c: ['Excuse yourself', O('You excused yourself. She did not look up. You had the feeling she had already played out the version where you stayed.')] },
  { key: 'paenggu', npc: 'paeng_gu', loc: 'paeng', age: [14, 35], art: 'feast', title: 'A drinking contest', text: 'In the Paeng fortress’s mess hall a broad young man with a laugh like a landslide is challenging all comers to a drinking contest. Nobody is accepting. "Cowards!" roars {@paeng_gu} at the room, cheerfully, and then he sees you.',
    a: ['Accept, but drink tea', 'You matched him cup for cup with tea in your jar. He noticed at the fortieth cup and laughed so hard he fell off the bench. "Cheat! Brother!" He has called you brother ever since.', { rel: { '@paeng_gu': { aff: 20 } }, charm: 1 }],
    b: ['Accept, and drink', 'health', 60, 'You drank until the room spun the other way. He fell first, by one cup, and woke declaring you the greatest drinker in Hebei.', { rel: { '@paeng_gu': { aff: 20, res: 15 } }, fame: 2, health: -5 }, 'You fell first. He carried you to bed over one shoulder, singing.', { rel: { '@paeng_gu': { aff: 15 } }, health: -8 }],
    c: ['Decline', O('He called you a coward too, cheerfully, and bought you a drink anyway.', { meet: '@paeng_gu', rel: { '@paeng_gu': { aff: 5 } } })] },
  { key: 'mokcheol', npc: 'mokcheol', loc: 'tenthousand', age: [6, 18], art: 'snow', title: 'Half a rice cake', text: 'In a hungry winter in the Ten Thousand Mountains a quiet boy sits down beside you in the snow, breaks his rice cake in half, and hands you the bigger piece. He does not say anything. Later you learn his name is {@mokcheol}.',
    a: ['Eat it and thank him', 'You ate it and thanked him. He nodded. From then on, through every hungry winter, he sat beside you, and whatever he had, you had half of.', { rel: { '@mokcheol': { aff: 25 } }, health: 3 }],
    b: ['Give him back the bigger half', 'charm', 30, 'He looked at you for a long time, and almost smiled. You shared everything after that, always swapping halves. It became a game, and then a kind of oath.', { rel: { '@mokcheol': { aff: 20, res: 15 } }, sanity: 4 }, 'He would not take it back. He would not speak to you for a week, either, as if you had insulted him.', { rel: { '@mokcheol': { aff: 5 } } }],
    c: ['Ask him why', O('He shrugged. "You looked hungry." That was all he ever said about it.', { meet: '@mokcheol', rel: { '@mokcheol': { aff: 15 } } })] },
  { key: 'yeonwoo', npc: 'yeonwoo', loc: 'wudang', age: [14, 35], art: 'duel', title: 'An apology before the duel', text: 'A gentle-faced Wudang disciple bows to you on the mountain path. "I am sorry," says {@yeonwoo}, "but my master told me to spar with the first stranger I met today, and you are the first stranger." He looks genuinely unhappy about it.',
    a: ['Accept the spar', 'He bowed again, apologetically.', { combat: { foe: '@yeonwoo', context: 'spar', lethal: 0, win: { text: 'You won. He thanked you sincerely and asked to spar again tomorrow, and the day after.', rel: { '@yeonwoo': { res: 20, aff: 10 } }, fame: 1 }, lose: { text: 'He won, apologised for winning, and then showed you exactly what you had done wrong.', rel: { '@yeonwoo': { aff: 15 } }, insight: 2 } } }],
    b: ['Talk him out of it', 'charm', 30, 'You pointed out that his master had not said what kind of spar. You sparred at baduk instead. He was terrible at it, and very happy.', { rel: { '@yeonwoo': { aff: 20 } }, charm: 1 }, 'He apologised, and insisted. It was a very polite beating.', { rel: { '@yeonwoo': { aff: 10 } }, health: -5 }],
    c: ['Refuse politely', O('He bowed, relieved, and walked on, and then came back and gave you a peach for your trouble.', { meet: '@yeonwoo', health: 2 })] },
  { key: 'moyongyeon', npc: 'moyong_yeon', loc: 'moyong', age: [12, 35], art: 'snow', title: 'Being studied', text: 'On the cold beach below the Moyong seat a young woman is watching you train and writing in a little book. When you look up she does not pretend she was not. "Your left foot is late," says {@moyong_yeon}. "I am writing down why."',
    a: ['Ask to read the book', 'She let you read it. It was about you, and it was right about everything, including things you had told no one. She seemed pleased that you were not angry.', { rel: { '@moyong_yeon': { aff: 15, res: 10 } }, insight: 3 }],
    b: ['Study her back', 'insight', 45, 'You told her three things about her own stance that she had not noticed. She wrote them down very fast, then looked at you as if for the first time.', { rel: { '@moyong_yeon': { res: 25, aff: 10 } }, insight: 2 }, 'You told her something about her stance. She corrected you, politely, with diagrams.', { rel: { '@moyong_yeon': { aff: 8 } } }],
    c: ['Fix your left foot and walk away', O('You fixed it. She wrote that down too.', { meet: '@moyong_yeon', body: 1 })] },
];
const tplFated = template('fo_fated', FATED, (r) => {
  const meet = `@${r.npc}`;
  return E('fo_fated', 'fortune', {
    if: { notMet: r.npc, alive: r.npc, age: r.age, chance: 0.4, ...(r.loc ? { loc: r.loc } : { region: r.region }) }, art: r.art, title: r.title, text: r.text,
    choices: [
      C(r.a[0], O(r.a[1], { meet, ...r.a[2] })),
      R(r.b[0], r.b[1], r.b[2], O(r.b[3], { meet, ...r.b[4] }), O(r.b[5], { meet, ...r.b[6] })),
      C(r.c[0], r.c[1]),
    ],
  });
});

// ── Template: the regressor’s advantage ──────────────────────────
// History you lived through in another life tells you where something is, or what will be worth what.
// Spending that knowledge draws Heaven’s eye.
const RECALL = [
  { key: 'grain_fleet', tl: 'grain_fleet', if: { happened: 'grain_fleet', loc: ['dongting', 'wuchang'], year: [13, 40] }, art: 'lake', title: 'The paymaster’s chests', text: 'You remember, from another life, a diver bragging in a Wuchang tavern: the imperial grain fleet did not only carry grain. The paymaster’s chests went down with the flagship, off the reed island the Water Fortress calls the Sow.',
    go: ['Dive off the Sow', 'body', 35, O('Nine fathoms, a broken mast, and three iron chests of imperial silver. You brought up one. It was enough. It was also, technically, the Emperor’s.', { wealth: 150, rep: { court: -4 }, gaze: 1, flag: 'fo.whispers' }), O('The water off the Sow was colder and darker than any diver’s boast. You came up with nothing and a ringing in your ears that took a month to fade.', { health: -12 })],
    alt: ['Tell the court where it lies', O('The Ministry of Revenue sent divers and paid you a finder’s fee, minus taxes, minus a fee for the paperwork.', { wealth: 25, rep: { court: 8 }, gaze: 1 })] },
  { key: 'coptis', tl: 'shu_plague', if: { year: [15, 18], region: 'shu' }, art: 'market', title: 'The price of coptis', text: 'You remember the plague summer of year 19 in Chengdu, and that coptis root, which cures nothing but is believed to, sold for its weight in silver. In this life the herb-sellers still sell it by the basket.',
    go: ['Buy coptis futures from the herb guild', 'insight', 30, O('You signed for a warehouse of coptis at spring prices. The guild clerks thought you a fool. You have made money on a plague that has not happened yet, and you cannot stop thinking about that.', { wealth: 70, sanity: -6, gaze: 1 }), O('The guild clerks were sharper than you. You signed for a warehouse of something that was mostly sawdust.', { wealth: -20 })],
    alt: ['Stock what the physicians will wish they had', O('You could not buy the cure, but you bought what the physicians of your past life had begged for: clean water jars, vinegar, willow bark. They thought you mad. In year 19, they will be glad.', { wealth: -15, fame: 3, sanity: 4, gaze: 1 })] },
  { key: 'kongtong_well', tl: 'kongtong_falls', if: { happened: 'kongtong_falls', loc: 'kongtong', noManual: 'kong_seven_injuries' }, art: 'fire', title: 'The well under Kongtong', text: 'You remember a Kongtong survivor in another life, weeping drunk in an inn: the Cult never found the vault under the dry well behind the scripture hall. He never went back. He could not bear to.',
    go: ['Climb down the dry well', 'body', 30, O('The vault was there, untouched, and in it the Seven Injuries Fist. As you read it your own ribs ached in sympathy. It is that kind of art.', { manual: 'kong_seven_injuries', health: -8, gaze: 1 }), O('The well was deeper than he had said. You climbed back out without the vault, and with a twisted ankle.', { injury: { name: 'twisted ankle', seasons: 2, sev: 5 } })],
    alt: ['Find the survivors and tell them', O('The Kongtong survivors went down the well themselves. They gave you nothing but a long bow, and that was more than enough.', { rep: { orthodox: 10 }, merit: 10, sanity: 4, gaze: 1 })] },
  { key: 'namgung_ashes', tl: 'namgung_burns', if: { happened: 'namgung_burns', loc: 'namgung', noManual: 'nam_heaven_thunder' }, art: 'fire', title: 'In the Namgung ashes', text: 'You remember where the Namgung kept their deepest art, because in another life you watched So-hee carry it into the fire to keep it from the Cult. In this life the estate is ash again, and the iron box is still under the ancestral hall.',
    go: ['Dig out the box and keep it', 'insight', 25, O('The Heavenly Thunder Sword Intent, slightly scorched. You read it by the light of the Namgung’s own ruins. It felt like robbing a grave, because it was.', { manual: 'nam_heaven_thunder', sanity: -6, rep: { families: -6 }, gaze: 1 }), O('The ashes had shifted. You dug for a week and found only the ancestral tablets, which you gave back.', { rep: { families: 3 } })],
    alt: ['Dig it out and give it to the surviving Namgung', O('The surviving Namgung received it on their knees. They did not ask how you knew where to dig. They will remember that you did.', { rep: { families: 12 }, fame: 4, gaze: 1 })] },
  { key: 'tathagata_pages', tl: 'siege_song', if: { happened: 'siege_song', loc: 'songshan', year: [36, 50] }, art: 'temple', title: 'The scattered pages', text: 'You remember that after the siege, in another life, a cook found pages of the Tathagata Palm blown into the bamboo behind the Scripture Pavilion, and used them to light fires all winter.',
    go: ['Search the bamboo before the cook does', 'insight', 40, O('Eleven pages, rain-stained but legible. Not enough to learn the Palm. More than enough to understand why it is feared.', { insight: 5, qi: 20, mastery: { shao_tathagata: 20, shao_arhat: 15 }, gaze: 1 }), O('You found two pages, both of them the preface.', { insight: 1 })],
    alt: ['Gather them for the monks', O('The monks wept to see them. They are short of everything now, even tears, and they spent some on you.', { rep: { orthodox: 10 }, merit: 8, gaze: 1 })] },
  { key: 'blood_demon_robe', tl: 'yellow_ford', if: { happened: 'yellow_ford', region: 'central', year: [41, 55], noManual: 'cult_blood_art' }, art: 'battlefield', title: 'Where the Blood Demon fell', text: 'You remember where the Blood Demon’s body was hidden after the Ford by his own guards: a mud bank three li downstream, under a broken war cart. In another life someone else found the manual sewn into his robe.',
    go: ['Find him first, and read it', 'sanity', 45, O('Under the cart lay what was left of Ma Hyeol-cheon. The Blood Demon Art was sewn into his robe, as you remembered. Reading it was like drinking from a wound.', { manual: 'cult_blood_art', sanity: -10, infamy: 4, gaze: 1 }), O('You found him, and the manual, and could not make yourself read past the first page. You burned it there.', { sanity: -4, insight: 2 })],
    alt: ['Find him and burn everything', O('You burned the robe, the manual and the man. Somewhere, in another life, someone did not become a monster because of it.', { sanity: 6, fame: 2, gaze: 1 })] },
  { key: 'kennel', tl: 'beggars_outlawed', if: { happened: 'beggars_outlawed', loc: 'luoyang', noManual: 'beg_dragon_palms' }, art: 'fire', title: 'The kennel under the bridge', text: 'You remember a Beggar elder in another life, laughing about it as he died: when the Depot burned the halls, the Eighteen Dragon-Subduing Palms were hidden in a dog kennel under the third bridge, because no one searches a kennel.',
    go: ['Search the kennels', 'insight', 40, O('Under the straw, under a very offended dog, an oilskin packet: the Eighteen Palms. Owning it now makes you an outlaw twice over.', { manual: 'beg_dragon_palms', rep: { court: -10 }, gaze: 2, flag: 'fo.luck+=1' }), O('There were seven kennels under the third bridge. The dogs in all of them bit you.', { health: -8 })],
    alt: ['Get word to the surviving Beggars', O('A one-eyed beggar collected it from the kennel the next night. The Beggars’ Sect, outlawed and scattered, now owes you more than it can say.', { rep: { orthodox: 8 }, fame: 3, gaze: 1 })] },
  { key: 'directors_room', tl: 'depot_coup', if: { happened: 'depot_coup', loc: 'capital', noManual: 'court_withered_flower' }, art: 'palace', title: 'The Director’s private room', text: 'You remember that after Wi Chung-hyeon died on the palace steps, his private room behind the Eastern Depot’s archive was never found. In another life you learned that its door is behind the shelf of tax records nobody reads.',
    go: ['Find the door', 'insight', 45, O('Silver, letters, and on the desk the Withered Flower Canon in the Director’s own hand. You left the letters. You took everything else.', { manual: 'court_withered_flower', wealth: 80, rep: { court: -10 }, gaze: 1, flag: 'fo.whispers' }), O('A Depot clerk working late saw you at the shelf. You talked your way out, barely.', { rep: { court: -4 } })],
    alt: ['Tell Commander Han Gyeong', O('Han Gyeong, the only honest man in the capital, opened the room himself and burned what was in it. He did not thank you. He nodded, which from him is more.', { rep: { court: 10 }, meet: '@guard_commander', rel: { '@guard_commander': { res: 20 } }, gaze: 1 })] },
  { key: 'drought_spring', tl: 'hebei_drought', if: { year: [43, 46], region: 'hebei' }, art: 'river', title: 'The spring that never dried', text: 'You remember the drought of year 46, and the one spring in Hebei that did not fail, on a hill farm that sells for almost nothing the year before.',
    go: ['Buy the hill farm', 'charm', 30, O('You bought it for a song from a farmer who thought you a fool. When the drought came your spring was the only water for ten li. You gave most of it away.', { wealth: -30, fame: 6, sanity: 6, gaze: 1 }), O('The farmer had heard rumours too. He doubled the price, and you paid it.', { wealth: -60, fame: 4, gaze: 1 })],
    alt: ['Sell the secret to a grain lord', O('A grain lord paid you handsomely and fenced the spring. In the drought he sold water by the cup. You knew he would.', { wealth: 120, infamy: 5, sanity: -8 })] },
  { key: 'north_face', tl: 'snow_lotus_16', if: { loc: 'kunlun', season: 1, or: [{ year: [16, 16] }, { year: [26, 26] }, { year: [36, 36] }] }, art: 'snow', title: 'The north face', text: 'You remember: in the summer of the lotus years, the Snow Lotus blooms on the north face above the Kunlun Sect, where the Kunlun disciples never look, because the south face is easier.',
    go: ['Climb the north face', 'body', 35, O('Three days on the ice. At the top, white petals opening in a crack of blue ice, exactly where you remembered.', { item: { snow_lotus: 1 }, gaze: 1 }), O('The north face is hard for a reason. You came down with frostbitten fingers and a new respect for the south face.', { injury: { name: 'frostbite', seasons: 4, sev: 10 } })],
    alt: ['Tell the Kunlun disciples where to look', O('Kunlun’s disciples climbed the north face and came back with the lotus and a new respect for you, which on Kunlun is rarer than lotuses.', { rep: { orthodox: 8 }, merit: 6, gaze: 1 })] },
];
const tplRecall = template('fo_recall', RECALL, (r) => E('fo_recall', 'fortune', {
  if: { ...LATER, mem: `timeline.${r.tl}`, age: [14, 90], ...r.if }, art: r.art, title: r.title, text: r.text,
  choices: [
    R(r.go[0], r.go[1], r.go[2], r.go[3], r.go[4]),
    C(r.alt[0], r.alt[1]),
    C('Leave history as it lies', O('You left it. Some knowledge is better kept than spent.')),
  ],
}));

// ── Template: off the cliff and into a secret valley ─────────────
// The fall always costs something. Explore the valley (a roll), get out at once, or, in a later life,
// go straight to what you found the last time you fell.
const ABYSS = [
  { key: 'mounthua', loc: 'mounthua', fall: 15, art: 'blossom', title: 'Through the clouds', text: 'On Mount Hua’s plank walkway, nailed to a sheer cliff, a rotten plank snaps. You fall through cloud, through pine branches, into a deep snowbank. When you dig yourself out you are in a valley of plum trees in full bloom, out of all season.',
    explore: ['Explore the plum valley', 'insight', 35, O('At the heart of the valley, a hermit’s grave, and on the stone a sword form carved as petals falling: the Plum Blossom Sword, older and stranger than Mount Hua teaches it. You learned it before you found the way out.', { manual: 'hua_plum_sword', mastery: { hua_plum_sword: 15 } }), O('You wandered among the plums until you were dizzy with the scent, found a goat path out, and nothing else.', { sanity: 3 })],
    out: ['Find the way out at once', O('You followed the stream down and out in two days. You have never been able to find the valley from above.', { body: 1 })],
    codex: ['The plum valley below the walkway', 'Below a rotten plank on Mount Hua’s cliff walkway is a valley of plums that bloom out of season. A hermit’s grave there bears the Plum Blossom Sword in its oldest form.'],
    mem: ['Go straight to the hermit’s grave', O('Straight to the grave. You bowed to it like an old friend this time, and the petals on the stone seemed to fall more slowly.', { manual: 'hua_plum_sword', mastery: { hua_plum_sword: 25 }, gaze: 1 })] },
  { key: 'kongtong', loc: 'kongtong', fall: 20, art: 'mountain', title: 'A wind-scoured drop', text: 'A gust on Mount Kongtong plucks you off a ridge like a leaf. You fall a long way, bounce off a ledge, and land in a pool of warm red water at the bottom of a hidden gorge.',
    explore: ['Soak in the red pool', 'health', 45, O('The red came from iron in the rock, and something older in the water. You soaked for a week. When you climbed out, your bones felt reforged.', { body: 4, health: 15 }), O('The water was too hot for too long. You climbed out scalded and lightheaded.', { health: -10 })],
    out: ['Climb out before dark', O('You climbed out before dark, bruised and grateful.', { body: 1 })],
    codex: ['The red pool of Kongtong', 'A hidden gorge below a Kongtong ridge holds a warm pool of iron-red water that tempers the bones. Soak only at night, when it cools.'],
    mem: ['Soak only at night, when it cools', O('You knew to soak at night. A week of nights, and your bones rang like bronze when you struck them.', { body: 5, health: 20 })] },
  { key: 'wudang', loc: 'wudang', fall: 12, art: 'river', title: 'The tortoise beach', text: 'Mist on the Wudang paths hides a drop. You fall into a river, are carried through a gorge, and wash up on a shingle beach where a hundred tortoises are sunning themselves in perfect silence.',
    explore: ['Sit with the tortoises', 'sanity', 50, O('You sat with them for a month, breathing as slowly as they did. When you left you were calmer than you had been in years, and your qi moved at the speed of patience.', { sanity: 10, qi: 20, flag: 'longevity+=1' }), O('You fidgeted. The tortoises regarded you with ancient disappointment.', { sanity: -2 })],
    out: ['Follow the river out', O('You followed the river out. The tortoises did not watch you go. They had seen people leave before.')],
    codex: ['The tortoise beach', 'Below the misty Wudang paths, a river gorge ends at a beach where a hundred tortoises sun themselves. Sit with them a season and your qi slows to their pace, and your life lengthens.'],
    mem: ['Bring them greens and stay the season', O('You brought greens, which they accepted with dignity, and stayed the whole season. They seemed to remember you, though they could not have.', { sanity: 12, qi: 25, flag: 'longevity+=2' })] },
  { key: 'emei', loc: 'emei', fall: 15, art: 'mountain', title: 'Below the sea of clouds', text: 'Pilgrims on Emei’s Golden Summit lean out to see the sea of clouds. You lean too far. You fall into the clouds and through them, and land in the crown of a vast tree in a valley where it is always dawn.',
    explore: ['Climb down and explore', 'insight', 40, O('At the foot of the tree stood a ring of stone seats, each carved with a line of a sutra. Read in a circle, they were a method of breathing with the light.', { qi: 25, insight: 3, sanity: 5 }), O('You climbed down the tree and found only birds, and a path out that took a week.', { health: -5 })],
    out: ['Shout for help from the treetop', O('Emei nuns lowered a rope at dusk. They had clearly done it before. They did not seem to think much of you.', { rep: { orthodox: -1 } })],
    codex: ['The valley of dawn', 'Below Emei’s Golden Summit, through the sea of clouds, is a valley where it is always dawn. A ring of stone seats bears a sutra of breathing with the light. Read it clockwise.'],
    mem: ['Read the seats clockwise this time', O('Clockwise, the sutra opened like a flower. You sat in the endless dawn until it was in your bones.', { qi: 30, insight: 4, sanity: 6 })] },
  { key: 'diancang', loc: 'diancang', fall: 15, art: 'cave', title: 'The serpent’s ledge', text: 'On Mount Diancang a ledge crumbles and drops you thirty feet onto another ledge, which has a cave on it, which has a very large snake in it, coiled around an egg the size of your head.',
    explore: ['Hold still until the snake goes hunting', 'sanity', 45, O('You waited all day, perfectly still, until it slid out to hunt. You did not touch the egg. You took the old shed skins from the back of the cave, which a physician later told you were worth more than a house.', { wealth: 90 }), O('You twitched. The snake struck. You left the ledge the fast way.', { health: -15, injury: { name: 'snakebite', seasons: 3, sev: 8 } })],
    out: ['Climb up and away', O('You climbed away very carefully, keeping your eyes on the egg, and the snake keeping its eyes on you.', { body: 1 })],
    codex: ['The serpent’s ledge', 'Below a crumbling ledge on Mount Diancang a great snake guards its egg in a cave full of old shed skins worth a fortune to physicians. It will trade them for a live chicken.'],
    mem: ['Bring a live chicken for the snake', O('The snake took the chicken and ignored you. You took the shed skins, each worth a small fortune.', { wealth: 120 })] },
  { key: 'taihang', loc: 'taihang', fall: 15, art: 'grave', title: 'The bandits’ ravine', text: 'Fleeing a Green Forest patrol, you take a goat path in the Taihang, and the goat path ends. You fall into a narrow ravine where the bandits throw their dead, and something down here is still alive.',
    explore: ['Find whoever is alive', 'insight', 35, O('A bandit, left for dead by his own brothers, with a broken leg and a grudge. You splinted his leg; he showed you the ravine’s back way out, and the purses the dead had been carrying.', { wealth: 40, rep: { unorthodox: 3 } }), O('It was a wolf. It was not interested in being found.', { health: -10 })],
    out: ['Climb out the way you came, fast', O('You climbed out faster than you would have believed possible, and did not look down again.', { body: 1 })],
    codex: ['The bandits’ ravine', 'In the Taihang a goat path ends above a ravine where the Green Forest throws its dead. A bandit left for dead lies there with a broken leg; he knows the back way out and where the dead men’s purses are.'],
    mem: ['Bring splints and food for the man you know is there', O('He wept to see a stranger with food. He showed you the back way, the purses and, later, as a sworn brother of the Green Forest, a great many other things.', { wealth: 50, rep: { unorthodox: 8 } })] },
  { key: 'zhongnan', loc: 'zhongnan', fall: 10, art: 'cave', title: 'The hermit’s tea room', text: 'The ground on Mount Zhongnan opens under you without warning into a dry, stone-lined shaft, and you slide into a round room where a hermit’s skeleton sits at a table with two cups set out for tea.',
    explore: ['Sit and pour the tea', 'sanity', 45, O('You poured. The tea leaves were dust. You drank the dust anyway, out of politeness, and the room rewarded you: a passage opened in the wall, and in it a small shelf of pills, still sealed.', { item: { foundation_pill: 1, qi_pill: 1 }, sanity: 3 }), O('You poured, and the skeleton’s head fell off. You left by the shaft, very quickly.', { sanity: -5 })],
    out: ['Climb the shaft', O('You climbed the shaft, bracing against the stone. At the top you found a grave marker that read: "Visitors welcome. Stay for tea." You did not go back.')],
    codex: ['The hermit’s tea room', 'A hidden shaft on Mount Zhongnan drops into a hermit’s round room with tea set for two. Pour the tea politely and a passage opens to his pills. His recipe is under the cup.'],
    mem: ['Pour the tea and bow to your host', O('You poured and bowed. The passage opened. This time you also found the note under the cup: a recipe.', { item: { foundation_pill: 1, qi_pill: 1 }, recipe: 'foundation_pill', sanity: 3 })] },
  { key: 'qingcheng', loc: 'qingcheng', fall: 12, art: 'forest', title: 'The green sinkhole', text: 'A rope bridge on Mount Qingcheng snaps beneath you. You fall into the green and land in a sinkhole of soft moss, ringed by cliffs, where the air is so thick with qi it is almost wet.',
    explore: ['Meditate where you landed', 'sanity', 50, O('You meditated for a season, eating mushrooms and drinking dew. When you climbed out your dantian was so full it ached pleasantly.', { qiFill: 40 }), O('The qi was too thick to breathe in a straight line. You choked on it, and came out a season later with a strange cough.', { qi: 15, health: -8 })],
    out: ['Climb the cliffs out', O('It took a week of climbing. At the top a Qingcheng disciple was mending the bridge, and did not look surprised.', { body: 2 })],
    codex: ['The green sinkhole', 'Below the old rope bridge on Mount Qingcheng is a mossy sinkhole thick with qi. Breathe slowly, in time with the moss; forcing it will choke you.'],
    mem: ['Breathe in time with the moss', O('Slowly, in time with the moss. A season, and your dantian full and quiet.', { qiFill: 50, sanity: 4 })] },
  { key: 'kunlun', loc: 'kunlun', fall: 18, if: { realm: '>=1' }, art: 'snow', title: 'A crevasse', text: 'A snow bridge gives way and you drop into a blue crevasse in the Kunlun glacier, and keep sliding, down and down, until you shoot out into a hidden valley where hot springs steam among green grass.',
    explore: ['Follow the hot springs to their source', 'body', 40, O('The source was a cave of crystal, humming with qi. You sat in the hottest pool until your meridians opened like flowers, and every old hurt in you let go.', { qi: 30, health: 10, cure: 'injuries' }), O('The hottest pool was too hot. You learned that with your feet.', { health: -10 })],
    out: ['Find a way back up', O('The valley had a way out, a long one, through ice tunnels. You came out weeks later near the Kunlun Sect, which did not believe a word of it.', { body: 1 })],
    codex: ['The hot valley in the glacier', 'Under the Kunlun glacier, a crevasse slide ends in a hidden valley of hot springs. Their source is a crystal cave that hums with qi, strongest at moonrise.'],
    mem: ['Wait in the crystal cave for moonrise', O('At moonrise the crystal sang, and your qi sang with it.', { qiFill: 40, health: 15, cure: 'injuries' })] },
];
const tplAbyss = template('fo_abyss', ABYSS, (r) => {
  const fall = { fx: { health: -r.fall } };
  const id = `secret.fo_abyss_${r.key}`;
  return E('fo_abyss', 'fortune', {
    if: { loc: r.loc, age: [12, 60], stat: { health: '>=45' }, chance: 0.25, ...r.if }, danger: true, art: r.art, title: r.title, text: r.text,
    choices: [
      R(r.explore[0], r.explore[1], r.explore[2], { ...r.explore[3], codex: cx(id, 'secrets', r.codex) }, r.explore[4], fall),
      C(r.out[0], r.out[1], fall),
      M(r.mem[0], id, r.mem[1], fall),
    ],
  });
});

// ── Template: marks left by the great ────────────────────────────
// Footprints, sword cuts and inscriptions that teach whoever can read them. Mastery goes to whichever of
// the listed arts you already know.
const STELES = [
  { key: 'footprints', loc: 'songshan', realm: '>=0', art: 'temple', title: 'Footprints in the flagstone', text: 'On a flagstone in a Shaolin courtyard two footprints are worn an inch deep, where a monk stood practising the same stance for forty years. Novices are told not to stand in them. Novices always do.',
    study: ['Stand in them, and stay', 40, O('You stood until you understood why he stood. Your stance roots now like an old tree.', { body: 2, insight: 2, mastery: { shao_arhat: 20, fist_basic: 20, shao_bell: 15, wu_taiji_fist: 15 } }), O('You stood until your legs gave out. A novice laughed at you, and you laughed too.', { body: 1 })],
    alt: ['Sweep around them', O('You swept around them, respectfully. An old monk watching you nodded.', { rep: { orthodox: 1 } })] },
  { key: 'petal_wall', loc: 'mounthua', art: 'mountain', title: 'The Wall of Petals', text: 'On the Lotus Peak a sheer rock face is scored with sword marks in the shape of falling plum blossoms, cut by a Mount Hua master centuries ago in a single afternoon. The disciples call it the Wall of Petals.',
    study: ['Trace the cuts with your eyes', 45, O('You traced the cuts until your sword hand began to twitch in time. The petals were not falling. They were being cut.', { insight: 3, mastery: { hua_plum_sword: 25, sword_basic: 20, nam_emperor_sword: 10 } }), O('All you saw were scratches. Pretty scratches.', { insight: 1 })],
    alt: ['Cut a petal of your own', O('Your cut was a scratch beside theirs. You were oddly proud of it anyway.', { sanity: 2, body: 1 })] },
  { key: 'taiji_terrace', loc: 'wudang', art: 'temple', title: 'The Taiji terrace', text: 'At the Golden Summit of Wudang a great Taiji diagram is carved into the floor of an old terrace, worn smooth by centuries of feet walking it in circles.',
    study: ['Walk it until you stop walking', 45, O('Round and round, until your feet were walking you, and then something else was. When you stopped, a Daoist was watching you with interest.', { insight: 4, qi: 10, mastery: { wu_taiji_fist: 20, wu_taiji_sword: 20, wu_ladder: 10 } }), O('You walked it until you were dizzy and sat down hard in the black half.', { insight: 1 })],
    alt: ['Watch the Daoists walk it', O('You watched for a morning. They moved like water poured slowly.', { sanity: 3 })] },
  { key: 'glacier_cut', loc: 'kunlun', realm: '>=3', art: 'snow', title: 'The glacier scar', text: 'A single straight cut runs a li across the Kunlun glacier, perfectly clean, as if the ice had been sliced by a sword the size of a mountain. Kunlun says the Sword Saint did it. The Sword Saint, when asked, says he was drunk.',
    study: ['Stand at the end of the cut until you feel it', 60, O('You stood there for days until you felt it: not the force, but the intent, the decision behind the cut. You will never be the same with a sword.', { insight: 5, mastery: { lost_formless_sword: 15, lost_sword_saint: 15, kun_cloud_sword: 20, sword_basic: 20 } }), O('You stood at the end of the cut until your toes froze. It was a very long, very straight crack in the ice.', { health: -5 })],
    alt: ['Measure it, for the record', O('A li and a quarter. You wrote it down. Nobody has ever asked you.', { insight: 1 })] },
  { key: 'duel_stone', loc: 'namgung', art: 'lake', title: 'The duel on the lake stone', text: 'On a stone in the lake behind the Namgung Estate are the marks of a duel two Namgung ancestors fought over a woman three centuries ago. They killed each other. The woman married someone else. The marks are magnificent.',
    study: ['Read the duel from the first cut', 40, O('Two swords, two styles, a hundred exchanges in the stone. You read the duel from beginning to end and understood how either of them could have won.', { insight: 3, mastery: { nam_emperor_sword: 25, nam_heaven_thunder: 15, sword_basic: 15 } }), O('You read the first ten exchanges and lost track. So, you suspect, did they.', { insight: 1 })],
    alt: ['Ask what happened to the woman', O('A Namgung servant told you she became a famous poet. Her poems about the duel are rude.', { charm: 1, sanity: 2 })] },
  { key: 'alliance_stele', loc: 'luoyang', realm: '>=0', art: 'city', title: 'The Alliance stele', text: 'Outside the Murim Alliance hall in Luoyang stands a stele carved with the names of every hero who died for the Orthodox cause. Some names have been chiselled out. An old caretaker polishes the empty spaces with special care.',
    study: ['Ask the caretaker about the empty spaces', 35, O('Heroes who later became inconvenient. He knew every name, and recited them for you. Some of them were the best of all.', { insight: 3, codex: { id: 'secret.fo_erased_names', cat: 'secrets', title: 'The erased names', text: 'The names chiselled off the Alliance stele in Luoyang belong to heroes who became inconvenient. The old caretaker remembers them all.' } }), O('He looked at you, decided something, and polished on in silence.')],
    alt: ['Read the names that remain', O('So many names. You read until the light went, and left a little heavier.', { sanity: -2, fame: 1 })] },
  { key: 'spear_poem', loc: 'jadegate', realm: '>=0', art: 'desert', title: 'The general’s poem', text: 'On the wall of the Jade Gate fortress a general carved a poem three hundred years ago with the tip of his spear: eight lines about the moon over the desert, and the friends who would never see it again.',
    study: ['Read the strokes, not the words', 35, O('In the strokes you saw his spear moving: thrust, sweep, return, as if he had fought the wall. The poem was also a lesson.', { insight: 2, sanity: 2, mastery: { escort_spear: 25, shao_staff: 15, beg_staff: 15 } }), O('It was a sad poem. That was all you saw in it, and it was enough.', { sanity: -1, charm: 1 })],
    alt: ['Copy the poem and send it home', O('You copied it and sent it home. It is, you are told, still on the wall of your family’s kitchen.', { charm: 1 })] },
  { key: 'split_boulder', loc: 'dongting', art: 'lake', title: 'The split boulder', text: 'In the middle of Lake Dongting a boulder rises from the water, split cleanly in two. Fishermen say a swordsman cut it while standing on a reed. The halves have drifted a finger’s width apart in a hundred years.',
    study: ['Stand on a reed and look', 50, O('You did not manage to stand on a reed. You did manage, waist-deep and soaked, to see how the cut began: with the feet, not the hand.', { insight: 3, body: 1, mastery: { lost_formless_sword: 10, sword_basic: 20, emei_sword: 15, uno_water_palm: 15 } }), O('You fell off a great many reeds. The fishermen enjoyed it enormously.', { health: -3, charm: 1 })],
    alt: ['Row between the halves', O('You rowed through the gap. It was just wide enough. Something about that pleased you all day.', { sanity: 3 })] },
  { key: 'thousand_buddhas', loc: 'emei', art: 'shrine', title: 'The thousand-Buddha cliff', text: 'On Emei a cliff is carved with a thousand small Buddhas, each making a different gesture. A nun tells you every gesture is a technique, if you have the eyes for it, and then that you probably do not.',
    study: ['Look until the hands move', 45, O('You looked for a month, until the hands began to move in your mind. Some blessed. Some, very gently, broke wrists.', { insight: 4, mastery: { emei_sword: 15, emei_needles: 20, shao_tathagata: 10, moy_return_art: 15 } }), O('A thousand stone hands, and not one of them would explain itself.', { insight: 1 })],
    alt: ['Light incense', O('You lit incense. A thousand stone faces looked at you kindly, or at least did not look away.', { sanity: 4 })] },
  { key: 'demon_hand', loc: 'tenthousand', realm: '>=0', art: 'demonic', title: 'The Heavenly Demon’s handprint', text: 'On a black cliff in the Ten Thousand Mountains a handprint is sunk a foot deep into the rock: the first Heavenly Demon’s, the Cult says. Believers press their palms into it. Some are never quite the same afterward.',
    study: ['Press your palm into it', 50, O('The stone was warm. For one heartbeat you felt what he felt: everything, wanting. You took your hand away before the heartbeat ended, and kept what he taught you.', { insight: 3, qi: 15, sanity: -6, mastery: { cult_demon_palm: 25, cult_blood_art: 15, kun_snow_palm: 10 } }), O('The stone was warm. You kept your hand there too long. For a month afterward you were very hungry, for things that are not food.', { sanity: -12, qi: 10 })],
    alt: ['Watch the believers instead', O('You watched them come and go. Some wept. Some laughed. One small girl pressed her hand in, frowned, and said, "It is just a hole." You liked her best.', { insight: 1, sanity: 2 })] },
];
const tplStele = template('fo_stele', STELES, (r) => E('fo_stele', 'fortune', {
  if: { loc: r.loc, age: [10, 150], realm: r.realm || '>=1', chance: 0.3 }, art: r.art, title: r.title, text: r.text,
  choices: [R(r.study[0], 'insight', r.study[1], r.study[2], r.study[3]), C(r.alt[0], r.alt[1])],
}));

export default [
  ...HAND,
  ...tplCave, ...tplDying, ...tplHerb, ...tplRuin, ...tplOmen, ...tplTeahouse, ...tplTomb,
  ...tplMap, ...tplBeast, ...tplCurse, ...tplFated, ...tplRecall, ...tplAbyss, ...tplStele,
];
